CREATE OR REPLACE FUNCTION private.reconcile_retell_generation(p_turn uuid, p_request bigint, p_event uuid, p_note text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
DECLARE t public.retell_api_turns; s public.retell_api_sessions; proof jsonb; payload jsonb;
 history jsonb; candidate jsonb; messages jsonb;
BEGIN
 IF length(trim(coalesce(p_note,''))) NOT BETWEEN 20 AND 1000 THEN RAISE EXCEPTION 'Operator note required'; END IF;
 SELECT * INTO t FROM public.retell_api_turns WHERE id=p_turn;
 IF NOT FOUND THEN RAISE EXCEPTION 'Missing exact turn'; END IF;
 SELECT * INTO s FROM public.retell_api_sessions WHERE id=t.session_id;
 PERFORM pg_advisory_xact_lock(hashtextextended('seller-outreach:'||s.phone_number,0));
 PERFORM 1 FROM public.retell_form_sms_jobs WHERE id=s.id FOR UPDATE;
 SELECT * INTO s FROM public.retell_api_sessions WHERE id=t.session_id FOR UPDATE;
 SELECT * INTO t FROM public.retell_api_turns WHERE id=p_turn FOR UPDATE;
 IF s.status<>'review' OR t.status<>'review' OR t.generated_messages IS NOT NULL OR t.outbound_id IS NOT NULL
  OR s.chat_id IS NULL
  OR EXISTS(SELECT 1 FROM private.retell_generation_reconciliations WHERE turn_id=t.id)
  OR (SELECT count(*) FROM public.retell_api_turns WHERE session_id=s.id)<>1
  OR EXISTS(SELECT 1 FROM public.sms_events WHERE raw_payload->>'api_turn_id'=t.id::text)
  OR NOT EXISTS(SELECT 1 FROM public.retell_form_sms_jobs WHERE id=s.id AND status='accepted' AND delivery_transport='app_twilio')
  OR NOT EXISTS(SELECT 1 FROM public.sms_events WHERE id=s.id AND status IN ('delivered','read'))
  OR NOT EXISTS(SELECT 1 FROM public.leads WHERE id=s.lead_id AND dnc IS FALSE AND status NOT IN ('dnc','dead','closed','sold','under_contract'))
  OR coalesce(public.intake_phone_status(s.phone_number,s.lead_id,'')->>'suppressed','true')<>'false'
 THEN RAISE EXCEPTION 'Turn has unresolved, expired, suppressed or non-first-turn evidence'; END IF;
 SELECT content::jsonb INTO proof FROM net._http_response WHERE id=p_request AND status_code=200
   AND timed_out IS FALSE AND created>=now()-interval '5 minutes';
 IF proof IS NULL OR proof->>'status' IS DISTINCT FROM 'inspected'
  OR proof->'dispatch_authorized' IS DISTINCT FROM 'false'::jsonb
  OR proof->>'session_id' IS DISTINCT FROM s.id::text OR proof->>'chat_id' IS DISTINCT FROM s.chat_id
  OR NOT coalesce(proof->'checks' @> '{"chat_id":true,"chat_type":true,"agent_id":true,"metadata":true,"ongoing":true,"pinned_version_valid":true}'::jsonb,false)
  OR jsonb_typeof(proof->'first_turn_proof') IS DISTINCT FROM 'object'
 THEN RAISE EXCEPTION 'Fresh authenticated first-turn inspection required'; END IF;
 SELECT w.payload INTO payload FROM public.webhook_jobs w WHERE id=p_event AND source='retell_api_chat' AND status='done';
 IF payload IS NULL OR payload->>'event' IS DISTINCT FROM 'transcript_updated'
  OR payload->'chat'->>'chat_id' IS DISTINCT FROM s.chat_id
  OR payload->'chat'->>'chat_type' IS DISTINCT FROM 'api_chat'
  OR payload->'chat'->>'agent_id' IS DISTINCT FROM s.agent_id
  OR payload->'chat'->'agent_version' IS DISTINCT FROM to_jsonb(s.agent_version)
  OR payload->'chat'->'metadata' IS DISTINCT FROM jsonb_build_object('operation_id',s.id,'lead_id',s.lead_id,'transport','wholesaleos_twilio')
 THEN RAISE EXCEPTION 'Authenticated event identity mismatch'; END IF;
 history:=payload->'transcript_with_tool_calls'; candidate:=history->1;
 IF jsonb_typeof(history) IS DISTINCT FROM 'array' OR jsonb_array_length(history)<>2
  OR history->0->>'role' IS DISTINCT FROM 'user' OR history->0->>'content' IS DISTINCT FROM t.recipient_text
  OR candidate->>'role' IS DISTINCT FROM 'agent'
  OR jsonb_typeof(candidate->'content') IS DISTINCT FROM 'string'
  OR length(trim(candidate->>'content')) NOT BETWEEN 1 AND 99
  OR candidate->>'content' ~ '[[:cntrl:]]'
  OR coalesce(candidate->>'message_id','') !~ '^[A-Za-z0-9_-]{1,128}$'
  OR candidate->>'message_id'=history->0->>'message_id'
  OR (candidate ? 'multimedia' AND candidate->'multimedia' NOT IN ('null'::jsonb,'[]'::jsonb))
  OR proof->'first_turn_proof' IS DISTINCT FROM jsonb_build_object(
   'user_message_id',history->0->>'message_id',
   'recipient_sha256',encode(sha256(convert_to(t.recipient_text,'UTF8')),'hex'),
   'message_id',candidate->>'message_id',
   'content_sha256',encode(sha256(convert_to(candidate->>'content','UTF8')),'hex'))
 THEN RAISE EXCEPTION 'Transcript is ambiguous, unsafe or does not match live proof'; END IF;
 messages:=jsonb_build_array(jsonb_build_object('message_id',candidate->>'message_id','content',candidate->>'content'));
 INSERT INTO private.retell_generation_reconciliations(turn_id,session_id,request_id,event_id,messages,before_state,proof,note)
 VALUES(t.id,s.id,p_request,p_event,messages,jsonb_build_object('turn',to_jsonb(t),'session',to_jsonb(s)),proof,p_note);
 UPDATE public.retell_api_sessions SET status='ready',reason='Existing generated reply verified; no completion replay' WHERE id=s.id;
 UPDATE public.retell_api_turns SET status=CASE WHEN t.expires_at>now() THEN 'generated' ELSE 'stopped' END,generated_messages=messages,
  reason='Existing provider reply verified; expired input stopped without sending; no regeneration' WHERE id=t.id;
 UPDATE private.retell_generation_reconciliations SET applied_at=now() WHERE turn_id=t.id;
 RETURN jsonb_build_object('reconciled',true,'turn_id',t.id,'turn_status',CASE WHEN t.expires_at>now() THEN 'generated' ELSE 'stopped' END,'dispatch_authorized',false);
END $function$

CREATE OR REPLACE FUNCTION private.tick_retell_app_sms()
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
DECLARE c private.retell_app_scheduler; bearer text; rid bigint; response record; response_body jsonb;
BEGIN
 SELECT * INTO c FROM private.retell_app_scheduler WHERE singleton FOR UPDATE;
 IF NOT FOUND OR NOT c.enabled THEN RETURN jsonb_build_object('status','disabled','requested',false); END IF;
 IF EXISTS(SELECT 1 FROM private.retell_sms_scheduler WHERE enabled) THEN
  UPDATE private.retell_app_scheduler SET last_state='native_scheduler_enabled' WHERE singleton;
  RETURN jsonb_build_object('status','native_scheduler_enabled','requested',false); END IF;
 IF c.last_request_id IS NOT NULL THEN
  SELECT * INTO response FROM net._http_response WHERE id=c.last_request_id;
  IF NOT FOUND THEN
   IF c.last_requested_at>now()-interval '90 seconds' THEN RETURN jsonb_build_object('status','in_flight','requested',false); END IF;
   UPDATE private.retell_app_scheduler SET enabled=false,last_state='worker_http_unconfirmed' WHERE singleton;
   RETURN jsonb_build_object('status','worker_http_unconfirmed','requested',false); END IF;
  IF response.status_code IS DISTINCT FROM 200 OR response.timed_out IS DISTINCT FROM false THEN
   UPDATE private.retell_app_scheduler SET enabled=false,last_state='worker_http_failed',last_http_status=response.status_code WHERE singleton;
   RETURN jsonb_build_object('status','worker_http_failed','requested',false); END IF;
  BEGIN response_body:=response.content::jsonb;
  EXCEPTION WHEN invalid_text_representation THEN response_body:=NULL; END;
  IF coalesce(response_body->>'status','') NOT IN ('processed','idle','deferred') THEN
   UPDATE private.retell_app_scheduler SET enabled=false,last_state='worker_disabled_or_invalid',last_http_status=200 WHERE singleton;
   RETURN jsonb_build_object('status','worker_disabled_or_invalid','requested',false); END IF;
  -- A completed HTTP receipt no longer needs to remain in pg_net's short-lived
  -- response store. Retain it in our diagnostic columns, not as an in-flight lock.
  UPDATE private.retell_app_scheduler SET last_request_id=NULL,last_state='idle',last_http_status=200 WHERE singleton;
 END IF;
 -- Contact hours are rechecked by the application immediately before providers.
 -- This guard avoids background HTTP traffic outside the configured launch window.
 IF extract(hour FROM now() AT TIME ZONE 'America/Chicago')<c.start_hour
  OR extract(hour FROM now() AT TIME ZONE 'America/Chicago')>=c.end_hour THEN
  RETURN jsonb_build_object('status','outside_contact_hours','requested',false); END IF;
 IF NOT EXISTS(SELECT 1 FROM public.retell_form_sms_jobs WHERE delivery_transport='app_twilio'
    AND status='scheduled' AND due_at<=now() AND expires_at>now()
    AND (auto_selected_at IS NULL OR auto_selected_at<=now()-interval '90 seconds'))
  AND NOT EXISTS(SELECT 1 FROM public.retell_api_turns t JOIN public.retell_api_sessions s ON s.id=t.session_id
    WHERE t.status IN ('queued','generated') AND s.status IN ('pending','ready') AND t.expires_at>now()
    AND (t.auto_selected_at IS NULL OR t.auto_selected_at<=now()-interval '90 seconds')) THEN
  RETURN jsonb_build_object('status','idle','requested',false); END IF;
 SELECT decrypted_secret INTO bearer FROM vault.decrypted_secrets WHERE name='retell_sms_worker_bearer';
 IF coalesce(bearer,'')='' THEN
  UPDATE private.retell_app_scheduler SET last_state='missing_worker_credential' WHERE singleton;
  RETURN jsonb_build_object('status','missing_worker_credential','requested',false); END IF;
 SELECT net.http_post(url:='https://wholesale-automation.vercel.app/webhooks/_worker/retell-app/automatic',
  body:='{}'::jsonb,headers:=jsonb_build_object('Authorization','Bearer '||bearer,'Content-Type','application/json'),
  timeout_milliseconds:=60000) INTO rid;
 UPDATE private.retell_app_scheduler SET last_request_id=rid,last_requested_at=now(),last_state='requested',last_http_status=NULL WHERE singleton;
 RETURN jsonb_build_object('status','requested','requested',true,'request_id',rid);
END $function$

CREATE OR REPLACE FUNCTION private.tick_retell_sms()
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
DECLARE c private.retell_sms_scheduler; bearer text; bypass text; headers jsonb; rid bigint;
BEGIN
  SELECT * INTO c FROM private.retell_sms_scheduler WHERE singleton FOR UPDATE;
  IF NOT FOUND OR NOT c.enabled THEN
    RETURN jsonb_build_object('status','disabled','requested',false);
  END IF;
  SELECT decrypted_secret INTO bearer FROM vault.decrypted_secrets WHERE name='retell_sms_worker_bearer';
  IF coalesce(bearer,'')='' THEN
    RETURN jsonb_build_object('status','missing_worker_credential','requested',false);
  END IF;
  headers := jsonb_build_object('Authorization','Bearer '||bearer);
  IF c.endpoint LIKE 'https://wholesale-automation-git-%' THEN
    SELECT decrypted_secret INTO bypass FROM vault.decrypted_secrets WHERE name='retell_sms_preview_bypass';
    IF coalesce(bypass,'')='' THEN
      RETURN jsonb_build_object('status','missing_preview_access','requested',false);
    END IF;
    headers := headers || jsonb_build_object('x-vercel-protection-bypass',bypass);
  END IF;
  -- Avoid overlapping HTTP workers. A crash cannot make the same processing job
  -- eligible again; the application moves ambiguous attempts to review.
  IF c.last_request_id IS NOT NULL AND c.last_requested_at > now()-interval '90 seconds'
     AND NOT EXISTS (SELECT 1 FROM net._http_response WHERE id=c.last_request_id) THEN
    RETURN jsonb_build_object('status','in_flight','requested',false);
  END IF;
  IF NOT EXISTS (SELECT 1 FROM public.retell_form_sms_jobs
                   WHERE status='scheduled' AND due_at<=now())
     AND NOT EXISTS (SELECT 1 FROM public.retell_form_sms_jobs
                   WHERE status='processing' AND claimed_at<now()-interval '5 minutes') THEN
    RETURN jsonb_build_object('status','idle','requested',false);
  END IF;
  SELECT net.http_get(url:=c.endpoint, headers:=headers, timeout_milliseconds:=60000) INTO rid;
  UPDATE private.retell_sms_scheduler SET last_request_id=rid,last_requested_at=now() WHERE singleton;
  RETURN jsonb_build_object('status','requested','requested',true,'request_id',rid);
END; $function$

CREATE OR REPLACE FUNCTION public.admin_set_user_role(target_user_id uuid, new_role text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
BEGIN
  IF NOT private.is_approved_admin() THEN
    RAISE EXCEPTION 'Unauthorized: approved admin role required';
  END IF;
  UPDATE public.profiles SET role = new_role WHERE id = target_user_id;
END;
$function$

CREATE OR REPLACE FUNCTION public.apply_list_scoring_operation(p_id uuid, p_operator uuid, p_action text, p_payload jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
DECLARE event wholesale_ingest.scoring_operator_events; config wholesale_ingest.settings; job wholesale_ingest.scoring_jobs; response jsonb; result jsonb;
BEGIN
 IF NOT EXISTS(SELECT 1 FROM public.profiles WHERE id=p_operator AND role='admin' AND status='approved') THEN RAISE EXCEPTION 'Approved administrator required'; END IF;
 IF p_id IS NULL OR p_action NOT IN ('threshold','complete_received') OR p_action IS NULL OR jsonb_typeof(p_payload) IS DISTINCT FROM 'object' THEN RETURN jsonb_build_object('blocked','invalid_action'); END IF;
 PERFORM pg_advisory_xact_lock(hashtextextended('scoring-operator:'||p_id::text,0));
 SELECT * INTO event FROM wholesale_ingest.scoring_operator_events WHERE id=p_id;
 IF FOUND THEN
  IF event.operator_id IS DISTINCT FROM p_operator OR event.action IS DISTINCT FROM p_action OR event.payload IS DISTINCT FROM p_payload THEN RETURN jsonb_build_object('blocked','reference_conflict'); END IF;
  RETURN jsonb_build_object('event',to_jsonb(event),'replayed',true);
 END IF;
 IF p_action='threshold' THEN
  IF p_payload-ARRAY['expected_version','score_threshold']<>'{}'::jsonb
  OR jsonb_typeof(p_payload->'expected_version') IS DISTINCT FROM 'number' OR coalesce(p_payload->>'expected_version','') !~ '^[1-9][0-9]{0,8}$'
  OR jsonb_typeof(p_payload->'score_threshold') IS DISTINCT FROM 'number' OR coalesce(p_payload->>'score_threshold','') !~ '^[0-9]{1,3}$'
  OR (p_payload->>'score_threshold')::int>100 THEN RETURN jsonb_build_object('blocked','invalid_threshold'); END IF;
  SELECT * INTO config FROM wholesale_ingest.settings WHERE singleton FOR UPDATE;
  IF NOT FOUND THEN RETURN jsonb_build_object('blocked','settings_missing'); END IF;
  IF config.score_settings_version<>(p_payload->>'expected_version')::int THEN RETURN jsonb_build_object('blocked','version_conflict'); END IF;
  UPDATE wholesale_ingest.settings SET score_threshold=(p_payload->>'score_threshold')::int,score_settings_version=score_settings_version+1 WHERE singleton RETURNING * INTO config;
  result:=jsonb_build_object('score_threshold',config.score_threshold,'version',config.score_settings_version);
 ELSE
  IF p_payload-ARRAY['job_id']<>'{}'::jsonb OR coalesce(p_payload->>'job_id','') !~ '^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}$' THEN RETURN jsonb_build_object('blocked','invalid_job'); END IF;
  SELECT * INTO job FROM wholesale_ingest.scoring_jobs WHERE id=(p_payload->>'job_id')::uuid FOR UPDATE;
  IF NOT FOUND OR job.state NOT IN ('received','completed') THEN RETURN jsonb_build_object('blocked','saved_response_required'); END IF;
  response:=public.complete_list_score_job(job.id);
  result:=jsonb_build_object('job_id',job.id,'state',response#>>'{job,state}','evaluation_id',response#>>'{evaluation,id}','blocked',response->>'blocked');
 END IF;
 INSERT INTO wholesale_ingest.scoring_operator_events(id,operator_id,action,payload,result) VALUES(p_id,p_operator,p_action,p_payload,result) RETURNING * INTO event;
 RETURN jsonb_build_object('event',to_jsonb(event),'replayed',false);
END $function$

CREATE OR REPLACE FUNCTION public.bind_retell_api_session(p_turn uuid, p_chat text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
DECLARE t public.retell_api_turns; s public.retell_api_sessions;
BEGIN
 IF coalesce(p_chat,'') !~ '^[A-Za-z0-9_-]{1,128}$' THEN RAISE EXCEPTION 'Invalid API chat identity'; END IF;
 SELECT * INTO t FROM public.retell_api_turns WHERE id=p_turn;
 IF NOT FOUND THEN RAISE EXCEPTION 'Missing turn'; END IF;
 SELECT * INTO s FROM public.retell_api_sessions WHERE id=t.session_id FOR UPDATE;
 SELECT * INTO t FROM public.retell_api_turns WHERE id=p_turn FOR UPDATE;
 IF s.status='ready' AND s.chat_id=p_chat AND t.status='generating' THEN RETURN jsonb_build_object('bound',true,'replayed',true); END IF;
 IF s.status<>'creating' OR s.chat_id IS NOT NULL OR t.status<>'creating_session' THEN RAISE EXCEPTION 'Session binding conflict'; END IF;
 UPDATE public.retell_api_sessions SET chat_id=p_chat,status='ready' WHERE id=s.id;
 UPDATE public.retell_api_turns SET status='generating' WHERE id=t.id;
 RETURN jsonb_build_object('bound',true,'replayed',false);
END $function$

CREATE OR REPLACE FUNCTION public.book_appointment(p_id uuid, p_lead uuid, p_at timestamp with time zone, p_type text, p_notes text, p_operator uuid, p_calendar text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
DECLARE saved public.appointments%ROWTYPE;
BEGIN
 IF NOT EXISTS(SELECT 1 FROM public.profiles WHERE id=p_operator AND status='approved') THEN
  RAISE EXCEPTION 'Operator not approved'; END IF;
 IF p_type NOT IN ('phone','in_person','video') OR p_calendar NOT IN ('not_configured','not_supported') OR length(coalesce(p_notes,''))>4000 THEN
  RAISE EXCEPTION 'Invalid appointment'; END IF;
 PERFORM pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended('appointment:'||p_lead,0));
 SELECT * INTO saved FROM public.appointments WHERE id=p_id;
 IF FOUND THEN
  IF saved.lead_id IS DISTINCT FROM p_lead OR saved.scheduled_at IS DISTINCT FROM p_at
   OR saved.appointment_type IS DISTINCT FROM p_type OR coalesce(saved.notes,'')<>coalesce(p_notes,'')
   OR saved.created_by IS DISTINCT FROM p_operator THEN RETURN jsonb_build_object('conflict',true); END IF;
  RETURN jsonb_build_object('appointment',to_jsonb(saved),'reused',true);
 END IF;
 SELECT * INTO saved FROM public.appointments WHERE lead_id=p_lead AND scheduled_at=p_at AND status IN ('scheduled','confirmed');
 IF FOUND THEN
  IF saved.appointment_type<>p_type OR coalesce(saved.notes,'')<>coalesce(p_notes,'') THEN RETURN jsonb_build_object('conflict',true); END IF;
  RETURN jsonb_build_object('appointment',to_jsonb(saved),'reused',true);
 END IF;
 IF p_at<=now() OR NOT EXISTS(SELECT 1 FROM public.leads WHERE id=p_lead) THEN
  RETURN jsonb_build_object('invalid',true); END IF;
 INSERT INTO public.appointments(id,lead_id,scheduled_at,appointment_type,notes,created_by,source,calendar_sync)
 VALUES(p_id,p_lead,p_at,p_type,nullif(p_notes,''),p_operator,'manual',p_calendar) RETURNING * INTO saved;
 RETURN jsonb_build_object('appointment',to_jsonb(saved),'reused',false);
END $function$

CREATE OR REPLACE FUNCTION public.cancel_list_trace_as_operator(p_id uuid, p_request uuid, p_operator uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
DECLARE event wholesale_ingest.trace_operator_events; result jsonb;
BEGIN
 IF NOT EXISTS(SELECT 1 FROM public.profiles WHERE id=p_operator AND role='admin' AND status='approved') THEN RAISE EXCEPTION 'Approved administrator required'; END IF;
 IF p_id IS NULL OR p_request IS NULL THEN RETURN jsonb_build_object('blocked','invalid_reference'); END IF;
 PERFORM pg_advisory_xact_lock(hashtextextended('trace-operator:'||p_id::text,0));
 SELECT * INTO event FROM wholesale_ingest.trace_operator_events WHERE id=p_id;
 IF FOUND THEN
  IF event.operator_id<>p_operator OR event.request_id<>p_request THEN RETURN jsonb_build_object('blocked','reference_conflict'); END IF;
  RETURN jsonb_build_object('event',to_jsonb(event),'replayed',true);
 END IF;
 result:=public.cancel_reserved_list_trace(p_request);
 IF result ? 'blocked' THEN RETURN result; END IF;
 INSERT INTO wholesale_ingest.trace_operator_events(id,operator_id,request_id,action,result)
 VALUES(p_id,p_operator,p_request,'cancel_reserved',result) RETURNING * INTO event;
 RETURN jsonb_build_object('event',to_jsonb(event),'replayed',false);
END $function$

CREATE OR REPLACE FUNCTION public.cancel_reserved_list_trace(p_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
DECLARE saved wholesale_ingest.skip_trace_requests;
BEGIN
 SELECT * INTO saved FROM wholesale_ingest.skip_trace_requests WHERE id=p_id FOR UPDATE;
 IF NOT FOUND THEN RETURN jsonb_build_object('blocked','request_missing'); END IF;
 IF saved.state<>'reserved' THEN RETURN jsonb_build_object('blocked','already_claimed'); END IF;
 UPDATE wholesale_ingest.daily_budgets SET reserved_cents=reserved_cents-saved.reserved_cents WHERE spend_day=saved.spend_day;
 IF NOT FOUND THEN RAISE EXCEPTION 'Original trace budget missing'; END IF;
 UPDATE wholesale_ingest.skip_trace_requests SET state='failed',actual_cents=0,provider_job_id='not_submitted',
  result_hash=input_hash,settled_at=clock_timestamp() WHERE id=p_id RETURNING * INTO saved;
 RETURN jsonb_build_object('request',to_jsonb(saved),'dispatch',false);
END $function$

CREATE OR REPLACE FUNCTION public.claim_email_message(p_id uuid, p_email text, p_subject text, p_provider text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
DECLARE v_email text := lower(trim(p_email)); v_id uuid;
BEGIN
 IF v_email = '' OR position('@' in v_email)=0 THEN RAISE EXCEPTION 'Invalid email'; END IF;
 -- Serialize suppression updates and claims for each mailbox.
 PERFORM pg_advisory_xact_lock(hashtextextended(v_email,0));
 IF EXISTS(SELECT 1 FROM public.email_suppressions WHERE email=v_email)
 OR EXISTS(SELECT 1 FROM public.dnc_registry WHERE lower(trim(email))=v_email)
 OR EXISTS(SELECT 1 FROM public.leads WHERE lower(trim(owner_email))=v_email AND dnc IS TRUE)
 THEN RETURN jsonb_build_object('claimed',false,'suppressed',true); END IF;
 INSERT INTO public.email_messages(id,recipient,subject,provider)
 VALUES(p_id,v_email,left(p_subject,998),p_provider) ON CONFLICT(id) DO NOTHING RETURNING id INTO v_id;
 RETURN jsonb_build_object('claimed',v_id IS NOT NULL,'suppressed',false);
END;
$function$

CREATE OR REPLACE FUNCTION public.claim_intake_notification(p_lead_id uuid, p_claim_id uuid, p_notification jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
DECLARE alert_id uuid; saved public.app_notifications%ROWTYPE; owner_id uuid;
BEGIN
 IF p_claim_id IS NULL OR jsonb_typeof(p_notification) IS DISTINCT FROM 'object' THEN
  RAISE EXCEPTION 'A delivery claim and notification are required'; END IF;
 IF NOT EXISTS(SELECT 1 FROM public.leads WHERE id=p_lead_id) THEN RAISE EXCEPTION 'Saved lead required'; END IF;
 SELECT p.id INTO owner_id FROM public.app_settings a JOIN public.profiles p ON p.id::text=a.value
  WHERE a.key='lead_owner_user_id' AND p.status='approved';
 IF owner_id IS NULL THEN RAISE EXCEPTION 'Approved owner required'; END IF;
 alert_id:=extensions.uuid_generate_v5('6ba7b811-9dad-11d1-80b4-00c04fd430c8'::uuid,'wholesaleos:intake-alert:'||p_lead_id::text);
 INSERT INTO public.app_notifications(id,recipient_id,recipient_role,type,title,body,action_url,lead_id,metadata)
 VALUES(alert_id,owner_id,'admin','pipeline_step',p_notification->>'title',p_notification->>'body','/leads',p_lead_id,
   coalesce(p_notification->'metadata','{}'::jsonb)||jsonb_build_object('delivery_state','pending'))
 ON CONFLICT(id) DO NOTHING;
 SELECT * INTO STRICT saved FROM public.app_notifications WHERE id=alert_id FOR UPDATE;
 IF saved.lead_id IS DISTINCT FROM p_lead_id THEN RAISE EXCEPTION 'Notification does not match lead'; END IF;
 IF saved.metadata->>'delivery_state' IS DISTINCT FROM 'pending' THEN
  RETURN jsonb_build_object('claimed',false,'notification_id',alert_id,'delivery_state',coalesce(saved.metadata->>'delivery_state','legacy_review'));
 END IF;
 UPDATE public.app_notifications SET metadata=metadata||jsonb_build_object('delivery_state','processing',
  'delivery_claim',p_claim_id,'claimed_at',clock_timestamp()) WHERE id=alert_id;
 RETURN jsonb_build_object('claimed',true,'notification_id',alert_id,'claim_id',p_claim_id);
END $function$

CREATE OR REPLACE FUNCTION public.claim_list_score_job(p_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
DECLARE job wholesale_ingest.scoring_jobs; snapshot jsonb;
BEGIN
 SELECT * INTO job FROM wholesale_ingest.scoring_jobs WHERE id=p_id FOR UPDATE;
 IF NOT FOUND THEN RETURN jsonb_build_object('blocked','job_missing'); END IF;
 IF job.state<>'queued' THEN RETURN jsonb_build_object('job',to_jsonb(job),'dispatch',false); END IF;
 snapshot:=public.list_scoring_input(job.lead_id);
 IF snapshot->>'input_hash' IS DISTINCT FROM job.input_hash THEN
  UPDATE wholesale_ingest.scoring_jobs SET state='obsolete',error_code='stale_before_call' WHERE id=p_id RETURNING * INTO job;
  RETURN jsonb_build_object('job',to_jsonb(job),'dispatch',false);
 END IF;
 UPDATE wholesale_ingest.scoring_jobs SET state='submitted',claimed_at=clock_timestamp(),claim_token=gen_random_uuid()
 WHERE id=p_id RETURNING * INTO job;
 RETURN jsonb_build_object('job',to_jsonb(job),'dispatch',true);
END $function$

CREATE OR REPLACE FUNCTION public.claim_list_trace(p_id uuid, p_input_hash text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
DECLARE saved wholesale_ingest.skip_trace_requests; snapshot jsonb; total_budget jsonb;
BEGIN
 IF coalesce(p_input_hash,'') !~ '^[a-f0-9]{64}$' THEN RETURN jsonb_build_object('blocked','invalid_input_identity'); END IF;
 SELECT * INTO saved FROM wholesale_ingest.skip_trace_requests WHERE id=p_id FOR UPDATE;
 IF NOT FOUND THEN RETURN jsonb_build_object('blocked','request_missing'); END IF;
 IF saved.input_snapshot IS NULL THEN RETURN jsonb_build_object('blocked','input_snapshot_missing'); END IF;
 IF saved.input_hash IS DISTINCT FROM p_input_hash THEN RETURN jsonb_build_object('blocked','input_changed'); END IF;
 IF saved.state<>'reserved' THEN RETURN jsonb_build_object('request',to_jsonb(saved),'dispatch',false); END IF;
 IF saved.spend_day<>(clock_timestamp() AT TIME ZONE 'America/Chicago')::date THEN RETURN jsonb_build_object('blocked','reservation_expired'); END IF;
 -- Existing pre-migration reservations cannot bypass the cumulative authorization.
 total_budget:=public.list_trace_total_budget();
 IF (total_budget->>'committed_cents')::bigint>(total_budget->>'cap_cents')::bigint
 THEN RETURN jsonb_build_object('blocked','total_cap','total_budget',total_budget); END IF;
 snapshot:=public.list_trace_input(saved.lead_id);
 IF snapshot ? 'blocked' THEN RETURN snapshot; END IF;
 IF snapshot->>'input_hash'<>saved.input_hash THEN RETURN jsonb_build_object('blocked','input_changed'); END IF;
 UPDATE wholesale_ingest.skip_trace_requests SET state='submitted' WHERE id=p_id RETURNING * INTO saved;
 RETURN jsonb_build_object('request',to_jsonb(saved),'input',snapshot->'input','dispatch',true);
END $function$

CREATE OR REPLACE FUNCTION public.claim_retell_api_turn(p_turn uuid, p_agent text, p_version integer)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
DECLARE t public.retell_api_turns; s public.retell_api_sessions; earliest uuid;
BEGIN
 IF p_turn IS NULL OR coalesce(p_agent,'') !~ '^[A-Za-z0-9_-]{1,128}$' OR p_version IS NULL OR p_version NOT BETWEEN 0 AND 999999999 THEN RAISE EXCEPTION 'Invalid generation claim'; END IF;
 SELECT * INTO t FROM public.retell_api_turns WHERE id=p_turn;
 IF NOT FOUND THEN RETURN jsonb_build_object('claimed',false,'reason','missing_turn'); END IF;
 SELECT * INTO s FROM public.retell_api_sessions WHERE id=t.session_id;
 PERFORM pg_advisory_xact_lock(hashtextextended('seller-outreach:'||s.phone_number,0));
 SELECT * INTO s FROM public.retell_api_sessions WHERE id=t.session_id FOR UPDATE;
 SELECT * INTO t FROM public.retell_api_turns WHERE id=p_turn FOR UPDATE;
 IF t.status<>'queued' OR s.status NOT IN ('pending','ready') THEN RETURN jsonb_build_object('claimed',false,'reason','already_claimed_or_held'); END IF;
 SELECT id INTO earliest FROM public.retell_api_turns WHERE session_id=s.id AND status NOT IN ('accepted','stopped') ORDER BY created_at,id LIMIT 1;
 IF earliest IS DISTINCT FROM t.id THEN RETURN jsonb_build_object('claimed',false,'reason','previous_turn_unfinished'); END IF;
 IF t.expires_at<=now() OR coalesce((public.intake_phone_status(s.phone_number,s.lead_id,''))->>'suppressed','true')<>'false'
  OR NOT EXISTS(SELECT 1 FROM public.retell_form_sms_jobs WHERE id=s.id AND delivery_transport='app_twilio' AND status='accepted')
  OR NOT EXISTS(SELECT 1 FROM public.leads WHERE id=s.lead_id AND dnc IS FALSE AND status NOT IN ('dnc','dead','closed','sold','under_contract')) THEN
  UPDATE public.retell_api_turns SET status='stopped',reason='Expired or suppressed before generation' WHERE id=t.id;
  RETURN jsonb_build_object('claimed',false,'reason','expired_or_suppressed'); END IF;
 IF s.status='ready' AND (s.agent_id IS DISTINCT FROM p_agent OR s.agent_version IS DISTINCT FROM p_version) THEN
  RETURN jsonb_build_object('claimed',false,'reason','session_release_mismatch'); END IF;
 UPDATE public.retell_api_turns SET status=CASE WHEN s.status='pending' THEN 'creating_session' ELSE 'generating' END,claimed_at=now() WHERE id=t.id;
 IF s.status='pending' THEN
  UPDATE public.retell_api_sessions SET status='creating',agent_id=p_agent,agent_version=p_version,claimed_at=now() WHERE id=s.id;
 END IF;
 RETURN jsonb_build_object('claimed',true,'create_session',s.status='pending','session_id',s.id,
  'chat_id',s.chat_id,'lead_id',s.lead_id,'turn_id',t.id,'recipient_text',t.recipient_text,'expires_at',t.expires_at);
END $function$

CREATE OR REPLACE FUNCTION public.claim_retell_app_reply(p_turn uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
DECLARE t public.retell_api_turns; s public.retell_api_sessions; message uuid; v_body text; earliest uuid;
BEGIN
 SELECT * INTO t FROM public.retell_api_turns WHERE id=p_turn;
 IF NOT FOUND THEN RETURN jsonb_build_object('claimed',false,'reason','missing_turn'); END IF;
 SELECT * INTO s FROM public.retell_api_sessions WHERE id=t.session_id;
 PERFORM pg_advisory_xact_lock(hashtextextended('seller-outreach:'||s.phone_number,0));
 SELECT * INTO s FROM public.retell_api_sessions WHERE id=t.session_id FOR UPDATE;
 SELECT * INTO t FROM public.retell_api_turns WHERE id=p_turn FOR UPDATE;
 IF t.status<>'generated' OR t.outbound_id IS NOT NULL OR s.status<>'ready' THEN
  RETURN jsonb_build_object('claimed',false,'reason','already_claimed_or_held'); END IF;
 SELECT id INTO earliest FROM public.retell_api_turns WHERE session_id=s.id AND status NOT IN ('accepted','stopped') ORDER BY created_at,id LIMIT 1;
 IF earliest IS DISTINCT FROM t.id THEN RETURN jsonb_build_object('claimed',false,'reason','previous_turn_unfinished'); END IF;
 IF t.expires_at<=now() OR coalesce((public.intake_phone_status(s.phone_number,s.lead_id,''))->>'suppressed','true')<>'false'
  OR NOT EXISTS(SELECT 1 FROM public.leads WHERE id=s.lead_id AND dnc IS FALSE AND status NOT IN ('dnc','dead','closed','sold','under_contract'))
  OR NOT EXISTS(SELECT 1 FROM public.retell_form_sms_jobs WHERE id=s.id AND delivery_transport='app_twilio' AND status='accepted')
  OR NOT EXISTS(SELECT 1 FROM public.sms_events WHERE id=t.id AND provider='twilio' AND direction='inbound'
   AND lead_id=s.lead_id AND phone_number=s.phone_number AND body=t.recipient_text AND opt_out IS FALSE
   AND raw_payload->>'MessageSid'=t.inbound_sid AND raw_payload->>'From'=s.phone_number AND raw_payload->>'To'=s.sender_number
   AND raw_payload->>'crm_opt_out'='false' AND raw_payload->>'Body'=t.recipient_text
   AND coalesce(raw_payload->>'OptOutType','')='') THEN
  UPDATE public.retell_api_turns SET status='stopped',reason='Expired, suppressed, or inbound binding changed before dispatch' WHERE id=t.id;
  RETURN jsonb_build_object('claimed',false,'reason','expired_suppressed_or_unbound'); END IF;
 -- A real reply permits a conversational response, not a second prospecting
 -- attempt. Uncertain activity in any channel still stops this response.
 IF EXISTS(SELECT 1 FROM public.sms_events WHERE phone_number=s.phone_number AND direction='outbound'
    AND status IN ('submitting','unknown') AND NOT(coalesce(raw_payload,'{}') ? 'MessageSid'))
  OR EXISTS(SELECT 1 FROM public.retell_call_requests WHERE phone_number=s.phone_number AND status<>'completed')
  OR EXISTS(SELECT 1 FROM public.retell_api_turns x JOIN public.sms_events e ON e.id=x.outbound_id
    WHERE x.session_id=s.id AND e.status IN ('failed','undelivered','canceled','unknown'))
  OR EXISTS(SELECT 1 FROM public.sms_events WHERE id=s.id AND status IN ('failed','undelivered','canceled','unknown')) THEN
  UPDATE public.retell_api_turns SET status='review',reason='Earlier provider outcome requires review' WHERE id=t.id;
  UPDATE public.retell_api_sessions SET status='review',reason='Earlier provider outcome requires review' WHERE id=s.id;
  RETURN jsonb_build_object('claimed',false,'reason','unresolved_provider_outcome'); END IF;
 SELECT string_agg(value->>'content',E'\n' ORDER BY ordinal) INTO v_body FROM jsonb_array_elements(t.generated_messages) WITH ORDINALITY a(value,ordinal);
 IF length(trim(coalesce(v_body,''))) NOT BETWEEN 1 AND 1600 THEN RAISE EXCEPTION 'Missing generated reply'; END IF;
 message:=gen_random_uuid();
 INSERT INTO public.sms_events(id,lead_id,provider,direction,phone_number,body,status,raw_payload)
  VALUES(message,s.lead_id,'twilio','outbound',s.phone_number,v_body,'submitting',
   jsonb_build_object('transport','app_twilio','api_turn_id',t.id,'form_job_id',s.id,'sender_number',s.sender_number,'inbound_sid',t.inbound_sid));
 UPDATE public.retell_api_turns SET status='submitting',outbound_id=message WHERE id=t.id;
 RETURN jsonb_build_object('claimed',true,'message_id',message,'turn_id',t.id,'session_id',s.id,'lead_id',s.lead_id,
   'phone_number',s.phone_number,'sender_number',s.sender_number,'body',v_body,'expires_at',t.expires_at);
END $function$

CREATE OR REPLACE FUNCTION public.claim_retell_batch_next(p_batch uuid, p_operator uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
DECLARE b public.retell_call_batches%ROWTYPE; item jsonb; idx int;
BEGIN
  SELECT * INTO b FROM public.retell_call_batches WHERE id=p_batch AND requested_by=p_operator FOR UPDATE;
  IF NOT FOUND OR b.status<>'ready' THEN RETURN jsonb_build_object('claimed',false); END IF;
  SELECT e.value,e.ordinality-1 INTO item,idx FROM jsonb_array_elements(b.outcomes) WITH ORDINALITY e
    WHERE e.value->>'status'='pending' ORDER BY e.ordinality LIMIT 1;
  IF item IS NULL THEN
    UPDATE public.retell_call_batches SET status='completed' WHERE id=p_batch;
    RETURN jsonb_build_object('claimed',false);
  END IF;
  UPDATE public.retell_call_batches SET status='processing',claimed_at=now(),
    outcomes=jsonb_set(outcomes,ARRAY[idx::text,'status'],'"submitting"'::jsonb) WHERE id=p_batch;
  RETURN jsonb_build_object('claimed',true,'item',item);
END; $function$

CREATE OR REPLACE FUNCTION public.claim_retell_call(p_id uuid, p_lead uuid, p_phone text, p_operator uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
DECLARE v_id uuid; v_reason text;
BEGIN
  IF coalesce(p_phone,'') !~ '^\+1[2-9][0-9]{9}$' THEN RAISE EXCEPTION 'Invalid call phone'; END IF;
  PERFORM pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended('seller-outreach:'||p_phone,0));
  IF EXISTS(SELECT 1 FROM public.retell_call_requests WHERE id=p_id) THEN
    RETURN jsonb_build_object('claimed',false,'reason','existing_reference');
  END IF;
  IF NOT EXISTS (SELECT 1 FROM public.leads WHERE id=p_lead AND dnc IS FALSE AND ai_calling_paused IS FALSE)
    OR coalesce((public.intake_phone_status(p_phone,p_lead,''))->>'suppressed','true')<>'false' THEN
    RETURN jsonb_build_object('claimed',false,'reason','suppressed_or_paused');
  END IF;
  v_reason:=public.outreach_recipient_limits(p_phone)->>'blocker';
  IF v_reason IS NOT NULL THEN RETURN jsonb_build_object('claimed',false,'reason',v_reason); END IF;
  INSERT INTO public.retell_call_requests(id,lead_id,phone_number,requested_by,status)
    VALUES(p_id,p_lead,p_phone,p_operator,'submitting') ON CONFLICT(id) DO NOTHING RETURNING id INTO v_id;
  RETURN jsonb_build_object('claimed',v_id IS NOT NULL,'reason',CASE WHEN v_id IS NULL THEN 'existing_reference' ELSE 'claimed' END);
END; $function$

CREATE OR REPLACE FUNCTION public.claim_retell_form_sms_transport(p_limit integer, p_job uuid, p_transport text)
 RETURNS SETOF retell_form_sms_jobs
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
DECLARE j public.retell_form_sms_jobs; test_override boolean; blocker text;
BEGIN
  IF p_transport IS NULL OR p_transport NOT IN ('retell_native','app_twilio') THEN RAISE EXCEPTION 'Invalid delivery transport'; END IF;
  FOR j IN SELECT * FROM public.retell_form_sms_jobs WHERE status='scheduled' AND due_at<=now() AND delivery_transport=p_transport
    AND (p_job IS NULL OR id=p_job)
    ORDER BY due_at FOR UPDATE SKIP LOCKED LIMIT CASE WHEN p_job IS NOT NULL THEN 1 ELSE least(greatest(p_limit,1),10) END
  LOOP
    PERFORM pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended('seller-outreach:'||j.phone_number,0));
    blocker := public.outreach_recipient_limits(j.phone_number)->>'blocker';
    SELECT EXISTS(SELECT 1 FROM private.retell_owner_retest_authorizations a
      WHERE a.job_id=j.id AND a.phone_number=j.phone_number AND a.lead_id=j.lead_id
        AND a.created_at<=now() AND a.expires_at>now() AND a.consumed_at IS NULL
        AND p_job=j.id AND p_transport='app_twilio') INTO test_override;
    IF j.expires_at <= now() OR
       (blocker IS NOT NULL AND NOT (test_override AND blocker='attempt_limit')) OR
       coalesce((public.intake_phone_status(j.phone_number,j.lead_id,''))->>'suppressed','true') <> 'false' OR
       EXISTS (SELECT 1 FROM public.retell_form_sms_jobs r WHERE r.phone_number=j.phone_number
         AND r.id<>j.id AND r.status IN ('processing','accepted','review')) OR
       EXISTS (SELECT 1 FROM public.sms_events e WHERE e.phone_number=j.phone_number
         AND ((e.opt_out IS TRUE AND NOT public.sms_stop_has_reviewed_opt_in(e.id)) OR (e.direction='outbound' AND e.created_at>now()-interval '24 hours'))) THEN
      UPDATE public.retell_form_sms_jobs SET status='stopped',reason='Expired, suppressed, or previous recipient contact' WHERE id=j.id;
      CONTINUE;
    END IF;
    IF test_override THEN
      UPDATE private.retell_owner_retest_authorizations SET consumed_at=now() WHERE job_id=j.id AND consumed_at IS NULL;
    END IF;
    UPDATE public.retell_form_sms_jobs SET status='processing',claimed_at=now() WHERE id=j.id RETURNING * INTO j;
    -- Shared ledger blocks Twilio's claim function from sending alongside Retell.
    INSERT INTO public.sms_events(id,lead_id,provider,direction,phone_number,body,status,raw_payload)
      VALUES(j.id,j.lead_id,CASE WHEN p_transport='retell_native' THEN 'retell' ELSE 'twilio' END,
        'outbound',j.phone_number,coalesce(j.delivery_body,'Retell consented form response pending'),'submitting',
        CASE WHEN p_transport='app_twilio' THEN jsonb_build_object('transport',p_transport,'form_job_id',j.id,'sender_number',j.delivery_sender) ELSE '{}'::jsonb END);
    RETURN NEXT j;
  END LOOP;
END; $function$

CREATE OR REPLACE FUNCTION public.claim_twilio_sms(p_id uuid, p_lead uuid, p_phone text, p_body text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
DECLARE v_id uuid; v_reason text;
BEGIN
  IF coalesce(p_phone,'') !~ '^\+1[2-9][0-9]{9}$' OR length(coalesce(p_body,'')) NOT BETWEEN 1 AND 1600 THEN
    RAISE EXCEPTION 'Invalid SMS claim';
  END IF;
  PERFORM pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended('seller-outreach:'||p_phone,0));
  IF EXISTS (SELECT 1 FROM public.sms_events WHERE id=p_id) THEN
    RETURN jsonb_build_object('claimed',false,'reason','existing_reference');
  END IF;
  IF coalesce((public.intake_phone_status(p_phone,p_lead,''))->>'suppressed','true') <> 'false' THEN
    RETURN jsonb_build_object('claimed',false,'reason','suppressed');
  END IF;
  v_reason:=public.outreach_recipient_limits(p_phone)->>'blocker';
  IF v_reason IS NOT NULL THEN RETURN jsonb_build_object('claimed',false,'reason',v_reason); END IF;
  INSERT INTO public.sms_events(id,lead_id,provider,direction,phone_number,body,status)
    VALUES(p_id,p_lead,'twilio','outbound',p_phone,p_body,'submitting') ON CONFLICT(id) DO NOTHING RETURNING id INTO v_id;
  RETURN jsonb_build_object('claimed',v_id IS NOT NULL,'reason',CASE WHEN v_id IS NULL THEN 'existing_reference' ELSE 'claimed' END);
END; $function$

CREATE OR REPLACE FUNCTION public.complete_list_score_job(p_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
DECLARE job wholesale_ingest.scoring_jobs; result jsonb;
BEGIN
 SELECT * INTO job FROM wholesale_ingest.scoring_jobs WHERE id=p_id FOR UPDATE;
 IF NOT FOUND THEN RETURN jsonb_build_object('blocked','job_missing'); END IF;
 IF job.state NOT IN ('received','completed') THEN RETURN jsonb_build_object('job',to_jsonb(job),'dispatch',false); END IF;
 result:=public.save_list_score(job.id,job.lead_id,job.input_hash,job.model_version,job.prompt_version,job.model_receipt,job.assessment);
 IF result ? 'blocked' THEN
  UPDATE wholesale_ingest.scoring_jobs SET state=CASE WHEN result->>'blocked' IN ('stale_input','no_active_signals','property_unverified') THEN 'obsolete' ELSE 'review' END,error_code=result->>'blocked'
  WHERE id=p_id RETURNING * INTO job;
  RETURN jsonb_build_object('job',to_jsonb(job),'blocked',result->>'blocked','dispatch',false);
 END IF;
 UPDATE wholesale_ingest.scoring_jobs SET state='completed',completed_at=coalesce(completed_at,clock_timestamp()) WHERE id=p_id RETURNING * INTO job;
 RETURN result||jsonb_build_object('job',to_jsonb(job),'dispatch',false);
END $function$

CREATE OR REPLACE FUNCTION public.complete_list_trace(p_id uuid, p_provider text, p_input_hash text, p_actual_cents integer, p_provider_receipt text, p_contacts jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
DECLARE saved wholesale_ingest.skip_trace_requests; snapshot jsonb; item jsonb; result jsonb; ordinal integer:=0; fingerprint text;
BEGIN
 SELECT * INTO saved FROM wholesale_ingest.skip_trace_requests WHERE id=p_id FOR UPDATE;
 IF NOT FOUND THEN RETURN jsonb_build_object('blocked','request_missing'); END IF;
 IF saved.provider IS DISTINCT FROM p_provider OR saved.input_hash IS DISTINCT FROM p_input_hash
 THEN RETURN jsonb_build_object('blocked','receipt_identity_mismatch'); END IF;
 IF jsonb_typeof(p_contacts) IS DISTINCT FROM 'array' THEN RETURN jsonb_build_object('blocked','invalid_contacts'); END IF;
 IF jsonb_array_length(p_contacts)>20 THEN RETURN jsonb_build_object('blocked','invalid_contacts'); END IF;
 FOR item IN SELECT value FROM jsonb_array_elements(p_contacts) LOOP
  IF jsonb_typeof(item) IS DISTINCT FROM 'object' OR item-ARRAY['phone','email','phone_type','name']<>'{}'::jsonb
  OR (item->>'phone' IS NULL AND item->>'email' IS NULL)
  OR (item->>'phone' IS NOT NULL AND (jsonb_typeof(item->'phone')<>'string' OR item->>'phone' !~ '^\+1[2-9][0-9]{9}$'))
  OR (item->>'email' IS NOT NULL AND (jsonb_typeof(item->'email')<>'string' OR length(item->>'email')>320 OR item->>'email' !~ '^[^[:space:]@]+@[^[:space:]@]+\.[^[:space:]@]+$'))
  OR (item->>'name' IS NOT NULL AND (jsonb_typeof(item->'name')<>'string' OR length(item->>'name')>200))
  OR coalesce(item->>'phone_type','unknown') NOT IN ('mobile','landline','voip','unknown')
  THEN RETURN jsonb_build_object('blocked','invalid_contacts'); END IF;
 END LOOP;
 fingerprint:=encode(sha256(convert_to(p_contacts::text,'UTF8')),'hex');
 IF saved.state<>'completed' THEN
  snapshot:=public.list_trace_input(saved.lead_id);
  IF snapshot ? 'blocked' THEN RETURN snapshot; END IF;
  IF snapshot->>'input_hash'<>saved.input_hash THEN RETURN jsonb_build_object('blocked','input_changed'); END IF;
 END IF;
 result:=public.settle_list_trace(p_id,'completed',p_actual_cents,p_provider_receipt,fingerprint);
 IF result ? 'blocked' THEN RETURN result; END IF;
 IF result->>'replayed'='false' THEN
  FOR item IN SELECT value FROM jsonb_array_elements(p_contacts) LOOP
   INSERT INTO wholesale_ingest.contacts(lead_id,provider,traced_at,expires_at,name,phone,email,phone_type,dnc_status,trace_request_id,trace_ordinal)
   VALUES(saved.lead_id,saved.provider,clock_timestamp(),clock_timestamp()+interval '30 days',item->>'name',item->>'phone',item->>'email',coalesce(item->>'phone_type','unknown'),'unknown',p_id,ordinal);
   ordinal:=ordinal+1;
  END LOOP;
 END IF;
 IF (SELECT count(*) FROM wholesale_ingest.contacts WHERE trace_request_id=p_id)<>jsonb_array_length(p_contacts)
 THEN RAISE EXCEPTION 'Trace contact persistence mismatch'; END IF;
 RETURN result||jsonb_build_object('contacts_saved',jsonb_array_length(p_contacts));
END $function$

CREATE OR REPLACE FUNCTION public.configure_list_source(p_key text, p_operator uuid, p_enabled boolean, p_lookback integer, p_procedure text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
DECLARE s wholesale_ingest.sources;
BEGIN
 IF NOT EXISTS(SELECT 1 FROM public.profiles WHERE id=p_operator AND role='admin' AND status='approved') THEN RAISE EXCEPTION 'Approved administrator required'; END IF;
 IF p_enabled AND (p_procedure IS NULL OR length(trim(p_procedure))<3) THEN RAISE EXCEPTION 'Reviewed procedure version required'; END IF;
 UPDATE wholesale_ingest.sources SET enabled=p_enabled,lookback_days=p_lookback,
 procedure_version=p_procedure,procedure_approved_at=CASE WHEN p_enabled THEN now() ELSE procedure_approved_at END
 WHERE source_key=p_key RETURNING * INTO s;
 IF s.id IS NULL THEN RAISE EXCEPTION 'Unknown source'; END IF;
 RETURN to_jsonb(s);
END; $function$

CREATE OR REPLACE FUNCTION public.create_pipeline_deal(p_id uuid, p_operator uuid, p_payload jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
DECLARE saved public.deals%ROWTYPE; proposed public.deals%ROWTYPE;
BEGIN
 IF NOT EXISTS(SELECT 1 FROM public.profiles WHERE id=p_operator AND status='approved') THEN RAISE EXCEPTION 'Operator not approved'; END IF;
 PERFORM pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended('deal-ref:'||p_id,0));
 SELECT * INTO saved FROM public.deals WHERE id=p_id;
 IF FOUND THEN
  IF saved.creation_manifest IS DISTINCT FROM p_payload OR saved.created_by IS DISTINCT FROM p_operator THEN RETURN jsonb_build_object('conflict',true); END IF;
  RETURN jsonb_build_object('deal',to_jsonb(saved),'reused',true);
 END IF;
 proposed:=jsonb_populate_record(NULL::public.deals,p_payload||jsonb_build_object('id',p_id,'created_by',p_operator,'creation_manifest',p_payload,
 'created_at',clock_timestamp(),'updated_at',clock_timestamp(),'assigned_to',coalesce(nullif(p_payload->>'assigned_to','')::uuid,p_operator)));
 IF NOT EXISTS(SELECT 1 FROM public.leads WHERE id=proposed.lead_id) THEN RETURN jsonb_build_object('missing',true); END IF;
 PERFORM pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended('deal-lead:'||proposed.lead_id,0));
 SELECT * INTO saved FROM public.deals WHERE lead_id=proposed.lead_id AND stage NOT IN ('closed','cancelled');
 IF FOUND THEN RETURN jsonb_build_object('existing_id',saved.id); END IF;
 IF NOT public.deal_handoff_valid(proposed) THEN RETURN jsonb_build_object('invalid',true); END IF;
 INSERT INTO public.deals SELECT proposed.* RETURNING * INTO saved;
 PERFORM public.sync_deal_handoff_tasks(saved);
 RETURN jsonb_build_object('deal',to_jsonb(saved),'reused',false);
END $function$

CREATE OR REPLACE FUNCTION public.enqueue_retell_api_turn(p_job uuid, p_event uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
DECLARE j public.retell_form_sms_jobs; e public.sms_events; existing public.retell_api_turns; body_control text;
BEGIN
 SELECT * INTO j FROM public.retell_form_sms_jobs WHERE id=p_job;
 IF NOT FOUND OR j.delivery_transport<>'app_twilio' OR j.status<>'accepted' THEN
  RETURN jsonb_build_object('queued',false,'reason','inquiry_not_accepted'); END IF;
 PERFORM pg_advisory_xact_lock(hashtextextended('seller-outreach:'||j.phone_number,0));
 SELECT * INTO e FROM public.sms_events WHERE id=p_event;
 IF NOT FOUND OR e.provider<>'twilio' OR e.direction<>'inbound' OR e.lead_id IS DISTINCT FROM j.lead_id
  OR e.phone_number IS DISTINCT FROM j.phone_number OR e.status IS DISTINCT FROM 'replied'
  OR e.opt_out IS DISTINCT FROM false OR coalesce(e.raw_payload->>'crm_opt_out','true')<>'false'
  OR coalesce(e.raw_payload->>'MessageSid','') !~ '^SM[0-9a-fA-F]{32}$'
  OR e.raw_payload->>'From' IS DISTINCT FROM j.phone_number OR e.raw_payload->>'To' IS DISTINCT FROM j.delivery_sender
  OR e.body IS DISTINCT FROM e.raw_payload->>'Body'
  OR length(trim(coalesce(e.body,''))) NOT BETWEEN 1 AND 1600 THEN
  RETURN jsonb_build_object('queued',false,'reason','carrier_receipt_mismatch'); END IF;
 body_control:=upper(regexp_replace(trim(e.body),'[.!?]+$','','g'));
 IF coalesce(e.raw_payload->>'OptOutType','')<>'' OR body_control IN
  ('STOP','STOPALL','UNSUBSCRIBE','CANCEL','END','QUIT','REVOKE','OPTOUT','OPT OUT','START','UNSTOP','YES','HELP','INFO') THEN
  RETURN jsonb_build_object('queued',false,'reason','carrier_control'); END IF;
 SELECT * INTO existing FROM public.retell_api_turns WHERE id=p_event OR inbound_sid=e.raw_payload->>'MessageSid';
 IF FOUND THEN
  IF existing.id<>p_event OR existing.session_id<>p_job OR existing.recipient_text<>e.body THEN RAISE EXCEPTION 'Inbound turn identity conflict'; END IF;
  RETURN jsonb_build_object('queued',false,'reason','existing_turn','turn_id',existing.id); END IF;
 IF e.created_at<j.created_at OR e.created_at>now()+interval '5 seconds' OR e.created_at<=now()-interval '15 minutes'
  OR coalesce((public.intake_phone_status(j.phone_number,j.lead_id,''))->>'suppressed','true')<>'false'
  OR NOT EXISTS(SELECT 1 FROM public.leads WHERE id=j.lead_id AND dnc IS FALSE AND status NOT IN ('dnc','dead','closed','sold','under_contract'))
  OR NOT EXISTS(SELECT 1 FROM public.sms_events WHERE id=j.id AND provider='twilio' AND direction='outbound'
    AND phone_number=j.phone_number AND lead_id=j.lead_id AND body=j.delivery_body AND created_at<=e.created_at
    AND raw_payload->>'transport'='app_twilio' AND raw_payload->>'form_job_id'=j.id::text
    AND raw_payload->>'sender_number'=j.delivery_sender AND status IN ('accepted','queued','sending','sent','delivered','read')
    AND raw_payload->>'provider_sid' ~ '^SM[0-9a-fA-F]{32}$') THEN
  RETURN jsonb_build_object('queued',false,'reason','expired_suppressed_or_ack_unconfirmed'); END IF;
 IF EXISTS(SELECT 1 FROM public.retell_api_sessions WHERE phone_number=j.phone_number AND id<>j.id AND status<>'closed') THEN
  RETURN jsonb_build_object('queued',false,'reason','other_conversation'); END IF;
 INSERT INTO public.retell_api_sessions(id,lead_id,phone_number,sender_number)
  VALUES(j.id,j.lead_id,j.phone_number,j.delivery_sender) ON CONFLICT(id) DO NOTHING;
 IF NOT EXISTS(SELECT 1 FROM public.retell_api_sessions WHERE id=j.id AND status IN ('pending','creating','ready')
  AND lead_id=j.lead_id AND phone_number=j.phone_number AND sender_number=j.delivery_sender) THEN
  RETURN jsonb_build_object('queued',false,'reason','conversation_held'); END IF;
 INSERT INTO public.retell_api_turns(id,session_id,inbound_sid,recipient_text,created_at,expires_at)
  VALUES(e.id,j.id,e.raw_payload->>'MessageSid',e.body,e.created_at,e.created_at+interval '15 minutes');
 RETURN jsonb_build_object('queued',true,'turn_id',e.id,'session_id',j.id);
END $function$

CREATE OR REPLACE FUNCTION public.finalize_form_submission(p_submission_id uuid, p_lead jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'public', 'pg_temp'
AS $function$
DECLARE
  receipt public.lead_form_submissions%ROWTYPE;
  candidate public.leads%ROWTYPE;
  saved_id uuid;
  owner_id uuid;
  created boolean := false;
  alert_id uuid;
  intake_source text;
  recovery_only boolean := coalesce((p_lead->>'_intake_recovery_only')::boolean,false);
BEGIN
  SELECT * INTO STRICT receipt FROM public.lead_form_submissions
    WHERE id = p_submission_id FOR UPDATE;
  SELECT value::uuid INTO owner_id FROM public.app_settings WHERE key = 'lead_owner_user_id';
  IF owner_id IS NULL OR NOT EXISTS (
    SELECT 1 FROM public.profiles WHERE id=owner_id AND status='approved'
  ) THEN RAISE EXCEPTION 'An approved intake owner is required'; END IF;

  saved_id := receipt.lead_id;
  IF saved_id IS NULL THEN
    SELECT id INTO saved_id FROM public.leads WHERE form_submission_id=p_submission_id
      ORDER BY created_at LIMIT 1;
  END IF;
  IF saved_id IS NULL THEN
    candidate := jsonb_populate_record(NULL::public.leads, p_lead);
    INSERT INTO public.leads (
      property_address,city,state,zip_code,owner_first_name,owner_last_name,owner_phone_1,owner_email,
      source,inbound_channel,status,precision_tier,ai_qualification_summary,
      score_motivation,score_timeline,score_equity,score_condition,score_flexibility,
      priority_tier,motivation_tag,asking_price,form_submission_id,ad_campaign_id,assigned_to,internal_notes,ai_calling_paused
    ) VALUES (
      candidate.property_address,candidate.city,candidate.state,candidate.zip_code,
      candidate.owner_first_name,candidate.owner_last_name,candidate.owner_phone_1,candidate.owner_email,
      candidate.source,candidate.inbound_channel,candidate.status,candidate.precision_tier,
      candidate.ai_qualification_summary,candidate.score_motivation,candidate.score_timeline,
      candidate.score_equity,candidate.score_condition,candidate.score_flexibility,
      candidate.priority_tier,candidate.motivation_tag,candidate.asking_price,p_submission_id,
      candidate.ad_campaign_id,owner_id,candidate.internal_notes,coalesce(candidate.ai_calling_paused,true)
    ) RETURNING id INTO saved_id;
    created := true;
  END IF;
  -- Same task id on every recovery; completed tasks and operator changes survive.
  INSERT INTO public.tasks(id,title,description,priority,status,type,lead_id,assigned_to,due_date)
    VALUES (p_submission_id,'Follow up on new website inquiry',
      'Review the saved inquiry and consent before contacting the inquirer.',
      'high','pending','follow_up',saved_id,owner_id,now())
    ON CONFLICT(id) DO NOTHING;
  -- Commit the operator alert with the receipt, lead and assigned task.
  alert_id := extensions.uuid_generate_v5('6ba7b811-9dad-11d1-80b4-00c04fd430c8'::uuid,
    'wholesaleos:intake-alert:'||saved_id::text);
  SELECT coalesce(slug,'web_form') INTO intake_source FROM public.lead_form_configs WHERE id=receipt.form_id;
  INSERT INTO public.app_notifications(id,recipient_id,recipient_role,type,title,body,action_url,lead_id,metadata)
  VALUES(alert_id,owner_id,'admin','pipeline_step','New inquiry — follow-up required',
    coalesce(p_lead->>'property_address','Saved website inquiry')||' — source: '||coalesce(intake_source,'web_form')||
    '. Saved inquiry requires owner follow-up. Provider delivery has not been confirmed.',
    '/leads',saved_id,jsonb_build_object('source',coalesce(intake_source,'web_form'),
      'delivery_state',CASE WHEN recovery_only THEN 'review' ELSE 'pending' END,
      'owner_email','not_attempted','seller_sms','not_attempted',
      'owner_sms','not_supported_for_registered_campaign','submission_id',p_submission_id))
  ON CONFLICT(id) DO NOTHING;
  IF recovery_only THEN
    UPDATE public.app_notifications SET metadata=metadata||jsonb_build_object('delivery_state','review','recovery_only',true)
    WHERE id=alert_id AND metadata->>'delivery_state'='pending';
  END IF;
  UPDATE public.lead_form_submissions SET lead_id=saved_id,processing_status='processed'
    WHERE id=p_submission_id;
  RETURN jsonb_build_object('lead_id',saved_id,'created',created,'notification_id',alert_id);
END;
$function$

CREATE OR REPLACE FUNCTION public.finish_retell_batch_item(p_batch uuid, p_reference uuid, p_status text, p_reason text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
DECLARE b public.retell_call_batches%ROWTYPE; item jsonb; idx int; ledger public.retell_call_requests%ROWTYPE; updated jsonb;
BEGIN
  IF p_status NOT IN ('accepted','blocked','unknown') THEN RAISE EXCEPTION 'Invalid batch outcome'; END IF;
  SELECT * INTO b FROM public.retell_call_batches WHERE id=p_batch FOR UPDATE;
  IF NOT FOUND OR b.status NOT IN ('processing','review') THEN RAISE EXCEPTION 'Batch is not awaiting an outcome'; END IF;
  SELECT e.value,e.ordinality-1 INTO item,idx FROM jsonb_array_elements(b.outcomes) WITH ORDINALITY e
    WHERE e.value->>'request_id'=p_reference::text AND e.value->>'status' IN ('submitting','unknown');
  IF item IS NULL THEN RAISE EXCEPTION 'No matching claimed batch item'; END IF;
  SELECT * INTO ledger FROM public.retell_call_requests WHERE id=p_reference;
  IF FOUND THEN
    IF ledger.lead_id::text<>item->>'lead_id' OR ledger.phone_number<>item->>'phone_number' THEN RAISE EXCEPTION 'Mismatched batch call'; END IF;
    IF p_status='blocked' OR (p_status='accepted' AND (ledger.provider_call_id IS NULL OR ledger.status NOT IN ('accepted','completed'))) THEN
      RAISE EXCEPTION 'Provider outcome not confirmed';
    END IF;
  ELSIF p_status='accepted' THEN RAISE EXCEPTION 'No durable call receipt'; END IF;
  updated:=jsonb_set(b.outcomes,ARRAY[idx::text],item||jsonb_build_object('status',p_status,'reason',left(p_reason,500)));
  UPDATE public.retell_call_batches SET outcomes=updated,status=CASE WHEN p_status='unknown' THEN 'review'
    WHEN EXISTS(SELECT 1 FROM jsonb_array_elements(updated) e WHERE e->>'status'='pending') THEN 'ready'
    ELSE 'completed' END WHERE id=p_batch;
  RETURN jsonb_build_object('saved',true);
END; $function$

CREATE OR REPLACE FUNCTION public.foreclosure_appraisal_status(p_operator uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
DECLARE result jsonb;
BEGIN
 IF NOT EXISTS(SELECT 1 FROM public.profiles WHERE id=p_operator AND role='admin' AND status='approved') THEN RAISE EXCEPTION 'Approved administrator required'; END IF;
 SELECT coalesce(jsonb_agg(item ORDER BY item->'summary'->>'county'),'[]'::jsonb) INTO result FROM (
  SELECT DISTINCT ON(source_id) jsonb_build_object('batch_id',id,'summary',summary,'source_as_of',receipt->>'source_as_of','processed_at',processed_at) item
  FROM wholesale_ingest.foreclosure_appraisal_batches ORDER BY source_id,processed_at DESC,received_at DESC,id
 ) q;
 RETURN result;
END; $function$

CREATE OR REPLACE FUNCTION public.hold_retell_api_turn(p_turn uuid, p_expected text, p_reason text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
DECLARE t public.retell_api_turns; s public.retell_api_sessions;
BEGIN
 IF p_expected IS NULL OR p_expected NOT IN ('creating_session','generating','generated','submitting')
  OR length(trim(coalesce(p_reason,''))) NOT BETWEEN 1 AND 500 THEN RAISE EXCEPTION 'Invalid operation hold'; END IF;
 SELECT * INTO t FROM public.retell_api_turns WHERE id=p_turn;
 IF NOT FOUND THEN RETURN jsonb_build_object('held',false); END IF;
 SELECT * INTO s FROM public.retell_api_sessions WHERE id=t.session_id FOR UPDATE;
 SELECT * INTO t FROM public.retell_api_turns WHERE id=p_turn FOR UPDATE;
 IF t.status<>p_expected THEN RETURN jsonb_build_object('held',false); END IF;
 UPDATE public.retell_api_turns SET status='review',reason=p_reason WHERE id=t.id;
 UPDATE public.retell_api_sessions SET status='review',reason=p_reason WHERE id=s.id AND status<>'closed';
 RETURN jsonb_build_object('held',true,'dispatch_authorized',false);
END $function$

CREATE OR REPLACE FUNCTION public.inspect_list_scoring_job(p_operator uuid, p_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
DECLARE job wholesale_ingest.scoring_jobs; current_input jsonb; changes jsonb; evaluation jsonb;
BEGIN
 IF NOT EXISTS(SELECT 1 FROM public.profiles WHERE id=p_operator AND role='admin' AND status='approved') THEN RAISE EXCEPTION 'Approved administrator required'; END IF;
 SELECT * INTO job FROM wholesale_ingest.scoring_jobs WHERE id=p_id;
 IF NOT FOUND THEN RETURN jsonb_build_object('blocked','job_missing'); END IF;
 current_input:=public.list_scoring_input(job.lead_id);
 SELECT coalesce(jsonb_agg(key ORDER BY key),'[]') INTO changes FROM (
  SELECT key FROM jsonb_object_keys(job.input_snapshot) key
  UNION SELECT key FROM jsonb_object_keys(coalesce(current_input->'input','{}')) key
 ) keys WHERE job.input_snapshot->key IS DISTINCT FROM current_input#>ARRAY['input',key];
 SELECT jsonb_build_object('id',e.id,'score',e.score,'route',e.route,'flags',e.flags,'created_at',e.created_at) INTO evaluation
 FROM wholesale_ingest.lead_evaluations e WHERE e.id=job.id;
 RETURN jsonb_build_object('job',jsonb_build_object('id',job.id,'lead_id',job.lead_id,'state',job.state,
 'requested_model',job.requested_model,'model_version',job.model_version,'prompt_version',job.prompt_version,
 'model_receipt',job.model_receipt,'input_hash',job.input_hash,'input_snapshot',job.input_snapshot,'assessment',job.assessment,
 'error_code',job.error_code,'created_at',job.created_at,'claimed_at',job.claimed_at,'received_at',job.received_at,'completed_at',job.completed_at),
 'freshness',jsonb_build_object('current',coalesce(current_input->>'input_hash'=job.input_hash,false),
 'blocked',current_input->>'blocked','input_hash',current_input->>'input_hash','changed_sections',changes),
 'evaluation',evaluation,'outreach_authorized',false);
END $function$

CREATE OR REPLACE FUNCTION public.lead_retention_calc(l leads, p_dupe boolean DEFAULT false, OUT o_rule text, OUT o_action text, OUT o_due timestamp with time zone, OUT o_deletable boolean, OUT o_reason text)
 RETURNS record
 LANGUAGE plpgsql
 STABLE
 SET search_path TO 'pg_catalog', 'public', 'pg_temp'
AS $function$
DECLARE
  base timestamptz := coalesce(l.created_at, now());
  src text := coalesce(l.source, '');
  untouched boolean;
  d_prefor timestamptz; d_tier timestamptz; d_tax timestamptz;
  tier_rule text;
BEGIN
  o_deletable := false;
  IF coalesce(l.dnc, false) THEN
    o_rule := 'dnc'; o_action := 'keep';
    o_reason := 'DNC / opted out: keep permanently as your suppression record'; RETURN;
  END IF;
  IF coalesce(l.status, '') IN ('appointment_set', 'offer_made', 'under_contract') THEN
    o_rule := 'transaction'; o_action := 'keep'; o_due := base + interval '7 years';
    o_reason := 'Appointment / offer / contract: keep records 7 years'; RETURN;
  END IF;

  -- Distinct website receipts carry consent and follow-up history even when
  -- an address matches an imported record. List cleanup must not erase them.
  IF l.form_submission_id IS NOT NULL
     OR coalesce(l.inbound_channel, '') IN ('web_form', 'web-form')
     OR src IN ('web_form', 'web-form') THEN
    o_rule := 'website_inquiry'; o_action := 'hold'; o_due := NULL;
    o_reason := 'Website inquiry: preserve submission and consent history; review before archive'; RETURN;
  END IF;

  untouched := coalesce(l.status, 'new') IN ('new', 'qualified_hot', 'qualified_warm', 'qualified_cold', 'scoring_error')
               AND coalesce(l.contact_attempts, 0) = 0 AND l.last_contact_date IS NULL;
  IF NOT untouched THEN
    o_rule := 'worked'; o_action := 'hold';
    o_due := coalesce(l.last_contact_date::timestamptz, l.updated_at, base) + interval '12 months';
    o_reason := 'Contacted: hold 12 months from last contact, then archive if no reply'; RETURN;
  END IF;

  o_deletable := true;
  IF coalesce(l.property_type, '') ~* 'business personal|personal property|mineral|utility|inventory' THEN
    o_rule := 'not_real_estate'; o_action := 'hold'; o_due := base;
    o_reason := 'Not real estate (business/personal property record): delete now'; RETURN;
  END IF;
  IF p_dupe THEN
    o_rule := 'duplicates'; o_action := 'hold'; o_due := base;
    o_reason := 'Duplicate of a better-scored copy of this property: delete now'; RETURN;
  END IF;

  -- Earliest of the time-based rules wins, so every lead has exactly one rule.
  d_prefor := CASE WHEN src ~* 'prefor|foreclos' THEN base + interval '60 days' END;
  d_tier := CASE l.status
              WHEN 'qualified_cold' THEN base + interval '90 days'
              WHEN 'qualified_warm' THEN base + interval '180 days' END;
  tier_rule := CASE l.status WHEN 'qualified_cold' THEN 'stale_cold' WHEN 'qualified_warm' THEN 'stale_warm' END;
  d_tax := CASE WHEN src ~* 'delinq|tax roll|tax_roll' THEN base + interval '365 days' END;

  o_due := least(d_prefor, d_tier, d_tax);
  IF o_due IS NULL THEN
    o_rule := 'work'; o_deletable := false; o_action := 'work';
    o_reason := 'Call within 48 hours'; RETURN;
  END IF;
  o_rule := CASE o_due WHEN d_prefor THEN 'stale_prefor' WHEN d_tier THEN tier_rule ELSE 'stale_tax_roll' END;
  o_action := CASE WHEN l.status IN ('qualified_hot', 'qualified_warm', 'new') THEN 'work' ELSE 'hold' END;
  o_reason := CASE o_rule
    WHEN 'stale_prefor'   THEN 'Pre-foreclosure list ages fast: work or re-pull within 60 days, then delete'
    WHEN 'stale_cold'     THEN 'No distress evidence: delete after 90 days if never contacted'
    WHEN 'stale_warm'     THEN 'Warm but never contacted: delete after 180 days'
    ELSE                       'Delinquent tax roll is republished yearly: replace after 12 months' END;
END;
$function$

CREATE OR REPLACE FUNCTION public.lead_retention_row_trigger()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'public', 'pg_temp'
AS $function$
DECLARE r record;
BEGIN
  SELECT * INTO r FROM public.lead_retention_calc(NEW, false);
  -- keep an existing duplicate verdict until the next full refresh
  IF TG_OP = 'UPDATE' AND OLD.retention_rule = 'duplicates' AND r.o_rule NOT IN ('dnc', 'transaction', 'worked', 'website_inquiry') THEN
    RETURN NEW;
  END IF;
  NEW.retention_rule := r.o_rule; NEW.retention_action := r.o_action; NEW.retention_due_at := r.o_due;
  NEW.retention_deletable := r.o_deletable; NEW.retention_reason := r.o_reason;
  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.lead_street_key(raw text)
 RETURNS text
 LANGUAGE plpgsql
 IMMUTABLE PARALLEL SAFE
 SET search_path TO 'pg_catalog', 'public', 'pg_temp'
AS $function$
DECLARE
  s text := lower(coalesce(raw, ''));
BEGIN
  s := regexp_replace(s, '[^a-z0-9 ]+', ' ', 'g');
  s := regexp_replace(s, '\ystreet\y', 'st', 'g');
  s := regexp_replace(s, '\yavenue\y', 'ave', 'g');
  s := regexp_replace(s, '\ydrive\y', 'dr', 'g');
  s := regexp_replace(s, '\ylane\y', 'ln', 'g');
  s := regexp_replace(s, '\yroad\y', 'rd', 'g');
  s := regexp_replace(s, '\ycourt\y', 'ct', 'g');
  s := regexp_replace(s, '\yboulevard\y', 'blvd', 'g');
  s := regexp_replace(s, '\yplace\y', 'pl', 'g');
  s := regexp_replace(s, '\ycircle\y', 'cir', 'g');
  s := regexp_replace(s, '\ytrail\y', 'trl', 'g');
  s := regexp_replace(s, '\yparkway\y', 'pkwy', 'g');
  s := regexp_replace(s, '\yhighway\y', 'hwy', 'g');
  s := regexp_replace(s, '\y(north|south|east|west)\y', '', 'g');
  RETURN btrim(regexp_replace(s, '\s+', ' ', 'g'));
END;
$function$

CREATE OR REPLACE FUNCTION public.list_trace_input(p_lead uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
DECLARE l jsonb; property wholesale_ingest.properties; doc jsonb;
BEGIN
 SELECT to_jsonb(leads) INTO l FROM public.leads WHERE id=p_lead FOR UPDATE;
 IF NOT FOUND THEN RETURN jsonb_build_object('blocked','lead_missing'); END IF;
 SELECT * INTO property FROM wholesale_ingest.properties WHERE lead_id=p_lead;
 IF NOT FOUND THEN RETURN jsonb_build_object('blocked','unverified_pipeline_property'); END IF;
 IF coalesce(nullif(trim(l->>'owner_phone_1'),''),nullif(trim(l->>'owner_phone_2'),''),nullif(trim(l->>'owner_phone_3'),''),nullif(trim(l->>'owner_email'),'')) IS NOT NULL
 OR EXISTS(SELECT 1 FROM wholesale_ingest.contacts WHERE lead_id=p_lead AND expires_at>clock_timestamp())
 THEN RETURN jsonb_build_object('blocked','already_enriched'); END IF;
 doc:=jsonb_build_object('owner_name',coalesce(nullif(trim(concat_ws(' ',l->>'owner_first_name',l->>'owner_last_name')),''),l->>'owner_name'),
  'property_address',l->>'property_address','city',coalesce(nullif(l->>'city',''),property.city),
  'state',property.state,'county',property.county,'property_id',property.id,'parcel_id',property.parcel_id,
  'zip_code',coalesce(nullif(l->>'zip_code',''),property.zip));
 IF coalesce(length(trim(doc->>'owner_name')),0)=0 OR coalesce(length(trim(doc->>'property_address')),0)=0
 OR coalesce(length(trim(doc->>'city')),0)=0 THEN RETURN jsonb_build_object('blocked','identity_incomplete'); END IF;
 RETURN jsonb_build_object('input',doc,'input_hash',encode(sha256(convert_to(doc::text,'UTF8')),'hex'));
END $function$

CREATE OR REPLACE FUNCTION public.next_list_scoring_jobs(p_model text, p_limit integer DEFAULT 5)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
DECLARE job wholesale_ingest.scoring_jobs; candidate record; prepared jsonb; jobs jsonb:='[]'; ids uuid[]:='{}';
BEGIN
 IF coalesce(length(p_model),0) NOT BETWEEN 1 AND 100 OR p_limit IS NULL OR p_limit NOT BETWEEN 1 AND 10 THEN RAISE EXCEPTION 'Invalid worker configuration'; END IF;
 -- Completing received evidence precedes every new paid model request.
 FOR job IN SELECT * FROM wholesale_ingest.scoring_jobs WHERE state='received' OR (state='queued' AND requested_model=p_model)
 ORDER BY CASE WHEN state='received' THEN 0 ELSE 1 END,created_at,id LIMIT p_limit LOOP
  jobs:=jobs||jsonb_build_array(jsonb_build_object('id',job.id,'lead_id',job.lead_id,'requested_model',job.requested_model,'state',job.state));
  ids:=array_append(ids,job.id);
 END LOOP;
 IF jsonb_array_length(jobs)>=p_limit THEN RETURN jsonb_build_object('jobs',jobs); END IF;
 FOR candidate IN
  SELECT p.lead_id,s.snapshot FROM wholesale_ingest.properties p
  CROSS JOIN LATERAL (SELECT public.list_scoring_input(p.lead_id) snapshot) s
  WHERE p.lead_id IS NOT NULL AND NOT (s.snapshot ? 'blocked')
  AND NOT EXISTS(SELECT 1 FROM wholesale_ingest.scoring_jobs j WHERE j.lead_id=p.lead_id AND j.state IN ('queued','submitted','received','review'))
  AND NOT EXISTS(SELECT 1 FROM wholesale_ingest.lead_evaluations e WHERE e.lead_id=p.lead_id AND e.input_hash=s.snapshot->>'input_hash' AND e.prompt_version='daily-list-score-v1' AND e.input_snapshot IS NOT NULL)
  ORDER BY p.created_at,p.id LIMIT (p_limit-jsonb_array_length(jobs)) LOOP
  prepared:=public.prepare_list_score_job(gen_random_uuid(),candidate.lead_id,p_model);
  IF prepared ? 'job' THEN job:=jsonb_populate_record(NULL::wholesale_ingest.scoring_jobs,prepared->'job');
  ELSIF prepared->>'blocked'='existing_job' THEN SELECT * INTO job FROM wholesale_ingest.scoring_jobs WHERE id=(prepared->>'job_id')::uuid;
  ELSE CONTINUE;
  END IF;
  IF job.id IS NOT NULL AND NOT(job.id=ANY(ids)) AND (job.state='received' OR (job.state='queued' AND job.requested_model=p_model)) THEN
   jobs:=jobs||jsonb_build_array(jsonb_build_object('id',job.id,'lead_id',job.lead_id,'requested_model',job.requested_model,'state',job.state));
   ids:=array_append(ids,job.id);
  END IF;
 END LOOP;
 RETURN jsonb_build_object('jobs',jobs);
END $function$

CREATE OR REPLACE FUNCTION public.pick_retell_app_work(p_job uuid DEFAULT NULL::uuid, p_first_turn_only boolean DEFAULT false, p_phones text[] DEFAULT NULL::text[])
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
DECLARE chosen record; updated uuid;
BEGIN
 IF p_first_turn_only IS NULL OR (p_first_turn_only AND p_job IS NULL) THEN RAISE EXCEPTION 'Finite test scope required'; END IF;
 IF p_phones IS NOT NULL AND EXISTS(SELECT 1 FROM unnest(p_phones) p WHERE p IS NULL OR p !~ '^\+1[0-9]{10}$') THEN RAISE EXCEPTION 'Invalid recipient scope'; END IF;
 IF NOT pg_try_advisory_xact_lock(hashtextextended('wholesaleos:retell-app-select',0)) THEN
  RETURN jsonb_build_object('selected',false,'reason','selection_busy'); END IF;
 SELECT * INTO chosen FROM (
  SELECT 'ack'::text action,j.id reference,j.id job_id,2 priority,j.due_at due_at
  FROM public.retell_form_sms_jobs j
  WHERE j.delivery_transport='app_twilio' AND j.status='scheduled' AND j.due_at<=now() AND j.expires_at>now()
   AND (p_job IS NULL OR j.id=p_job) AND (p_phones IS NULL OR j.phone_number=ANY(p_phones))
   AND (j.auto_selected_at IS NULL OR j.auto_selected_at<=now()-interval '90 seconds')
  UNION ALL
  SELECT CASE WHEN t.status='generated' THEN 'reply' ELSE 'generate' END,t.id,s.id,
   CASE WHEN t.status='generated' THEN 0 ELSE 1 END,t.created_at
  FROM public.retell_api_turns t JOIN public.retell_api_sessions s ON s.id=t.session_id
  JOIN public.retell_form_sms_jobs j ON j.id=s.id
  WHERE j.delivery_transport='app_twilio' AND j.status='accepted' AND t.expires_at>now()
   AND ((t.status='queued' AND s.status IN ('pending','ready')) OR (t.status='generated' AND s.status='ready'))
   AND (p_job IS NULL OR s.id=p_job) AND (p_phones IS NULL OR s.phone_number=ANY(p_phones))
   AND (t.auto_selected_at IS NULL OR t.auto_selected_at<=now()-interval '90 seconds')
   AND t.id=(SELECT x.id FROM public.retell_api_turns x WHERE x.session_id=s.id AND x.status NOT IN ('accepted','stopped') ORDER BY x.created_at,x.id LIMIT 1)
   AND (NOT p_first_turn_only OR t.id=(SELECT x.id FROM public.retell_api_turns x WHERE x.session_id=s.id ORDER BY x.created_at,x.id LIMIT 1))
 ) candidates ORDER BY priority,due_at,reference LIMIT 1;
 IF NOT FOUND THEN RETURN jsonb_build_object('selected',false,'reason','no_due_work'); END IF;
 IF chosen.action='ack' THEN
  UPDATE public.retell_form_sms_jobs SET auto_selected_at=now()
   WHERE id=chosen.reference AND status='scheduled' RETURNING id INTO updated;
 ELSE
  UPDATE public.retell_api_turns SET auto_selected_at=now()
   WHERE id=chosen.reference AND status=CASE WHEN chosen.action='reply' THEN 'generated' ELSE 'queued' END RETURNING id INTO updated;
 END IF;
 IF updated IS NULL THEN RETURN jsonb_build_object('selected',false,'reason','state_changed'); END IF;
 RETURN jsonb_build_object('selected',true,'action',chosen.action,'reference',chosen.reference,'job_id',chosen.job_id,'dispatch_authorized',false);
END $function$

CREATE OR REPLACE FUNCTION public.prepare_list_score_job(p_id uuid, p_lead uuid, p_model text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
DECLARE job wholesale_ingest.scoring_jobs; snapshot jsonb;
BEGIN
 IF p_id IS NULL OR p_lead IS NULL OR coalesce(length(p_model),0) NOT BETWEEN 1 AND 100 THEN RETURN jsonb_build_object('blocked','invalid_identity'); END IF;
 PERFORM pg_advisory_xact_lock(hashtextextended('score-job-id:'||p_id::text,0));
 PERFORM pg_advisory_xact_lock(hashtextextended('score-job-lead:'||p_lead::text,0));
 SELECT * INTO job FROM wholesale_ingest.scoring_jobs WHERE id=p_id;
 IF FOUND THEN
  IF job.lead_id<>p_lead OR job.requested_model<>p_model THEN RETURN jsonb_build_object('blocked','reference_conflict'); END IF;
  RETURN jsonb_build_object('job',to_jsonb(job),'replayed',true);
 END IF;
 snapshot:=public.list_scoring_input(p_lead);
 IF snapshot ? 'blocked' THEN RETURN snapshot; END IF;
 SELECT * INTO job FROM wholesale_ingest.scoring_jobs WHERE lead_id=p_lead AND state<>'obsolete'
 AND ((input_hash=snapshot->>'input_hash' AND requested_model=p_model AND prompt_version='daily-list-score-v1')
 OR state IN ('queued','submitted','received','review')) ORDER BY created_at,id LIMIT 1;
 IF FOUND THEN RETURN jsonb_build_object('blocked','existing_job','job_id',job.id,'state',job.state); END IF;
 INSERT INTO wholesale_ingest.scoring_jobs(id,lead_id,input_hash,input_snapshot,requested_model,prompt_version)
 VALUES(p_id,p_lead,snapshot->>'input_hash',snapshot->'input',p_model,'daily-list-score-v1') RETURNING * INTO job;
 RETURN jsonb_build_object('job',to_jsonb(job),'replayed',false);
END $function$

CREATE OR REPLACE FUNCTION public.prepare_list_trace(p_id uuid, p_lead uuid, p_provider text, p_max_cents integer)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
DECLARE snapshot jsonb; result jsonb; saved wholesale_ingest.skip_trace_requests;
BEGIN
 IF p_id IS NULL OR p_lead IS NULL THEN RETURN jsonb_build_object('blocked','invalid_request'); END IF;
 PERFORM pg_advisory_xact_lock(hashtextextended('trace-request:'||p_id::text,0));
 PERFORM pg_advisory_xact_lock(hashtextextended('trace-lead:'||p_lead::text,0));
 SELECT * INTO saved FROM wholesale_ingest.skip_trace_requests WHERE id=p_id;
 IF FOUND THEN
  IF saved.lead_id IS DISTINCT FROM p_lead OR saved.provider IS DISTINCT FROM p_provider OR saved.reserved_cents IS DISTINCT FROM p_max_cents
  THEN RETURN jsonb_build_object('blocked','reference_conflict'); END IF;
  RETURN jsonb_build_object('request',to_jsonb(saved),'input',saved.input_snapshot,'replayed',true,'dispatch',false,
   'contacts_saved',(SELECT count(*) FROM wholesale_ingest.contacts WHERE trace_request_id=p_id));
 END IF;
 snapshot:=public.list_trace_input(p_lead);
 IF snapshot ? 'blocked' THEN RETURN snapshot; END IF;
 result:=public.reserve_list_trace(p_id,p_lead,p_provider,snapshot->>'input_hash',p_max_cents);
 IF result ? 'blocked' THEN RETURN result; END IF;
 UPDATE wholesale_ingest.skip_trace_requests SET input_snapshot=snapshot->'input' WHERE id=p_id RETURNING * INTO saved;
 RETURN result||jsonb_build_object('request',to_jsonb(saved),'input',snapshot->'input');
END $function$

CREATE OR REPLACE FUNCTION public.propstream_bulk_action(p_batch uuid, p_operator uuid, p_items jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
DECLARE old wholesale_ingest.propstream_batches; item jsonb; results jsonb:='[]'; result jsonb; fingerprint text; action text; quote bigint; balance bigint;
BEGIN
 IF NOT EXISTS(SELECT 1 FROM public.profiles WHERE id=p_operator AND role='admin' AND status='approved') THEN RAISE EXCEPTION 'Approved administrator required'; END IF;
 IF p_batch IS NULL OR jsonb_typeof(p_items) IS DISTINCT FROM 'array' THEN RAISE EXCEPTION 'Batch items required'; END IF;
 IF jsonb_array_length(p_items) NOT BETWEEN 1 AND 500 THEN RAISE EXCEPTION 'Batch requires 1 to 500 leads'; END IF;
 fingerprint:=encode(sha256(convert_to(p_items::text,'UTF8')),'hex');
 PERFORM pg_advisory_xact_lock(hashtextextended('propstream-batch:'||p_batch::text,0));
 IF EXISTS(SELECT 1 FROM wholesale_ingest.propstream_abandoned_events WHERE id=p_batch) THEN RAISE EXCEPTION 'Batch abandoned during recovery'; END IF;
 SELECT * INTO old FROM wholesale_ingest.propstream_batches WHERE id=p_batch;
 IF FOUND THEN
  IF old.operator_id<>p_operator OR old.payload_hash<>fingerprint THEN RAISE EXCEPTION 'Batch reference conflict'; END IF;
  RETURN old.result||jsonb_build_object('replayed',true,'dispatch',false);
 END IF;
 SELECT min(v->>'action') INTO action FROM jsonb_array_elements(p_items) v;
 IF EXISTS(SELECT 1 FROM jsonb_array_elements(p_items) v WHERE v->>'action' IS DISTINCT FROM action)
 OR (SELECT count(DISTINCT v->>'lead_id') FROM jsonb_array_elements(p_items) v)<>jsonb_array_length(p_items)
 OR (SELECT count(DISTINCT v->>'event_id') FROM jsonb_array_elements(p_items) v)<>jsonb_array_length(p_items)
 OR (SELECT count(DISTINCT v->>'request_id') FROM jsonb_array_elements(p_items) v)<>jsonb_array_length(p_items)
 THEN RAISE EXCEPTION 'One action and unique lead, request and event per batch required'; END IF;
 IF action='prepare' THEN
  SELECT sum((v->'payload'->>'quote_cents')::bigint),min((v->'payload'->>'prepaid_balance_cents')::bigint) INTO quote,balance FROM jsonb_array_elements(p_items) v;
  IF quote>balance OR quote>5000 THEN RAISE EXCEPTION 'Batch quote exceeds confirmed balance or total cap'; END IF;
 END IF;
 -- All member locks are ordered; one failed row rolls back every member.
 FOR item IN SELECT v FROM jsonb_array_elements(p_items) v ORDER BY v->>'lead_id' LOOP
  result:=public.propstream_handoff_action((item->>'event_id')::uuid,p_operator,(item->>'request_id')::uuid,(item->>'lead_id')::uuid,item->>'action',item->'payload');
  IF coalesce((result->>'replayed')::boolean,false) THEN RAISE EXCEPTION 'Member action already used; recover its original batch'; END IF;
  IF action='start' AND result->'dispatch' IS DISTINCT FROM 'true'::jsonb THEN RAISE EXCEPTION 'Batch member is not newly submitted'; END IF;
  results:=results||jsonb_build_array(result);
 END LOOP;
 result:=jsonb_build_object('batch_id',p_batch,'operator_id',p_operator,'action',action,'count',jsonb_array_length(p_items),'results',results,'dispatch',action='start','replayed',false,'outreach_authorized',false);
 INSERT INTO wholesale_ingest.propstream_batches(id,operator_id,payload_hash,result) VALUES(p_batch,p_operator,fingerprint,result);
 RETURN result;
END $function$

CREATE OR REPLACE FUNCTION public.propstream_bulk_recover(p_batch uuid, p_operator uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
DECLARE old wholesale_ingest.propstream_batches;
BEGIN
 IF NOT EXISTS(SELECT 1 FROM public.profiles WHERE id=p_operator AND role='admin' AND status='approved') THEN RAISE EXCEPTION 'Approved administrator required'; END IF;
 PERFORM pg_advisory_xact_lock(hashtextextended('propstream-batch:'||p_batch::text,0));
 SELECT * INTO old FROM wholesale_ingest.propstream_batches WHERE id=p_batch;
 IF FOUND AND old.operator_id<>p_operator THEN RAISE EXCEPTION 'Actor mismatch'; END IF;
 IF old.id IS NULL THEN
  INSERT INTO wholesale_ingest.propstream_abandoned_events(id,operator_id) VALUES(p_batch,p_operator) ON CONFLICT DO NOTHING;
  IF NOT EXISTS(SELECT 1 FROM wholesale_ingest.propstream_abandoned_events WHERE id=p_batch AND operator_id=p_operator) THEN RAISE EXCEPTION 'Actor mismatch'; END IF;
 END IF;
 RETURN jsonb_build_object('batch_id',p_batch,'settled',true,'result',old.result);
END $function$

CREATE OR REPLACE FUNCTION public.propstream_handoff_action(p_event uuid, p_operator uuid, p_request uuid, p_lead uuid, p_action text, p_payload jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
DECLARE old wholesale_ingest.propstream_events; saved wholesale_ingest.skip_trace_requests; h wholesale_ingest.propstream_handoffs;
 signal wholesale_ingest.distress_signals; input jsonb; result jsonb; lead jsonb; signal_hash text; task uuid; host text; owner_id uuid;
BEGIN
 IF NOT EXISTS(SELECT 1 FROM public.profiles WHERE id=p_operator AND role='admin' AND status='approved') THEN RAISE EXCEPTION 'Approved administrator required'; END IF;
 IF p_event IS NULL OR p_request IS NULL OR p_lead IS NULL OR p_action IS NULL OR p_action NOT IN ('prepare','start','reconcile','review_status') OR jsonb_typeof(p_payload) IS DISTINCT FROM 'object' THEN RAISE EXCEPTION 'Invalid handoff'; END IF;
 PERFORM pg_advisory_xact_lock(hashtextextended('propstream-event:'||p_event::text,0));
 IF EXISTS(SELECT 1 FROM wholesale_ingest.propstream_abandoned_events WHERE id=p_event) THEN RAISE EXCEPTION 'Saved action abandoned during recovery'; END IF;
 SELECT * INTO old FROM wholesale_ingest.propstream_events WHERE id=p_event;
 IF FOUND THEN
  IF old.operator_id<>p_operator OR old.result->>'request_id' IS DISTINCT FROM p_request::text OR old.action<>p_action OR old.payload_hash IS DISTINCT FROM encode(sha256(convert_to((p_payload||jsonb_build_object('lead_id',p_lead))::text,'UTF8')),'hex') THEN RAISE EXCEPTION 'Handoff reference conflict'; END IF;
  RETURN old.result||jsonb_build_object('replayed',true,'dispatch',false);
 END IF;
 -- Match the core lead reservation lock before inspecting/changing handoff state.
 PERFORM pg_advisory_xact_lock(hashtextextended('trace-lead:'||p_lead::text,0));
 SELECT to_jsonb(l) INTO lead FROM public.leads l WHERE id=p_lead FOR UPDATE;
 IF lead IS NULL THEN RAISE EXCEPTION 'Lead missing'; END IF;
 IF p_action='review_status' THEN
  IF (p_payload-ARRAY['signal_id','signal_hash','active','auction_date','status_evidence_url','notes','confirmed_current_status'])<>'{}'::jsonb
   OR p_payload->'confirmed_current_status' IS DISTINCT FROM 'true'::jsonb
   OR jsonb_typeof(p_payload->'active') IS DISTINCT FROM 'boolean'
   OR coalesce(length(trim(p_payload->>'notes')),0) NOT BETWEEN 20 AND 2000
   THEN RAISE EXCEPTION 'Current status review and evidence required'; END IF;
  SELECT s.* INTO signal FROM wholesale_ingest.distress_signals s JOIN wholesale_ingest.properties p ON p.id=s.property_id
   WHERE s.id=(p_payload->>'signal_id')::uuid AND p.lead_id=p_lead AND s.list_type='pre_foreclosure' FOR UPDATE OF s;
  IF signal.id IS NULL THEN RAISE EXCEPTION 'Matching foreclosure signal required'; END IF;
  signal_hash:=md5(jsonb_build_object('id',signal.id,'active',signal.active,'auction_date',signal.auction_date,'last_run_id',signal.last_run_id,'last_seen_at',signal.last_seen_at,'status_review_id',signal.status_review_id)::text);
  IF p_payload->>'signal_hash' IS DISTINCT FROM signal_hash THEN RAISE EXCEPTION 'Foreclosure evidence changed'; END IF;
  host:=p_payload->>'status_evidence_url';
  IF NOT wholesale_ingest.foreclosure_status_evidence_allowed(p_lead,(SELECT county FROM wholesale_ingest.sources WHERE id=signal.source_id),host) THEN RAISE EXCEPTION 'Property-bound current-sale evidence required'; END IF;
  IF coalesce(p_payload->>'auction_date','') !~ '^[0-9]{4}-[0-9]{2}-[0-9]{2}$' THEN RAISE EXCEPTION 'Exact sale date required'; END IF;
  IF (p_payload->>'active')::boolean AND ((p_payload->>'auction_date')::date<(clock_timestamp() AT TIME ZONE 'America/Chicago')::date
   OR coalesce((lead->>'dnc')::boolean,false) OR lead->>'status' IN ('dnc','dead','sold','under_contract')) THEN RAISE EXCEPTION 'Active sale cannot be past or suppressed'; END IF;
  -- Changing this version invalidates any previously reserved quote at claim time.
  -- Submitted provider orders remain reconcilable even when a sale is canceled.
  UPDATE wholesale_ingest.distress_signals SET active=(p_payload->>'active')::boolean,
   auction_date=(p_payload->>'auction_date')::date,status_review_id=p_event WHERE id=signal.id;
  result:=jsonb_build_object('status_reviewed',true,'signal_id',signal.id,'active',(p_payload->>'active')::boolean,'dispatch',false);
 ELSIF p_action='prepare' THEN
  IF (p_payload-ARRAY['input_hash','signal_id','signal_hash','quote_cents','prepaid_balance_cents','quote_reference','owner_evidence_url','status_evidence_url','notes','all_pages_reviewed'])<>'{}'::jsonb THEN RAISE EXCEPTION 'Unexpected prepare fields'; END IF;
  IF coalesce((lead->>'dnc')::boolean,false) OR lead->>'status' IN ('dnc','dead','sold','under_contract') THEN RAISE EXCEPTION 'Lead suppressed'; END IF;
  SELECT s.* INTO signal FROM wholesale_ingest.distress_signals s JOIN wholesale_ingest.properties p ON p.id=s.property_id
   WHERE s.id=(p_payload->>'signal_id')::uuid AND p.lead_id=p_lead AND s.list_type='pre_foreclosure' FOR UPDATE OF s;
  IF signal.id IS NULL OR NOT signal.active OR signal.auction_date IS NULL OR signal.auction_date<(clock_timestamp() AT TIME ZONE 'America/Chicago')::date THEN RAISE EXCEPTION 'Current active foreclosure evidence required'; END IF;
  signal_hash:=md5(jsonb_build_object('id',signal.id,'active',signal.active,'auction_date',signal.auction_date,'last_run_id',signal.last_run_id,'last_seen_at',signal.last_seen_at,'status_review_id',signal.status_review_id)::text);
  IF p_payload->>'signal_hash' IS DISTINCT FROM signal_hash THEN RAISE EXCEPTION 'Foreclosure evidence changed'; END IF;
  IF p_payload->'all_pages_reviewed' IS DISTINCT FROM 'true'::jsonb OR coalesce(length(trim(p_payload->>'notes')),0) NOT BETWEEN 20 AND 2000 OR coalesce(length(trim(p_payload->>'quote_reference')),0) NOT BETWEEN 3 AND 255 THEN RAISE EXCEPTION 'Notice review and exact quote reference required'; END IF;
  FOREACH host IN ARRAY ARRAY[p_payload->>'owner_evidence_url'] LOOP
   IF coalesce(length(host),0)>2000 OR substring(lower(host) from '^https://([^/:?#]+)(?:[/:?#]|$)') IS NULL OR
    substring(lower(host) from '^https://([^/:?#]+)(?:[/:?#]|$)')<>ALL(CASE WHEN (SELECT county FROM wholesale_ingest.sources WHERE id=signal.source_id)='Dallas' THEN ARRAY['www.dallascad.org','dallascad.org','www.dallascounty.org','dallas.tx.publicsearch.us'] ELSE ARRAY['www.collincad.org','collincad.org','www.collincountytx.gov','collincountytx.gov','gis.collincountytx.gov','apps.collincountytx.gov','apps2.collincountytx.gov','esearch.collincad.org'] END) THEN RAISE EXCEPTION 'Official owner and status evidence required'; END IF;
  END LOOP;
  IF NOT wholesale_ingest.foreclosure_status_evidence_allowed(p_lead,(SELECT county FROM wholesale_ingest.sources WHERE id=signal.source_id),p_payload->>'status_evidence_url') THEN RAISE EXCEPTION 'Property-bound current-sale evidence required'; END IF;
  IF coalesce(p_payload->>'quote_cents','') !~ '^[1-9][0-9]{0,3}$' OR (p_payload->>'quote_cents')::int>5000 OR coalesce(p_payload->>'prepaid_balance_cents','') !~ '^[0-9]{1,9}$' OR (p_payload->>'quote_cents')::int>(p_payload->>'prepaid_balance_cents')::int THEN RAISE EXCEPTION 'Quote exceeds confirmed prepaid balance or total cap'; END IF;
  input:=public.list_trace_input(p_lead);
  IF input ? 'blocked' OR input->>'input_hash' IS DISTINCT FROM p_payload->>'input_hash' THEN RAISE EXCEPTION 'Trace identity unavailable or changed: %',input->>'blocked'; END IF;
  INSERT INTO wholesale_ingest.daily_budgets(spend_day,cap_cents) VALUES((clock_timestamp() AT TIME ZONE 'America/Chicago')::date,5000) ON CONFLICT DO NOTHING;
  result:=public.prepare_list_trace(p_request,p_lead,'propstream', (p_payload->>'quote_cents')::int);
  IF result ? 'blocked' THEN RAISE EXCEPTION 'Trace reservation blocked: %',result->>'blocked'; END IF;
  IF result->>'replayed'='true' THEN RAISE EXCEPTION 'Request already exists; recover its original event'; END IF;
  INSERT INTO wholesale_ingest.propstream_handoffs(request_id,operator_id,review,signal_id,signal_hash) VALUES(p_request,p_operator,p_payload,signal.id,signal_hash);
 ELSE
  SELECT * INTO saved FROM wholesale_ingest.skip_trace_requests WHERE id=p_request FOR UPDATE;
  SELECT * INTO h FROM wholesale_ingest.propstream_handoffs WHERE request_id=p_request FOR UPDATE;
  IF saved.id IS NULL OR h.request_id IS NULL OR saved.lead_id<>p_lead OR saved.provider<>'propstream' THEN RAISE EXCEPTION 'Matching PropStream handoff required'; END IF;
  IF p_action='start' THEN
   IF p_payload<>jsonb_build_object('input_hash',saved.input_hash) THEN RAISE EXCEPTION 'Input mismatch'; END IF;
   IF coalesce((lead->>'dnc')::boolean,false) OR lead->>'status' IN ('dnc','dead','sold','under_contract') THEN RAISE EXCEPTION 'Lead suppressed'; END IF;
   SELECT * INTO signal FROM wholesale_ingest.distress_signals WHERE id=h.signal_id FOR UPDATE;
   signal_hash:=md5(jsonb_build_object('id',signal.id,'active',signal.active,'auction_date',signal.auction_date,'last_run_id',signal.last_run_id,'last_seen_at',signal.last_seen_at,'status_review_id',signal.status_review_id)::text);
   IF signal_hash<>h.signal_hash OR NOT signal.active OR signal.auction_date<(clock_timestamp() AT TIME ZONE 'America/Chicago')::date OR h.created_at<clock_timestamp()-interval '24 hours' THEN RAISE EXCEPTION 'Recheck current foreclosure evidence'; END IF;
   result:=public.claim_list_trace(p_request,saved.input_hash);
  ELSE
   IF (p_payload-ARRAY['input_hash','actual_cents','provider_receipt','contacts','confirmed_match'])<>'{}'::jsonb OR p_payload->'confirmed_match' IS DISTINCT FROM 'true'::jsonb OR p_payload->>'input_hash' IS DISTINCT FROM saved.input_hash OR coalesce(p_payload->>'actual_cents','') !~ '^[0-9]{1,4}$' THEN RAISE EXCEPTION 'Matching provider result and cost required'; END IF;
   result:=public.complete_list_trace(p_request,'propstream',saved.input_hash,(p_payload->>'actual_cents')::int,p_payload->>'provider_receipt',p_payload->'contacts');
   IF NOT (result ? 'blocked') AND h.follow_up_task_id IS NULL THEN
    SELECT p.id INTO owner_id FROM public.app_settings a JOIN public.profiles p ON p.id::text=a.value AND p.status='approved' WHERE a.key='lead_owner_user_id';
    owner_id:=coalesce(owner_id,p_operator);task:=gen_random_uuid();
    INSERT INTO public.tasks(id,title,description,status,priority,type,assigned_to,due_date,lead_id)
     VALUES(task,CASE WHEN (result->>'contacts_saved')::int>0 THEN 'Foreclosure contact found — review outreach eligibility' ELSE 'Foreclosure trace returned no contacts — review next action' END,
      'Lead '||p_lead||'; PropStream request '||p_request||'. Review matched contacts and channel eligibility in Daily Lists. No outreach authorized or sent.', 'pending','high','follow_up',owner_id,clock_timestamp(),p_lead);
    UPDATE wholesale_ingest.propstream_handoffs SET follow_up_task_id=task WHERE request_id=p_request;
    result:=result||jsonb_build_object('follow_up_task_id',task);
   END IF;
  END IF;
  IF result ? 'blocked' THEN RAISE EXCEPTION 'Trace handoff blocked: %',result->>'blocked'; END IF;
 END IF;
 result:=result||jsonb_build_object('event_id',p_event,'request_id',p_request,'lead_id',p_lead,'operator_id',p_operator,'action',p_action,'outreach_authorized',false);
 INSERT INTO wholesale_ingest.propstream_events(id,operator_id,request_id,action,payload_hash,result,status_review) VALUES(p_event,p_operator,CASE WHEN p_action='review_status' THEN NULL ELSE p_request END,p_action,encode(sha256(convert_to((p_payload||jsonb_build_object('lead_id',p_lead))::text,'UTF8')),'hex'),result,CASE WHEN p_action='review_status' THEN p_payload END);
 RETURN result;
END; $function$

CREATE OR REPLACE FUNCTION public.propstream_handoff_snapshot(p_operator uuid, p_offset integer DEFAULT 0)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
DECLARE items jsonb:='[]'; p record; input jsonb; trace jsonb; stage text;
BEGIN
 IF NOT EXISTS(SELECT 1 FROM public.profiles WHERE id=p_operator AND role='admin' AND status='approved') THEN RAISE EXCEPTION 'Approved administrator required'; END IF;
 IF p_offset IS NULL OR p_offset<0 THEN RAISE EXCEPTION 'Invalid offset'; END IF;
 FOR p IN SELECT pr.lead_id,pr.county,pr.address_std,pr.city,pr.zip,l.status,coalesce((to_jsonb(l)->>'dnc')::boolean,false) AS dnc,
 sg.id AS signal_id,sg.auction_date,sg.active,sg.source_url,
 md5(jsonb_build_object('id',sg.id,'active',sg.active,'auction_date',sg.auction_date,'last_run_id',sg.last_run_id,'last_seen_at',sg.last_seen_at,'status_review_id',sg.status_review_id)::text) AS signal_hash
 FROM wholesale_ingest.properties pr JOIN public.leads l ON l.id=pr.lead_id
 JOIN LATERAL(SELECT * FROM wholesale_ingest.distress_signals s WHERE s.property_id=pr.id AND s.list_type='pre_foreclosure' ORDER BY s.active DESC,s.auction_date DESC NULLS LAST,s.id LIMIT 1) sg ON true
 ORDER BY sg.auction_date NULLS LAST,pr.lead_id LIMIT 50 OFFSET p_offset LOOP
  input:=public.list_trace_input(p.lead_id);
  SELECT to_jsonb(r) INTO trace FROM wholesale_ingest.skip_trace_requests r WHERE r.lead_id=p.lead_id ORDER BY created_at DESC,id DESC LIMIT 1;
  stage:=CASE WHEN trace->>'state' IN ('submitted','unknown') THEN 'reconciliation_required'
   WHEN p.dnc OR p.status IN ('dnc','dead','sold','under_contract') THEN 'suppressed'
   WHEN trace->>'state'='reserved' THEN 'reserved'
   WHEN trace->>'state'='completed' THEN 'result_saved'
   WHEN NOT p.active OR p.auction_date IS NULL OR p.auction_date<(clock_timestamp() AT TIME ZONE 'America/Chicago')::date THEN 'current_status_review'
   WHEN input ? 'blocked' THEN input->>'blocked' ELSE 'quote_and_evidence_required' END;
  items:=items||jsonb_build_array(to_jsonb(p)||jsonb_build_object('stage',stage,'input',input->'input','input_hash',input->'input_hash',
   'request',trace,'contacts',(SELECT coalesce(jsonb_agg(jsonb_build_object('id',id,'name',name,'phone',phone,'email',email,'dnc_status',dnc_status,'expires_at',expires_at)),'[]') FROM wholesale_ingest.contacts WHERE trace_request_id=(trace->>'id')::uuid),
   'handoff',(SELECT to_jsonb(h) FROM wholesale_ingest.propstream_handoffs h WHERE request_id=(trace->>'id')::uuid)));
 END LOOP;
 RETURN jsonb_build_object('total_budget',public.list_trace_total_budget(),'items',items,'total',
 (SELECT count(*) FROM wholesale_ingest.properties pr WHERE EXISTS(SELECT 1 FROM wholesale_ingest.distress_signals s WHERE s.property_id=pr.id AND s.list_type='pre_foreclosure')));
END; $function$

CREATE OR REPLACE FUNCTION public.propstream_recover_event(p_operator uuid, p_event uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
DECLARE e wholesale_ingest.propstream_events;
BEGIN
 IF NOT EXISTS(SELECT 1 FROM public.profiles WHERE id=p_operator AND role='admin' AND status='approved') THEN RAISE EXCEPTION 'Approved administrator required'; END IF;
 PERFORM pg_advisory_xact_lock(hashtextextended('propstream-event:'||p_event::text,0));
 SELECT * INTO e FROM wholesale_ingest.propstream_events WHERE id=p_event;
 IF FOUND AND e.operator_id<>p_operator THEN RAISE EXCEPTION 'Actor mismatch'; END IF;
 IF e.id IS NULL THEN
  INSERT INTO wholesale_ingest.propstream_abandoned_events(id,operator_id) VALUES(p_event,p_operator) ON CONFLICT DO NOTHING;
  IF NOT EXISTS(SELECT 1 FROM wholesale_ingest.propstream_abandoned_events WHERE id=p_event AND operator_id=p_operator) THEN RAISE EXCEPTION 'Actor mismatch'; END IF;
 END IF;
 RETURN jsonb_build_object('event_id',p_event,'result',e.result,'settled',true);
END; $function$

CREATE OR REPLACE FUNCTION public.receive_list_score_job(p_id uuid, p_token uuid, p_model text, p_receipt text, p_result jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
DECLARE job wholesale_ingest.scoring_jobs;
BEGIN
 SELECT * INTO job FROM wholesale_ingest.scoring_jobs WHERE id=p_id FOR UPDATE;
 IF NOT FOUND THEN RETURN jsonb_build_object('blocked','job_missing'); END IF;
 IF p_token IS NULL OR job.claim_token IS DISTINCT FROM p_token OR job.requested_model IS DISTINCT FROM p_model
 OR coalesce(length(p_receipt),0) NOT BETWEEN 1 AND 255 OR jsonb_typeof(p_result) IS DISTINCT FROM 'object'
 OR octet_length(p_result::text)>65536 THEN RETURN jsonb_build_object('blocked','receipt_identity_mismatch'); END IF;
 IF job.assessment IS NOT NULL THEN
  IF job.model_version IS DISTINCT FROM p_model OR job.model_receipt IS DISTINCT FROM p_receipt OR job.assessment IS DISTINCT FROM p_result
  THEN RETURN jsonb_build_object('blocked','receipt_conflict'); END IF;
  RETURN jsonb_build_object('job',to_jsonb(job),'replayed',true);
 END IF;
 IF job.state<>'submitted' THEN RETURN jsonb_build_object('blocked','not_submitted'); END IF;
 UPDATE wholesale_ingest.scoring_jobs SET state='received',model_version=p_model,model_receipt=p_receipt,assessment=p_result,received_at=clock_timestamp()
 WHERE id=p_id RETURNING * INTO job;
 RETURN jsonb_build_object('job',to_jsonb(job),'replayed',false);
END $function$

CREATE OR REPLACE FUNCTION public.reconcile_list_digests()
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
DECLARE d wholesale_ingest.daily_digests; m public.email_messages; delivered timestamptz; adverse boolean;
 owner_id uuid; task uuid; deadline timestamptz; outcome text; err text;
BEGIN
 IF NOT pg_try_advisory_xact_lock(hashtextextended('wholesaleos:list-digest-reconcile',0)) THEN RETURN jsonb_build_object('busy',true); END IF;
 SELECT p.id INTO owner_id FROM public.app_settings a JOIN public.profiles p ON p.id::text=a.value
 WHERE a.key='lead_owner_user_id' AND p.status='approved' LIMIT 1;
 FOR d IN SELECT * FROM wholesale_ingest.daily_digests WHERE day<=(now() AT TIME ZONE 'America/Chicago')::date
 AND day>=(now() AT TIME ZONE 'America/Chicago')::date-7 FOR UPDATE
 LOOP
  SELECT * INTO m FROM public.email_messages WHERE id=d.message_id AND recipient=d.recipient AND provider='sendgrid';
  SELECT coalesce(bool_or(event IN ('bounce','dropped','spamreport','unsubscribe','group_unsubscribe')),false)
  INTO adverse FROM public.email_delivery_events
  WHERE message_id=m.id AND recipient=d.recipient AND event IN ('delivered','bounce','dropped','spamreport','unsubscribe','group_unsubscribe');
  -- Only a matching delivered event is evidence of delivery; other event timestamps are not.
  SELECT min(occurred_at) INTO delivered FROM public.email_delivery_events WHERE message_id=m.id AND recipient=d.recipient AND event='delivered';
  deadline:=(d.day+time '07:30') AT TIME ZONE 'America/Chicago';
  outcome:=CASE WHEN adverse THEN 'review' WHEN delivered IS NOT NULL THEN 'delivered'
    WHEN m.status='accepted' THEN 'accepted' WHEN m.id IS NOT NULL THEN 'review' ELSE d.status END;
  err:=CASE WHEN adverse THEN 'provider_failure_or_suppression' WHEN m.id IS NOT NULL AND m.status<>'accepted' AND delivered IS NULL THEN 'uncertain_email_attempt' ELSE NULL END;
  IF now()>=deadline AND delivered IS NULL THEN outcome:='review';err:=coalesce(err,'delivery_unconfirmed_by_deadline'); END IF;
  UPDATE wholesale_ingest.daily_digests SET status=outcome,error_code=err,
   accepted_at=CASE WHEN m.status='accepted' OR delivered IS NOT NULL THEN coalesce(accepted_at,now()) ELSE accepted_at END,
   delivered_at=coalesce(delivered_at,delivered) WHERE day=d.day;
  IF outcome='review' AND owner_id IS NOT NULL AND d.alert_task_id IS NULL THEN
   task:=gen_random_uuid();
   INSERT INTO public.tasks(id,title,description,status,priority,type,assigned_to,due_date)
   VALUES(task,'Daily digest delivery needs review',d.day||': '||err||'. Inspect the saved email receipt. Do not resend an uncertain attempt.','pending','high','follow_up',owner_id,now());
   UPDATE wholesale_ingest.daily_digests SET alert_task_id=task WHERE day=d.day;
  END IF;
 END LOOP;
 RETURN jsonb_build_object('digests',(SELECT coalesce(jsonb_agg(jsonb_build_object('day',day,'message_id',message_id,'status',status,'accepted_at',accepted_at,'delivered_at',delivered_at,'error_code',error_code,'on_time',CASE WHEN delivered_at IS NULL THEN NULL ELSE delivered_at<=(day+time '07:30') AT TIME ZONE 'America/Chicago' END) ORDER BY day DESC),'[]') FROM wholesale_ingest.daily_digests WHERE day>=(now() AT TIME ZONE 'America/Chicago')::date-7));
END; $function$

CREATE OR REPLACE FUNCTION public.record_sendgrid_events(p_events jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
DECLARE e jsonb; v_email text; v_id text; v_msg uuid; v_new text; v_stop boolean;
BEGIN
 IF jsonb_typeof(p_events)<>'array' OR jsonb_array_length(p_events)>1000 THEN RAISE EXCEPTION 'Invalid batch'; END IF;
 FOR e IN SELECT value FROM jsonb_array_elements(p_events) LOOP
  v_email:=lower(trim(e->>'email')); v_id:=e->>'event_id'; v_msg:=NULL;
  IF coalesce(v_email,'')='' OR coalesce(v_id,'')='' THEN RAISE EXCEPTION 'Invalid event'; END IF;
  PERFORM pg_advisory_xact_lock(hashtextextended(v_email,0));
  IF e->>'message_id' IS NOT NULL THEN
   SELECT id INTO v_msg FROM public.email_messages WHERE id=(e->>'message_id')::uuid AND recipient=v_email AND provider='sendgrid';
  END IF;
  INSERT INTO public.email_delivery_events(event_id,message_id,recipient,event,occurred_at,payload)
  VALUES(v_id,v_msg,v_email,e->>'event',to_timestamp((e->>'timestamp')::double precision),e)
  ON CONFLICT(event_id) DO NOTHING RETURNING event_id INTO v_new;
  IF v_new IS NULL THEN CONTINUE; END IF;
  v_stop:=e->>'event' IN ('unsubscribe','group_unsubscribe','spamreport','bounce');
  IF v_stop THEN
   INSERT INTO public.email_suppressions(email,reason) VALUES(v_email,e->>'event') ON CONFLICT(email) DO NOTHING;
   UPDATE public.leads SET email_sequence_active=false WHERE lower(trim(owner_email))=v_email;
   UPDATE public.buyers SET email_opt_in=false WHERE lower(trim(email))=v_email;
  END IF;
  -- Never remove suppression on group_resubscribe or on out-of-order delivery events.
  IF v_stop OR (v_msg IS NOT NULL AND e->>'event' IN ('delivered','dropped','deferred')) THEN
   INSERT INTO public.app_notifications(recipient_role,type,title,body,action_url,metadata)
   VALUES('admin','pipeline_step','Email ' || (e->>'event'),
    v_email || ': ' || left(coalesce(e->>'reason',e->>'event'),300),'/settings',
    jsonb_build_object('provider','sendgrid','message_id',v_msg,'event_id',v_id,'suppressed',v_stop));
  END IF;
 END LOOP;
 RETURN jsonb_build_object('saved',true);
END;
$function$

CREATE OR REPLACE FUNCTION public.record_twilio_event(p_event uuid, p_kind text, p_payload jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
DECLARE
  v_phone text;
  v_lead uuid;
  v_inserted uuid;
  v_owner uuid;
  v_stop boolean;
  v_suppressed boolean;
  v_body text := coalesce(p_payload->>'Body','');
  v_control text := upper(trim(coalesce(p_payload->>'OptOutType',p_payload->>'Body','')));
BEGIN
  IF p_kind NOT IN ('inbound','status') OR coalesce(p_payload->>'MessageSid','') !~ '^SM[0-9a-fA-F]{32}$' THEN
    RAISE EXCEPTION 'Invalid Twilio event';
  END IF;
  v_phone := CASE WHEN p_kind='inbound' THEN p_payload->>'From' ELSE p_payload->>'To' END;
  IF coalesce(v_phone,'') !~ '^\+1[0-9]{10}$' THEN RAISE EXCEPTION 'Invalid phone'; END IF;
  PERFORM pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended('seller-outreach:'||v_phone,0));
  v_stop := p_kind='inbound' AND (v_control IN ('STOP','STOPALL','UNSUBSCRIBE','CANCEL','END','QUIT','REVOKE','OPTOUT','OPT OUT')
    OR coalesce(p_payload->>'crm_opt_out','false')='true'
    OR upper(trim(v_body)) IN ('STOP','STOPALL','UNSUBSCRIBE','CANCEL','END','QUIT','REVOKE','OPTOUT','OPT OUT'));
  IF p_kind='status' THEN
    IF p_payload->>'app_message_id' IS NOT NULL THEN
      SELECT lead_id INTO v_lead FROM public.sms_events WHERE id=(p_payload->>'app_message_id')::uuid
        AND provider='twilio' AND direction='outbound' AND phone_number=v_phone;
    ELSE
      SELECT lead_id INTO v_lead FROM public.sms_events WHERE provider='twilio'
        AND raw_payload->>'provider_sid'=p_payload->>'MessageSid' LIMIT 1;
    END IF;
  ELSE
    SELECT id INTO v_lead FROM public.leads l WHERE EXISTS (
      SELECT 1 FROM unnest(ARRAY[l.owner_phone_1,l.owner_phone_2,l.owner_phone_3]) n(phone)
      WHERE regexp_replace(regexp_replace(coalesce(n.phone,''),'[^0-9]','','g'),'^1([0-9]{10})$','\1')=right(v_phone,10)
    ) ORDER BY created_at DESC LIMIT 1;
  END IF;
  INSERT INTO public.sms_events(id,lead_id,provider,direction,phone_number,body,status,opt_out,raw_payload)
    VALUES(p_event,v_lead,'twilio',CASE WHEN p_kind='inbound' THEN 'inbound' ELSE 'outbound' END,
      v_phone,v_body,CASE WHEN p_kind='inbound' THEN 'replied' ELSE p_payload->>'MessageStatus' END,v_stop,p_payload)
    ON CONFLICT(id) DO NOTHING RETURNING id INTO v_inserted;
  IF v_inserted IS NULL THEN RETURN jsonb_build_object('saved',true,'duplicate',true); END IF;
  IF v_stop THEN
    -- Store even unknown numbers so a later imported lead remains suppressed.
    INSERT INTO public.dnc_registry(id,phone_number,lead_id,reason,source,opt_out_keyword,raw_payload)
      VALUES(p_event,v_phone,v_lead,'opt_out','twilio',left(v_body,100),p_payload) ON CONFLICT(id) DO NOTHING;
    UPDATE public.leads l SET dnc=true,status='dnc',sms_sequence_active=false,email_sequence_active=false,ai_calling_paused=true
      WHERE EXISTS (SELECT 1 FROM unnest(ARRAY[l.owner_phone_1,l.owner_phone_2,l.owner_phone_3]) n(phone)
        WHERE regexp_replace(regexp_replace(coalesce(n.phone,''),'[^0-9]','','g'),'^1([0-9]{10})$','\1')=right(v_phone,10));
    UPDATE public.tasks t SET status='cancelled'
      WHERE t.status='pending' AND t.type='acquisition_review'
        AND t.title IN ('Retell SMS reply: review and follow up','SMS reply: review and follow up')
        AND EXISTS (SELECT 1 FROM public.leads l WHERE l.id=t.lead_id AND EXISTS (
          SELECT 1 FROM unnest(ARRAY[l.owner_phone_1,l.owner_phone_2,l.owner_phone_3]) n(phone)
          WHERE regexp_replace(regexp_replace(coalesce(n.phone,''),'[^0-9]','','g'),'^1([0-9]{10})$','\1')=right(v_phone,10)));
  ELSIF p_kind='inbound' AND v_control NOT IN ('START','UNSTOP','YES','HELP','INFO') THEN
    UPDATE public.leads SET status='responding',sms_sequence_active=false,ai_calling_paused=true
      WHERE id=v_lead AND dnc IS FALSE AND status NOT IN ('dead','dnc','closed');
  END IF;
  v_suppressed := coalesce((public.intake_phone_status(v_phone,v_lead,''))->>'suppressed','true') <> 'false';
  SELECT p.id INTO v_owner FROM public.leads l JOIN public.profiles p ON p.id=l.assigned_to
    WHERE l.id=v_lead AND p.status='approved';
  IF v_owner IS NULL THEN
    SELECT p.id INTO v_owner FROM public.app_settings a JOIN public.profiles p ON p.id::text=a.value
      WHERE a.key='lead_owner_user_id' AND p.status='approved';
  END IF;
  IF p_kind='inbound' AND NOT v_stop AND NOT v_suppressed AND v_lead IS NOT NULL
    AND v_control NOT IN ('START','UNSTOP','YES','HELP','INFO') THEN
    INSERT INTO public.tasks(id,lead_id,title,description,priority,status,type,assigned_to,due_date)
      SELECT p_event,v_lead,'SMS reply: review and follow up',
        'Carrier SMS receipt: '||p_event::text||E'\nRecipient text (unverified): '||left(v_body,3000),
        'high','pending','acquisition_review',v_owner,now()
      WHERE EXISTS (SELECT 1 FROM public.leads WHERE id=v_lead AND dnc IS FALSE
        AND status NOT IN ('dead','dnc','closed','sold'))
      ON CONFLICT(id) DO NOTHING;
  END IF;
  -- START is recorded, but never automatically clears existing DNC or renews consent.
  IF p_kind='inbound' THEN
    INSERT INTO public.app_notifications(id,recipient_id,recipient_role,type,title,body,action_url,lead_id,metadata)
      VALUES(p_event,v_owner,'admin','pipeline_step',CASE WHEN v_stop THEN 'SMS opt-out received' ELSE 'SMS reply received' END,
        left(v_body,500),'/leads',v_lead,jsonb_build_object('provider','twilio','message_sid',p_payload->>'MessageSid','opt_out',v_stop));
  END IF;
  RETURN jsonb_build_object('saved',true,'duplicate',false,'lead_id',v_lead,
    'suppressed',v_suppressed,'opt_out',v_stop);
END;
$function$

CREATE OR REPLACE FUNCTION public.recover_propstream_external_submission(p_id uuid, p_operator uuid, p_payload jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
DECLARE old wholesale_ingest.propstream_external_submissions; item jsonb; saved wholesale_ingest.skip_trace_requests;
 fingerprint text; results jsonb:='[]'; result jsonb; job text;
BEGIN
 IF NOT EXISTS(SELECT 1 FROM public.profiles WHERE id=p_operator AND role='admin' AND status='approved') THEN RAISE EXCEPTION 'Approved administrator required'; END IF;
 IF p_id IS NULL OR jsonb_typeof(p_payload) IS DISTINCT FROM 'object'
 OR (p_payload-ARRAY['provider_job_id','evidence_sha256','notes','items'])<>'{}'::jsonb
 OR coalesce(p_payload->>'provider_job_id','') !~ '^A[0-9]{1,20}$'
 OR coalesce(p_payload->>'evidence_sha256','') !~ '^[a-f0-9]{64}$'
 OR coalesce(length(trim(p_payload->>'notes')),0) NOT BETWEEN 20 AND 2000
 OR jsonb_typeof(p_payload->'items') IS DISTINCT FROM 'array' THEN RAISE EXCEPTION 'Exact external job evidence required'; END IF;
 IF jsonb_array_length(p_payload->'items') NOT BETWEEN 1 AND 500
 OR (SELECT count(DISTINCT v->>'request_id') FROM jsonb_array_elements(p_payload->'items') v)<>jsonb_array_length(p_payload->'items')
 OR (SELECT count(DISTINCT v->>'lead_id') FROM jsonb_array_elements(p_payload->'items') v)<>jsonb_array_length(p_payload->'items') THEN RAISE EXCEPTION 'Unique request and lead per member required'; END IF;
 fingerprint:=encode(sha256(convert_to(p_payload::text,'UTF8')),'hex');job:=p_payload->>'provider_job_id';
 PERFORM pg_advisory_xact_lock(hashtextextended('propstream-external:'||p_id::text,0));
 SELECT * INTO old FROM wholesale_ingest.propstream_external_submissions WHERE id=p_id;
 IF FOUND THEN
  IF old.operator_id<>p_operator OR old.payload_hash<>fingerprint THEN RAISE EXCEPTION 'External recovery reference conflict'; END IF;
  RETURN old.result||jsonb_build_object('replayed',true,'dispatch',false);
 END IF;
 FOR item IN SELECT v FROM jsonb_array_elements(p_payload->'items') v ORDER BY v->>'lead_id' LOOP
  IF jsonb_typeof(item) IS DISTINCT FROM 'object' OR (item-ARRAY['request_id','lead_id','input_hash'])<>'{}'::jsonb
  OR coalesce(item->>'input_hash','') !~ '^[a-f0-9]{64}$' THEN RAISE EXCEPTION 'Exact reserved input required'; END IF;
  PERFORM pg_advisory_xact_lock(hashtextextended('trace-lead:'||(item->>'lead_id'),0));
  SELECT * INTO saved FROM wholesale_ingest.skip_trace_requests WHERE id=(item->>'request_id')::uuid FOR UPDATE;
  IF saved.id IS NULL OR saved.lead_id IS DISTINCT FROM (item->>'lead_id')::uuid OR saved.provider<>'propstream'
  OR saved.input_hash IS DISTINCT FROM item->>'input_hash' OR saved.state NOT IN ('reserved','submitted','unknown')
  OR (saved.provider_job_id IS NOT NULL AND saved.provider_job_id<>job)
  OR NOT EXISTS(SELECT 1 FROM wholesale_ingest.propstream_handoffs WHERE request_id=saved.id AND operator_id=p_operator)
  THEN RAISE EXCEPTION 'Matching unresolved PropStream reservation required'; END IF;
  -- Do not pretend a dispatch happened here or recheck eligibility to release an
  -- already external job. Its original hold must survive stale evidence/midnight.
  UPDATE wholesale_ingest.skip_trace_requests SET state='unknown',provider_job_id=job WHERE id=saved.id RETURNING * INTO saved;
  results:=results||jsonb_build_array(jsonb_build_object('request_id',saved.id,'lead_id',saved.lead_id,'state',saved.state,'reserved_cents',saved.reserved_cents));
 END LOOP;
 result:=jsonb_build_object('recovery_id',p_id,'provider_job_id',job,'count',jsonb_array_length(p_payload->'items'),'results',results,
 'dispatch',false,'outreach_authorized',false,'replayed',false);
 INSERT INTO wholesale_ingest.propstream_external_submissions(id,operator_id,payload_hash,payload,result) VALUES(p_id,p_operator,fingerprint,p_payload,result);
 RETURN result;
END $function$

CREATE OR REPLACE FUNCTION public.recover_retell_api_turn(p_turn uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
DECLARE t public.retell_api_turns; s public.retell_api_sessions; e public.sms_events; receipt jsonb;
BEGIN
 SELECT * INTO t FROM public.retell_api_turns WHERE id=p_turn;
 IF NOT FOUND THEN RETURN jsonb_build_object('recovered',false,'reason','missing_turn','dispatch_authorized',false); END IF;
 SELECT * INTO s FROM public.retell_api_sessions WHERE id=t.session_id;
 PERFORM pg_advisory_xact_lock(hashtextextended('seller-outreach:'||s.phone_number,0));
 -- Use the same lock order as callback synchronization: phone, job, session, turn, receipt.
 PERFORM 1 FROM public.retell_form_sms_jobs WHERE id=s.id FOR UPDATE;
 SELECT * INTO s FROM public.retell_api_sessions WHERE id=t.session_id FOR UPDATE;
 SELECT * INTO t FROM public.retell_api_turns WHERE id=p_turn FOR UPDATE;
 IF t.status='queued' AND t.expires_at<=now() THEN
  UPDATE public.retell_api_turns SET status='stopped',reason='Reply expired before generation; human follow-up retained' WHERE id=t.id;
  RETURN jsonb_build_object('recovered',true,'status','stopped','dispatch_authorized',false);
 ELSIF (t.status IN ('creating_session','generating') AND coalesce(t.claimed_at,t.created_at)<=now()-interval '5 minutes')
   OR (t.status='generated' AND t.expires_at<=now()) THEN
  PERFORM public.hold_retell_api_turn(t.id,t.status,'Interrupted or expired generation; verify provider history; never regenerate automatically');
  RETURN jsonb_build_object('recovered',true,'status','review','dispatch_authorized',false);
 ELSIF t.status='submitting' THEN
  SELECT * INTO e FROM public.sms_events WHERE id=t.outbound_id FOR UPDATE;
  IF coalesce(e.created_at,t.claimed_at,t.created_at)>now()-interval '5 minutes' THEN
   RETURN jsonb_build_object('recovered',false,'reason','dispatch_still_fresh','dispatch_authorized',false); END IF;
  receipt:=public.sync_retell_app_outcome(t.outbound_id);
  SELECT * INTO t FROM public.retell_api_turns WHERE id=p_turn;
  IF receipt->>'synced'='true' AND t.status<>'submitting' THEN
   RETURN jsonb_build_object('recovered',true,'status',t.status,'dispatch_authorized',false); END IF;
  IF receipt->>'synced'='true' THEN
   PERFORM public.review_retell_app_dispatch(t.outbound_id,'Stale reply dispatch outcome unconfirmed; reconcile carrier evidence; never resend automatically');
  ELSE
   PERFORM public.hold_retell_api_turn(t.id,'submitting','Stale reply ledger missing; never resend automatically');
  END IF;
  RETURN jsonb_build_object('recovered',true,'status','review','dispatch_authorized',false);
 END IF;
 RETURN jsonb_build_object('recovered',false,'reason','not_stale_actionable','dispatch_authorized',false);
END $function$

CREATE OR REPLACE FUNCTION public.recover_retell_app_ack(p_job uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
DECLARE j public.retell_form_sms_jobs; receipt jsonb;
BEGIN
 SELECT * INTO j FROM public.retell_form_sms_jobs WHERE id=p_job;
 IF NOT FOUND OR j.delivery_transport<>'app_twilio' THEN
  RETURN jsonb_build_object('recovered',false,'reason','unrelated_job','dispatch_authorized',false); END IF;
 PERFORM pg_advisory_xact_lock(hashtextextended('seller-outreach:'||j.phone_number,0));
 SELECT * INTO j FROM public.retell_form_sms_jobs WHERE id=p_job FOR UPDATE;
 IF j.status<>'processing' OR coalesce(j.claimed_at,j.created_at)>now()-interval '5 minutes' THEN
  RETURN jsonb_build_object('recovered',false,'reason','not_stale_processing','dispatch_authorized',false); END IF;
 receipt:=public.sync_retell_app_outcome(j.id);
 SELECT * INTO j FROM public.retell_form_sms_jobs WHERE id=p_job;
 IF receipt->>'synced'='true' AND j.status<>'processing' THEN
  RETURN jsonb_build_object('recovered',true,'status',j.status,'dispatch_authorized',false); END IF;
 IF receipt->>'synced'='true' THEN
  PERFORM public.review_retell_app_dispatch(j.id,'Stale acknowledgment outcome unconfirmed; reconcile carrier evidence; never resend automatically');
 ELSE
  UPDATE public.retell_form_sms_jobs SET status='review',reason='Stale acknowledgment ledger missing; never resend automatically' WHERE id=j.id;
 END IF;
 RETURN jsonb_build_object('recovered',true,'status','review','dispatch_authorized',false);
END $function$

CREATE OR REPLACE FUNCTION public.reserve_form_submission(p_request_id uuid, p_submission jsonb, p_manifest jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'public', 'pg_temp'
AS $function$
DECLARE receipt public.lead_form_submissions%ROWTYPE; inserted integer;
BEGIN
 IF p_request_id IS NULL OR jsonb_typeof(p_manifest) IS DISTINCT FROM 'object'
    OR jsonb_typeof(p_submission->'raw_answers') IS DISTINCT FROM 'object' THEN
   RAISE EXCEPTION 'Validated inquiry reference and manifest are required';
 END IF;
 INSERT INTO public.lead_form_submissions(
   id,form_id,ip_address,user_agent,utm_source,utm_medium,utm_campaign,raw_answers,
   computed_motivation_tag,computed_timeline,computed_condition,processing_status,request_manifest
 ) VALUES(
   p_request_id,(p_submission->>'form_id')::uuid,p_submission->>'ip_address',
   p_submission->>'user_agent',p_submission->>'utm_source',p_submission->>'utm_medium',
   p_submission->>'utm_campaign',p_submission->'raw_answers',
   p_submission->>'computed_motivation_tag',p_submission->>'computed_timeline',
   p_submission->>'computed_condition','pending',p_manifest
 ) ON CONFLICT(id) DO NOTHING;
 GET DIAGNOSTICS inserted=ROW_COUNT;
 SELECT * INTO STRICT receipt FROM public.lead_form_submissions WHERE id=p_request_id;
 IF receipt.form_id IS DISTINCT FROM (p_submission->>'form_id')::uuid
    OR receipt.request_manifest IS DISTINCT FROM p_manifest THEN
   RETURN jsonb_build_object('status','conflict');
 END IF;
 RETURN jsonb_build_object('status',CASE WHEN inserted=1 THEN 'created' ELSE 'replayed' END,
    'submission_id',receipt.id,'processing_status',receipt.processing_status);
END;
$function$

CREATE OR REPLACE FUNCTION public.reserve_list_digest(p_day date, p_recipient text, p_message uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
DECLARE d wholesale_ingest.daily_digests; mail text:=lower(trim(p_recipient));
BEGIN
 IF p_day IS DISTINCT FROM (now() AT TIME ZONE 'America/Chicago')::date THEN RAISE EXCEPTION 'Only current-day digests may be sent'; END IF;
 IF p_message IS NULL OR mail IS NULL OR length(mail)>320 OR mail!~'^[^[:space:]@]+@[^[:space:]@]+[.][^[:space:]@]+$' THEN RAISE EXCEPTION 'Valid message and recipient required'; END IF;
 SELECT * INTO d FROM wholesale_ingest.daily_digests WHERE day=p_day FOR UPDATE;
 IF d.day IS NULL OR d.summary IS NULL THEN RAISE EXCEPTION 'Generate digest before reserving delivery'; END IF;
 IF d.message_id IS NOT NULL AND (d.message_id<>p_message OR d.recipient<>mail) THEN RAISE EXCEPTION 'Existing digest reservation is immutable'; END IF;
 IF d.message_id IS NULL THEN
  UPDATE wholesale_ingest.daily_digests SET message_id=p_message,recipient=mail,delivery_summary=summary,
   reserved_at=now(),status='reserved' WHERE day=p_day RETURNING * INTO d;
 END IF;
 RETURN jsonb_build_object('day',d.day,'message_id',d.message_id,'recipient',d.recipient,
 'summary',d.delivery_summary,'send_allowed',d.status IN ('reserved','generated') AND NOT EXISTS(SELECT 1 FROM public.email_messages WHERE id=d.message_id));
END; $function$

CREATE OR REPLACE FUNCTION public.reserve_list_trace(p_id uuid, p_lead uuid, p_provider text, p_input_hash text, p_max_cents integer)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
DECLARE saved wholesale_ingest.skip_trace_requests; budget wholesale_ingest.daily_budgets;
 day date:=(clock_timestamp() AT TIME ZONE 'America/Chicago')::date; lead_json jsonb; total_budget jsonb;
BEGIN
 IF p_id IS NULL OR p_lead IS NULL OR coalesce(p_provider,'') !~ '^[a-z0-9_-]{1,64}$'
 OR coalesce(p_input_hash,'') !~ '^[a-f0-9]{64}$' OR p_max_cents IS NULL OR p_max_cents<=0
 THEN RETURN jsonb_build_object('blocked','invalid_request'); END IF;
 PERFORM pg_advisory_xact_lock(hashtextextended('trace-request:'||p_id::text,0));
 PERFORM pg_advisory_xact_lock(hashtextextended('trace-lead:'||p_lead::text,0));
 SELECT * INTO saved FROM wholesale_ingest.skip_trace_requests WHERE id=p_id;
 IF FOUND THEN
  IF saved.lead_id<>p_lead OR saved.provider<>p_provider OR saved.input_hash IS DISTINCT FROM p_input_hash
   OR saved.reserved_cents<>p_max_cents THEN RETURN jsonb_build_object('blocked','reference_conflict'); END IF;
  RETURN jsonb_build_object('request',to_jsonb(saved),'replayed',true,'dispatch',false);
 END IF;
 SELECT to_jsonb(l) INTO lead_json FROM public.leads l WHERE id=p_lead FOR UPDATE;
 IF NOT FOUND THEN RETURN jsonb_build_object('blocked','lead_missing'); END IF;
 IF NOT EXISTS(SELECT 1 FROM wholesale_ingest.properties WHERE lead_id=p_lead AND state='TX' AND county IN ('Dallas','Collin'))
 THEN RETURN jsonb_build_object('blocked','unverified_pipeline_property'); END IF;
 IF coalesce(nullif(trim(lead_json->>'owner_phone_1'),''),nullif(trim(lead_json->>'owner_phone_2'),''),nullif(trim(lead_json->>'owner_email'),'')) IS NOT NULL
 OR EXISTS(SELECT 1 FROM wholesale_ingest.contacts WHERE lead_id=p_lead AND expires_at>clock_timestamp())
 OR EXISTS(SELECT 1 FROM wholesale_ingest.skip_trace_requests WHERE lead_id=p_lead AND state='completed')
 THEN RETURN jsonb_build_object('blocked','already_enriched'); END IF;
 IF EXISTS(SELECT 1 FROM wholesale_ingest.skip_trace_requests WHERE lead_id=p_lead AND state IN ('reserved','submitted','unknown'))
 THEN RETURN jsonb_build_object('blocked','unresolved_request'); END IF;
 -- Serialize every new reservation across all days and providers. Midnight never resets authorization.
 PERFORM pg_advisory_xact_lock(hashtextextended('trace-total-cap-v1',0));
 total_budget:=public.list_trace_total_budget();
 IF p_max_cents::bigint>(total_budget->>'remaining_cents')::bigint
 THEN RETURN jsonb_build_object('blocked','total_cap','total_budget',total_budget); END IF;
 SELECT * INTO budget FROM wholesale_ingest.daily_budgets WHERE spend_day=day FOR UPDATE;
 IF NOT FOUND THEN RETURN jsonb_build_object('blocked','budget_not_configured'); END IF;
 IF p_max_cents::bigint+budget.reserved_cents+budget.actual_cents>budget.cap_cents
 THEN RETURN jsonb_build_object('blocked','daily_cap'); END IF;
 INSERT INTO wholesale_ingest.skip_trace_requests(id,lead_id,provider,request_key,spend_day,reserved_cents,state,input_hash)
 VALUES(p_id,p_lead,p_provider,p_id::text,day,p_max_cents,'reserved',p_input_hash) RETURNING * INTO saved;
 UPDATE wholesale_ingest.daily_budgets SET reserved_cents=reserved_cents+p_max_cents WHERE spend_day=day;
 RETURN jsonb_build_object('request',to_jsonb(saved),'replayed',false,'dispatch',false);
END $function$

CREATE OR REPLACE FUNCTION public.resolve_list_record(p_run uuid, p_batch integer, p_ordinal integer, p_operator uuid, p_county text, p_evidence_url text, p_lead uuid DEFAULT NULL::uuid, p_active boolean DEFAULT true)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
DECLARE r wholesale_ingest.records; s wholesale_ingest.sources; v jsonb; prop uuid; lid uuid; sig uuid;
 aliases text[]; prefix text; matches uuid[]; host text; a text; new_lead boolean:=false;
BEGIN
 IF NOT EXISTS(SELECT 1 FROM public.profiles WHERE id=p_operator AND role='admin' AND status='approved') THEN RAISE EXCEPTION 'Approved administrator required'; END IF;
 -- All identity mutations share a lock; aliases cannot be claimed by concurrent reviews.
 PERFORM pg_advisory_xact_lock(hashtextextended('wholesaleos:list-identity',0));
 SELECT * INTO r FROM wholesale_ingest.records WHERE run_id=p_run AND batch_index=p_batch AND ordinal=p_ordinal FOR UPDATE;
 IF r.run_id IS NULL THEN RAISE EXCEPTION 'Record missing'; END IF;
 IF r.resolved_at IS NOT NULL THEN RETURN jsonb_build_object('replayed',true,'property_id',r.property_id); END IF;
 -- Match the ingress lock so a review cannot race receipt writes for this run.
 PERFORM pg_advisory_xact_lock(hashtextextended(p_run::text,0));
 IF NOT EXISTS (
  SELECT 1 FROM wholesale_ingest.ingest_runs i WHERE i.id=p_run
  AND (SELECT count(*) FROM wholesale_ingest.raw_payloads b WHERE b.run_id=i.id)=i.expected_batches
  AND NOT EXISTS (SELECT 1 FROM wholesale_ingest.raw_payloads b WHERE b.run_id=i.id
   AND (b.batch_index>=i.expected_batches OR b.expires_at<=now()))
 ) THEN RAISE EXCEPTION 'Complete unexpired batch set required before property review'; END IF;

 SELECT src.* INTO s FROM wholesale_ingest.sources src JOIN wholesale_ingest.ingest_runs i ON i.source_id=src.id WHERE i.id=p_run;
 v:=r.record;
 IF p_county IS DISTINCT FROM s.county OR p_county NOT IN ('Dallas','Collin') THEN RAISE EXCEPTION 'County mismatch'; END IF;
 host:=substring(lower(p_evidence_url) from '^https://([^/:?#]+)(?:[/:?#]|$)');
 IF host IS NULL OR NOT (host=ANY(CASE WHEN p_county='Dallas' THEN ARRAY['www.dallascad.org','dallascad.org','www.dallascounty.org'] ELSE ARRAY['www.collincad.org','collincad.org','www.collincountytx.gov','gis.collincountytx.gov'] END)) THEN RAISE EXCEPTION 'Official county/title evidence required'; END IF;
 IF r.source_record_id IS NULL OR nullif(trim(v->>'property_address'),'') IS NULL OR nullif(trim(v->>'city'),'') IS NULL OR v->>'state' IS DISTINCT FROM 'TX' THEN RAISE EXCEPTION 'Stable source ID and verified property address required'; END IF;
 IF s.list_type='pre_foreclosure' AND v->>'filed_date' IS NULL THEN RAISE EXCEPTION 'Notice filing date required'; END IF;
 prefix:='tx|'||lower(s.county)||'|';
 aliases:=ARRAY[prefix||'address|'||lower(regexp_replace(trim(v->>'property_address'),'\s+',' ','g'))||'|'||lower(coalesce(v->>'unit',''))||'|'||lower(v->>'city')||'|'||coalesce(v->>'zip','')];
 IF nullif(trim(v->>'parcel_id'),'') IS NOT NULL THEN aliases:=array_append(aliases,prefix||'parcel|'||lower(trim(v->>'parcel_id'))); END IF;
 SELECT array_agg(DISTINCT property_id) INTO matches FROM wholesale_ingest.property_aliases WHERE alias_key=ANY(aliases);
 IF cardinality(matches)>1 THEN RAISE EXCEPTION 'Conflicting identities require reconciliation'; END IF;
 prop:=matches[1];
 IF prop IS NOT NULL THEN
  SELECT lead_id INTO lid FROM wholesale_ingest.properties WHERE id=prop;
  IF p_lead IS NOT NULL AND p_lead IS DISTINCT FROM lid THEN RAISE EXCEPTION 'Existing property has another lead'; END IF;
 ELSE
  lid:=p_lead;
  IF lid IS NOT NULL AND NOT EXISTS(SELECT 1 FROM public.leads WHERE id=lid) THEN RAISE EXCEPTION 'Lead missing'; END IF;
  IF lid IS NULL THEN
   -- Existing legacy leads have no verified county key: ask operator to choose rather than duplicate.
   IF EXISTS(SELECT 1 FROM public.leads WHERE lower(trim(property_address))=lower(trim(v->>'property_address')) AND lower(trim(city))=lower(trim(v->>'city'))) THEN RAISE EXCEPTION 'Existing CRM address requires explicit lead selection'; END IF;
   INSERT INTO public.leads(property_address,city,state,zip_code,source,motivation_tag,status,owner_mailing_address,sms_sequence_active,email_sequence_active)
    VALUES(v->>'property_address',v->>'city','TX',v->>'zip',s.source_key,s.list_type,'new',v->>'mailing_address',false,false) RETURNING id INTO lid;
   new_lead:=true;
  END IF;
  INSERT INTO wholesale_ingest.properties(state,county,parcel_id,address_std,unit,city,zip,lead_id)
   VALUES('TX',s.county,v->>'parcel_id',v->>'property_address',v->>'unit',v->>'city',v->>'zip',lid) RETURNING id INTO prop;
 END IF;
 FOREACH a IN ARRAY aliases LOOP
  INSERT INTO wholesale_ingest.property_aliases(alias_key,property_id,evidence_url) VALUES(a,prop,p_evidence_url) ON CONFLICT(alias_key) DO NOTHING;
 END LOOP;
 INSERT INTO wholesale_ingest.distress_signals(property_id,source_id,source_record_id,list_type,case_number,filed_date,auction_date,amount,amount_type,source_url,first_run_id,last_run_id,active)
 VALUES(prop,s.id,r.source_record_id,s.list_type,v->>'case_number',(v->>'filed_date')::date,(v->>'auction_date')::date,(v->>'amount_owed')::numeric,v->>'amount_type',v->>'source_url',p_run,p_run,p_active)
 ON CONFLICT(property_id,source_id,source_record_id) DO UPDATE SET last_run_id=p_run,last_seen_at=now(),active=p_active,amount=excluded.amount
 RETURNING id INTO sig;
 INSERT INTO wholesale_ingest.signal_observations(signal_id,run_id,source_url,pulled_at)
 SELECT sig,p_run,v->>'source_url',pulled_at FROM wholesale_ingest.ingest_runs WHERE id=p_run ON CONFLICT DO NOTHING;
 UPDATE wholesale_ingest.records SET property_id=prop,resolved_at=now(),reviewed_by=p_operator,reviewed_at=now(),evidence_url=p_evidence_url,review_reason=NULL
 WHERE run_id=p_run AND batch_index=p_batch AND ordinal=p_ordinal;
 INSERT INTO wholesale_ingest.review_events(run_id,batch_index,ordinal,operator_id,action,evidence_url,property_id)
 VALUES(p_run,p_batch,p_ordinal,p_operator,'verified_property',p_evidence_url,prop);
 UPDATE wholesale_ingest.ingest_runs SET records_new=records_new+new_lead::int,records_stacked=records_stacked+(NOT new_lead)::int WHERE id=p_run;
 RETURN jsonb_build_object('replayed',false,'property_id',prop,'lead_id',lid,'new_lead',new_lead,
 'stack_count',(SELECT count(DISTINCT list_type) FROM wholesale_ingest.distress_signals WHERE property_id=prop AND active));
END; $function$

CREATE OR REPLACE FUNCTION public.resolve_reviewed_list_record(p_run uuid, p_batch integer, p_ordinal integer, p_operator uuid, p_county text, p_evidence_url text, p_lead uuid, p_active boolean, p_review jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
DECLARE r wholesale_ingest.records; s wholesale_ingest.sources; v jsonb; prop uuid; lid uuid; sig uuid;
 aliases text[]; prefix text; matches uuid[]; host text; a text; new_lead boolean:=false; identity jsonb; prior wholesale_ingest.review_events;
BEGIN
 IF NOT EXISTS(SELECT 1 FROM public.profiles WHERE id=p_operator AND role='admin' AND status='approved') THEN RAISE EXCEPTION 'Approved administrator required'; END IF;
 -- All identity mutations share a lock; aliases cannot be claimed by concurrent reviews.
 PERFORM pg_advisory_xact_lock(hashtextextended('wholesaleos:list-identity',0));
 SELECT * INTO r FROM wholesale_ingest.records WHERE run_id=p_run AND batch_index=p_batch AND ordinal=p_ordinal FOR UPDATE;
 IF r.run_id IS NULL THEN RAISE EXCEPTION 'Record missing'; END IF;
 IF jsonb_typeof(p_review) IS DISTINCT FROM 'object' OR
    coalesce(p_review->>'source_fingerprint','') IS DISTINCT FROM md5(r.record::text) OR
    coalesce(length(trim(p_review->>'notes')),0) NOT BETWEEN 10 AND 2000 OR
    jsonb_typeof(p_review->'identity') IS DISTINCT FROM 'object' OR
    EXISTS(SELECT 1 FROM jsonb_object_keys(p_review) k WHERE k NOT IN ('source_fingerprint','notes','identity'))
 THEN RAISE EXCEPTION 'Current source fingerprint, identity and review notes required'; END IF;
 identity:=p_review->'identity';
 IF EXISTS(SELECT 1 FROM jsonb_object_keys(identity) k WHERE k NOT IN ('property_address','city','state','zip','parcel_id','unit')) OR
    EXISTS(SELECT 1 FROM jsonb_each(identity) e WHERE jsonb_typeof(e.value) NOT IN ('string','null')) OR
    coalesce(length(trim(identity->>'property_address')),0) NOT BETWEEN 1 AND 300 OR trim(identity->>'property_address') ~ '^0+$' OR
    coalesce(length(trim(identity->>'city')),0) NOT BETWEEN 1 AND 100 OR identity->>'state' IS DISTINCT FROM 'TX' OR
    coalesce(identity->>'zip','') !~ '^[0-9]{5}(-[0-9]{4})?$' OR
    coalesce(length(identity->>'parcel_id'),0)>100 OR coalesce(length(identity->>'unit'),0)>100
 THEN RAISE EXCEPTION 'Verified Texas situs address, city and ZIP required'; END IF;
 IF p_active IS NULL THEN RAISE EXCEPTION 'Explicit signal status required'; END IF;
 IF r.resolved_at IS NOT NULL THEN
  SELECT * INTO prior FROM wholesale_ingest.review_events WHERE run_id=p_run AND batch_index=p_batch AND ordinal=p_ordinal AND action='verified_property' ORDER BY created_at DESC LIMIT 1;
  IF prior.review_details IS DISTINCT FROM jsonb_build_object('review',p_review,'active_signal',p_active,'lead_id',p_lead,'county',p_county) OR prior.evidence_url IS DISTINCT FROM p_evidence_url OR prior.operator_id IS DISTINCT FROM p_operator
  THEN RAISE EXCEPTION 'Already resolved with different review evidence'; END IF;
  SELECT lead_id INTO lid FROM wholesale_ingest.properties WHERE id=r.property_id;
  RETURN jsonb_build_object('replayed',true,'property_id',r.property_id,'lead_id',lid,'outreach_authorized',false,'run_id',p_run,'batch_index',p_batch,'ordinal',p_ordinal,'review',p_review);
 END IF;
 -- Match the ingress lock so a review cannot race receipt writes for this run.
 PERFORM pg_advisory_xact_lock(hashtextextended(p_run::text,0));
 IF NOT EXISTS (
  SELECT 1 FROM wholesale_ingest.ingest_runs i WHERE i.id=p_run
  AND (SELECT count(*) FROM wholesale_ingest.raw_payloads b WHERE b.run_id=i.id)=i.expected_batches
  AND NOT EXISTS (SELECT 1 FROM wholesale_ingest.raw_payloads b WHERE b.run_id=i.id
   AND (b.batch_index>=i.expected_batches OR b.expires_at<=now()))
 ) THEN RAISE EXCEPTION 'Complete unexpired batch set required before property review'; END IF;

 SELECT src.* INTO s FROM wholesale_ingest.sources src JOIN wholesale_ingest.ingest_runs i ON i.source_id=src.id WHERE i.id=p_run;
 v:=r.record||identity; -- Original county record and raw payload hashes remain unchanged.
 IF p_county IS DISTINCT FROM s.county OR p_county NOT IN ('Dallas','Collin') THEN RAISE EXCEPTION 'County mismatch'; END IF;
 host:=substring(lower(p_evidence_url) from '^https://([^/:?#]+)(?:[/:?#]|$)');
 IF host IS NULL OR NOT (host=ANY(CASE WHEN p_county='Dallas' THEN ARRAY['www.dallascad.org','dallascad.org','www.dallascounty.org'] ELSE ARRAY['www.collincad.org','collincad.org','esearch.collincad.org','www.collincountytx.gov','gis.collincountytx.gov'] END) OR (p_county='Collin' AND coalesce(identity->>'parcel_id','') ~ '^[0-9]+$' AND p_evidence_url = ('https://data.texas.gov/resource/ahis-pci3.json?propid=' || (identity->>'parcel_id')))) THEN RAISE EXCEPTION 'Official county/title evidence required'; END IF;
 IF p_lead IS NOT NULL AND NOT EXISTS(SELECT 1 FROM public.leads WHERE id=p_lead AND lower(trim(property_address))=lower(trim(v->>'property_address')) AND lower(trim(city))=lower(trim(v->>'city')) AND state='TX' AND zip_code=v->>'zip') THEN RAISE EXCEPTION 'Selected CRM lead does not match verified property'; END IF;
 IF r.source_record_id IS NULL OR nullif(trim(v->>'property_address'),'') IS NULL OR nullif(trim(v->>'city'),'') IS NULL OR v->>'state' IS DISTINCT FROM 'TX' THEN RAISE EXCEPTION 'Stable source ID and verified property address required'; END IF;
 IF s.list_type='pre_foreclosure' AND v->>'filed_date' IS NULL THEN RAISE EXCEPTION 'Notice filing date required'; END IF;
 prefix:='tx|'||lower(s.county)||'|';
 aliases:=ARRAY[prefix||'address|'||lower(regexp_replace(trim(v->>'property_address'),'\s+',' ','g'))||'|'||lower(coalesce(v->>'unit',''))||'|'||lower(v->>'city')||'|'||coalesce(v->>'zip','')];
 IF nullif(trim(v->>'parcel_id'),'') IS NOT NULL THEN aliases:=array_append(aliases,prefix||'parcel|'||lower(trim(v->>'parcel_id'))); END IF;
 SELECT array_agg(DISTINCT property_id) INTO matches FROM wholesale_ingest.property_aliases WHERE alias_key=ANY(aliases);
 IF cardinality(matches)>1 THEN RAISE EXCEPTION 'Conflicting identities require reconciliation'; END IF;
 prop:=matches[1];
 IF prop IS NOT NULL THEN
  SELECT lead_id INTO lid FROM wholesale_ingest.properties WHERE id=prop;
  IF p_lead IS NOT NULL AND p_lead IS DISTINCT FROM lid THEN RAISE EXCEPTION 'Existing property has another lead'; END IF;
 ELSE
  lid:=p_lead;
  IF lid IS NOT NULL AND NOT EXISTS(SELECT 1 FROM public.leads WHERE id=lid) THEN RAISE EXCEPTION 'Lead missing'; END IF;
  IF lid IS NULL THEN
   -- Existing legacy leads have no verified county key: ask operator to choose rather than duplicate.
   IF EXISTS(SELECT 1 FROM public.leads WHERE lower(trim(property_address))=lower(trim(v->>'property_address')) AND lower(trim(city))=lower(trim(v->>'city'))) THEN RAISE EXCEPTION 'Existing CRM address requires explicit lead selection'; END IF;
   INSERT INTO public.leads(property_address,city,state,zip_code,source,motivation_tag,status,owner_mailing_address,sms_sequence_active,email_sequence_active)
    VALUES(v->>'property_address',v->>'city','TX',v->>'zip',s.source_key,s.list_type,'new',v->>'mailing_address',false,false) RETURNING id INTO lid;
   new_lead:=true;
  END IF;
  INSERT INTO wholesale_ingest.properties(state,county,parcel_id,address_std,unit,city,zip,lead_id)
   VALUES('TX',s.county,v->>'parcel_id',v->>'property_address',v->>'unit',v->>'city',v->>'zip',lid) RETURNING id INTO prop;
 END IF;
 FOREACH a IN ARRAY aliases LOOP
  INSERT INTO wholesale_ingest.property_aliases(alias_key,property_id,evidence_url) VALUES(a,prop,p_evidence_url) ON CONFLICT(alias_key) DO NOTHING;
 END LOOP;
 INSERT INTO wholesale_ingest.distress_signals(property_id,source_id,source_record_id,list_type,case_number,filed_date,auction_date,amount,amount_type,source_url,first_run_id,last_run_id,active)
 VALUES(prop,s.id,r.source_record_id,s.list_type,v->>'case_number',(v->>'filed_date')::date,(v->>'auction_date')::date,(v->>'amount_owed')::numeric,v->>'amount_type',v->>'source_url',p_run,p_run,p_active)
 ON CONFLICT(property_id,source_id,source_record_id) DO UPDATE SET last_run_id=p_run,last_seen_at=now(),active=p_active,amount=excluded.amount
 RETURNING id INTO sig;
 INSERT INTO wholesale_ingest.signal_observations(signal_id,run_id,source_url,pulled_at)
 SELECT sig,p_run,v->>'source_url',pulled_at FROM wholesale_ingest.ingest_runs WHERE id=p_run ON CONFLICT DO NOTHING;
 UPDATE wholesale_ingest.records SET property_id=prop,resolved_at=now(),reviewed_by=p_operator,reviewed_at=now(),evidence_url=p_evidence_url,review_reason=NULL
 WHERE run_id=p_run AND batch_index=p_batch AND ordinal=p_ordinal;
 INSERT INTO wholesale_ingest.review_events(run_id,batch_index,ordinal,operator_id,action,evidence_url,property_id,review_details)
 VALUES(p_run,p_batch,p_ordinal,p_operator,'verified_property',p_evidence_url,prop,jsonb_build_object('review',p_review,'active_signal',p_active,'lead_id',p_lead,'county',p_county));
 UPDATE wholesale_ingest.ingest_runs SET records_new=records_new+new_lead::int,records_stacked=records_stacked+(NOT new_lead)::int WHERE id=p_run;
 RETURN jsonb_build_object('replayed',false,'property_id',prop,'lead_id',lid,'new_lead',new_lead,'outreach_authorized',false,'run_id',p_run,'batch_index',p_batch,'ordinal',p_ordinal,'review',p_review,
 'stack_count',(SELECT count(DISTINCT list_type) FROM wholesale_ingest.distress_signals WHERE property_id=prop AND active));
END; $function$

CREATE OR REPLACE FUNCTION public.review_retell_app_dispatch(p_message uuid, p_reason text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
DECLARE result jsonb; e public.sms_events; job_id uuid;
BEGIN
 IF length(trim(coalesce(p_reason,''))) NOT BETWEEN 1 AND 500 THEN RAISE EXCEPTION 'Review reason required'; END IF;
 result:=public.sync_retell_app_outcome(p_message);
 IF result->>'synced' IS DISTINCT FROM 'true' THEN RAISE EXCEPTION 'App receipt required'; END IF;
 SELECT * INTO e FROM public.sms_events WHERE id=p_message;
 job_id:=(e.raw_payload->>'form_job_id')::uuid;
 IF p_message=job_id THEN
  UPDATE public.retell_form_sms_jobs SET status='review',reason=p_reason WHERE id=job_id AND status IN ('processing','accepted','review');
 ELSE
  UPDATE public.retell_api_turns SET status='review',reason=p_reason WHERE outbound_id=p_message AND status IN ('submitting','accepted','review');
 END IF;
 UPDATE public.retell_api_sessions SET status='review',reason=p_reason WHERE id=job_id AND status IN ('pending','creating','ready','review');
 RETURN jsonb_build_object('held',true,'dispatch_authorized',false);
END $function$

CREATE OR REPLACE FUNCTION public.save_foreclosure_appraisal_batch(p_operator uuid, p_batch uuid, p_receipt jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
DECLARE old wholesale_ingest.foreclosure_appraisal_batches; src uuid; run uuid; idx integer;
 stamp timestamptz; asof date; item jsonb; summary jsonb;
BEGIN
 IF NOT EXISTS(SELECT 1 FROM public.profiles WHERE id=p_operator AND role='admin' AND status='approved') THEN RAISE EXCEPTION 'Approved administrator required'; END IF;
 IF p_batch IS NULL OR jsonb_typeof(p_receipt) IS DISTINCT FROM 'object' OR (SELECT count(*) FROM jsonb_object_keys(p_receipt))<>12
  OR NOT(p_receipt ?& ARRAY['processor','run_id','batch_index','records_sha256','archive_sha256','report_sha256','source_as_of','processed_at','items','verification_granted','dispatch_authorized','outreach_authorized'])
  OR p_receipt->>'processor' IS DISTINCT FROM 'dallas-appraisal-batch/1.0'
  OR p_receipt->'verification_granted' IS DISTINCT FROM 'false'::jsonb OR p_receipt->'dispatch_authorized' IS DISTINCT FROM 'false'::jsonb
  OR p_receipt->'outreach_authorized' IS DISTINCT FROM 'false'::jsonb
  OR coalesce(p_receipt->>'records_sha256','') !~ '^[a-f0-9]{64}$' OR coalesce(p_receipt->>'archive_sha256','') !~ '^[a-f0-9]{64}$'
  OR coalesce(p_receipt->>'report_sha256','') !~ '^[a-f0-9]{64}$' OR jsonb_typeof(p_receipt->'batch_index') IS DISTINCT FROM 'number'
  OR coalesce(p_receipt->>'batch_index','') !~ '^[0-9]+$' THEN RAISE EXCEPTION 'Invalid appraisal receipt'; END IF;
 run:=(p_receipt->>'run_id')::uuid; idx:=(p_receipt->>'batch_index')::integer; stamp:=(p_receipt->>'processed_at')::timestamptz; asof:=(p_receipt->>'source_as_of')::date;
 IF stamp IS NULL OR NOT isfinite(stamp) OR stamp<'2000-01-01' OR stamp>now()+interval '5 minutes' OR asof IS NULL OR NOT isfinite(asof)
  OR asof>(stamp AT TIME ZONE 'UTC')::date OR asof<(stamp AT TIME ZONE 'UTC')::date-1
  OR jsonb_typeof(p_receipt->'items') IS DISTINCT FROM 'array' OR jsonb_array_length(p_receipt->'items') NOT BETWEEN 1 AND 500 THEN RAISE EXCEPTION 'Invalid appraisal timestamp or size'; END IF;
 SELECT r.source_id INTO src FROM wholesale_ingest.ingest_runs r JOIN wholesale_ingest.sources s ON s.id=r.source_id
 JOIN wholesale_ingest.raw_payloads p ON p.run_id=r.id AND p.batch_index=idx
 WHERE r.id=run AND s.source_key='tx-dallas-pre_foreclosure' AND p.records_hash=p_receipt->>'records_sha256' AND p.records_in=jsonb_array_length(p_receipt->'items');
 IF src IS NULL OR (SELECT count(*) FROM wholesale_ingest.records WHERE run_id=run AND batch_index=idx)<>jsonb_array_length(p_receipt->'items') THEN RAISE EXCEPTION 'Appraisal batch must match saved Dallas inventory'; END IF;
 IF (SELECT count(DISTINCT value->>'document_id') FROM jsonb_array_elements(p_receipt->'items'))<>jsonb_array_length(p_receipt->'items') THEN RAISE EXCEPTION 'Duplicate appraisal documents'; END IF;
 FOR item IN SELECT value FROM jsonb_array_elements(p_receipt->'items') LOOP
  IF jsonb_typeof(item) IS DISTINCT FROM 'object' OR (SELECT count(*) FROM jsonb_object_keys(item))<>3 OR NOT(item ?& ARRAY['document_id','match_count','held'])
   OR coalesce(item->>'document_id','') !~ '^[0-9]{1,30}$' OR jsonb_typeof(item->'match_count') IS DISTINCT FROM 'number'
   OR coalesce(item->>'match_count','') !~ '^[0-9]+$' OR (item->>'match_count')::integer NOT BETWEEN 0 AND 100
   OR jsonb_typeof(item->'held') IS DISTINCT FROM 'boolean'
   OR ((item->>'match_count')::integer<>1 AND item->'held' IS DISTINCT FROM 'true'::jsonb)
   OR NOT EXISTS(SELECT 1 FROM wholesale_ingest.records WHERE run_id=run AND batch_index=idx AND source_record_id=item->>'document_id') THEN RAISE EXCEPTION 'Invalid appraisal document'; END IF;
 END LOOP;
 PERFORM pg_advisory_xact_lock(hashtextextended('appraisal-batch:'||p_batch::text,0));
 SELECT * INTO old FROM wholesale_ingest.foreclosure_appraisal_batches WHERE id=p_batch;
 IF FOUND THEN
  IF old.operator_id<>p_operator OR old.receipt<>p_receipt THEN RAISE EXCEPTION 'Appraisal receipt conflict'; END IF;
  RETURN old.summary||jsonb_build_object('batch_id',p_batch,'verification_granted',false);
 END IF;
 SELECT jsonb_build_object('county','Dallas','documents',count(*),'unique_situs_matches',count(*) FILTER(WHERE (value->>'match_count')::int=1),
  'exception_documents',count(*) FILTER(WHERE (value->>'held')::boolean),'trace_eligible',0) INTO summary FROM jsonb_array_elements(p_receipt->'items');
 INSERT INTO wholesale_ingest.foreclosure_appraisal_batches VALUES(p_batch,src,run,idx,p_receipt,summary,stamp,p_operator,now());
 RETURN summary||jsonb_build_object('batch_id',p_batch,'verification_granted',false);
END; $function$

CREATE OR REPLACE FUNCTION public.save_foreclosure_batch(p_operator uuid, p_batch uuid, p_source text, p_receipt jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
DECLARE src wholesale_ingest.sources; old wholesale_ingest.foreclosure_batches; n jsonb; c wholesale_ingest.foreclosure_captures;
 stamp timestamptz; day date; summary jsonb;
BEGIN
 IF NOT EXISTS(SELECT 1 FROM public.profiles WHERE id=p_operator AND role='admin' AND status='approved') THEN RAISE EXCEPTION 'Approved administrator required'; END IF;
 SELECT * INTO STRICT src FROM wholesale_ingest.sources WHERE source_key=p_source AND county='Collin' AND list_type='pre_foreclosure';
 IF p_batch IS NULL OR jsonb_typeof(p_receipt) IS DISTINCT FROM 'object' OR (SELECT count(*) FROM jsonb_object_keys(p_receipt))<>10
  OR NOT(p_receipt ?& ARRAY['processor','day','processed_at','dataset_url','ownership_snapshot_sha256','report_sha256','verification_granted','dispatch_authorized','outreach_authorized','notices'])
  OR coalesce(p_receipt->>'processor','') NOT IN ('foreclosure-batch/1.0','foreclosure-batch/1.1','foreclosure-batch/1.2')
  OR p_receipt->>'dataset_url' IS DISTINCT FROM 'https://data.texas.gov/d/ahis-pci3'
  OR p_receipt->'verification_granted' IS DISTINCT FROM 'false'::jsonb OR p_receipt->'dispatch_authorized' IS DISTINCT FROM 'false'::jsonb
  OR p_receipt->'outreach_authorized' IS DISTINCT FROM 'false'::jsonb
  OR coalesce(p_receipt->>'ownership_snapshot_sha256','') !~ '^[a-f0-9]{64}$'
  OR coalesce(p_receipt->>'report_sha256','') !~ '^[a-f0-9]{64}$' THEN RAISE EXCEPTION 'Invalid bulk receipt'; END IF;
 stamp:=(p_receipt->>'processed_at')::timestamptz; day:=(p_receipt->>'day')::date;
 IF stamp IS NULL OR NOT isfinite(stamp) OR stamp<'2000-01-01' OR stamp>now()+interval '5 minutes'
  OR day IS NULL OR NOT isfinite(day) OR day>current_date OR day<date '2000-01-01'
  OR jsonb_typeof(p_receipt->'notices') IS DISTINCT FROM 'array' OR jsonb_array_length(p_receipt->'notices') NOT BETWEEN 1 AND 500 THEN RAISE EXCEPTION 'Invalid bulk timestamp or size'; END IF;
 IF (SELECT count(DISTINCT value->>'document_id') FROM jsonb_array_elements(p_receipt->'notices'))<>jsonb_array_length(p_receipt->'notices') THEN RAISE EXCEPTION 'Duplicate batch documents'; END IF;
 PERFORM pg_advisory_xact_lock(hashtextextended(p_batch::text,0));
 SELECT * INTO old FROM wholesale_ingest.foreclosure_batches WHERE id=p_batch;
 IF FOUND THEN
  IF old.source_id<>src.id OR old.operator_id<>p_operator OR old.receipt<>p_receipt THEN RAISE EXCEPTION 'Bulk receipt conflict'; END IF;
  RETURN jsonb_build_object('batch_id',p_batch,'summary',old.summary,'verification_granted',false,'dispatch_authorized',false);
 END IF;
 FOR n IN SELECT value FROM jsonb_array_elements(p_receipt->'notices') LOOP
  IF jsonb_typeof(n) IS DISTINCT FROM 'object' OR (SELECT count(*) FROM jsonb_object_keys(n))<>10
   OR NOT(n ?& ARRAY['document_id','html_sha256','text_sha256s','parcel_id','appraisal_situs_matched','notice_situs_supported','trustee_case','auction_date','future_sale','holds'])
   OR coalesce(n->>'document_id','') !~ '^[0-9]{1,30}$' OR coalesce(n->>'html_sha256','') !~ '^[a-f0-9]{64}$'
   OR jsonb_typeof(n->'appraisal_situs_matched') IS DISTINCT FROM 'boolean' OR jsonb_typeof(n->'notice_situs_supported') IS DISTINCT FROM 'boolean'
   OR jsonb_typeof(n->'future_sale') IS DISTINCT FROM 'boolean' OR jsonb_typeof(n->'holds') IS DISTINCT FROM 'array'
   OR jsonb_array_length(n->'holds')>10 OR EXISTS(SELECT 1 FROM jsonb_array_elements_text(n->'holds') h WHERE h !~ '^[a-z_]{1,60}$')
   OR (n->>'parcel_id' IS NOT NULL AND n->>'parcel_id' !~ '^[1-9][0-9]{0,19}$')
   OR ((n->>'appraisal_situs_matched')::boolean AND n->>'parcel_id' IS NULL)
   OR (n->>'trustee_case' IS NOT NULL AND (
    jsonb_typeof(n->'trustee_case') IS DISTINCT FROM 'string' OR NOT (
      n->>'trustee_case' ~ '^[0-9]{4}-[0-9]{3,10}-[A-Z]{2}$'
      OR (p_receipt->>'processor' IN ('foreclosure-batch/1.1','foreclosure-batch/1.2') AND n->>'trustee_case' ~ '^(PLG:[0-9]{2}-[0-9]{6}-[0-9]{1,3}|FIRM:[0-9]{2}-[0-9]{6}|TS:[0-9]{2}-[0-9]{5})$')
    )))
   OR ((n->>'future_sale')::boolean AND ((n->>'auction_date')::date IS NULL OR (n->>'auction_date')::date<=day)) THEN RAISE EXCEPTION 'Invalid batch notice'; END IF;
  SELECT * INTO c FROM wholesale_ingest.foreclosure_captures WHERE source_id=src.id AND source_record_id=n->>'document_id' AND html_sha256=n->>'html_sha256';
  IF NOT FOUND OR jsonb_array_length(c.pages)<>c.expected_pages OR stamp<c.captured_at
   OR jsonb_typeof(n->'text_sha256s') IS DISTINCT FROM 'array' OR jsonb_array_length(n->'text_sha256s')<>c.expected_pages THEN RAISE EXCEPTION 'Batch must match complete county evidence'; END IF;
  IF EXISTS(SELECT 1 FROM jsonb_array_elements_text(n->'text_sha256s') WITH ORDINALITY h(digest,page)
   WHERE NOT EXISTS(SELECT 1 FROM wholesale_ingest.foreclosure_extractions e WHERE e.source_id=src.id AND e.source_record_id=c.source_record_id AND e.html_sha256=c.html_sha256
    AND e.page=h.page AND e.text_sha256=h.digest AND e.extracted_at<=stamp)) THEN RAISE EXCEPTION 'Batch must match extracted county evidence'; END IF;
 END LOOP;
 SELECT jsonb_build_object('county',src.county,'documents',count(*),
  'appraisal_situs_matched',count(*) FILTER(WHERE (value->>'appraisal_situs_matched')::boolean),
  'notice_situs_supported',count(*) FILTER(WHERE (value->>'notice_situs_supported')::boolean),
  'property_groups',count(DISTINCT CASE WHEN (value->>'appraisal_situs_matched')::boolean THEN 'parcel:'||(value->>'parcel_id') ELSE 'notice:'||(value->>'document_id') END),
  'future_sale_documents',count(*) FILTER(WHERE (value->>'future_sale')::boolean),
  'exception_documents',count(*) FILTER(WHERE jsonb_array_length(value->'holds')>0),
  'evidence_review_candidates',count(*) FILTER(WHERE jsonb_array_length(value->'holds')=0),
  'trace_eligible',0) INTO summary FROM jsonb_array_elements(p_receipt->'notices');
 INSERT INTO wholesale_ingest.foreclosure_batches VALUES(p_batch,src.id,p_receipt,summary,stamp,p_operator,now());
 RETURN jsonb_build_object('batch_id',p_batch,'summary',summary,'verification_granted',false,'dispatch_authorized',false);
END; $function$

CREATE OR REPLACE FUNCTION public.save_foreclosure_captures(p_operator uuid, p_source text, p_items jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO 'public', 'wholesale_ingest', 'pg_temp'
AS $function$
DECLARE src wholesale_ingest.sources; item jsonb; old wholesale_ingest.foreclosure_captures;
 cnt integer; expected integer; stamp timestamptz; doc text; url text; digest text;
BEGIN
 IF NOT EXISTS(SELECT 1 FROM public.profiles WHERE id=p_operator AND role='admin' AND status='approved') THEN RAISE EXCEPTION 'Approved administrator required'; END IF;
 SELECT * INTO STRICT src FROM wholesale_ingest.sources WHERE source_key=p_source AND list_type='pre_foreclosure';
 IF jsonb_typeof(p_items) IS DISTINCT FROM 'array' OR jsonb_array_length(p_items) NOT BETWEEN 1 AND 500 THEN RAISE EXCEPTION 'Invalid capture batch'; END IF;
 IF (SELECT count(DISTINCT value->>'document_id') FROM jsonb_array_elements(p_items))<>jsonb_array_length(p_items) THEN RAISE EXCEPTION 'Duplicate or missing document IDs'; END IF;
 FOR item IN SELECT value FROM jsonb_array_elements(p_items) ORDER BY value->>'document_id' LOOP
  doc:=item->>'document_id';url:=item->>'source_url';digest:=item->>'html_sha256';
  IF doc IS NULL OR doc !~ '^[0-9]{1,30}$' OR digest IS NULL OR digest !~ '^[a-f0-9]{64}$' OR url IS DISTINCT FROM
   (CASE src.county WHEN 'Collin' THEN 'https://apps2.collincountytx.gov/ForeclosureNotices/DetailPage/'||doc ELSE 'https://dallas.tx.publicsearch.us/doc/'||doc END) THEN RAISE EXCEPTION 'Invalid official capture identity'; END IF;
  IF NOT EXISTS(SELECT 1 FROM wholesale_ingest.records r JOIN wholesale_ingest.ingest_runs run ON run.id=r.run_id WHERE run.source_id=src.id AND r.source_record_id=doc) THEN RAISE EXCEPTION 'Capture must match an ingested notice'; END IF;
  IF (SELECT count(*) FROM jsonb_object_keys(item))<>6 OR NOT (item ?& ARRAY['document_id','source_url','html_sha256','captured_at','expected_pages','pages']) THEN RAISE EXCEPTION 'Unexpected capture fields'; END IF;
  expected:=(item->>'expected_pages')::integer;stamp:=(item->>'captured_at')::timestamptz;
  IF expected IS NULL OR expected NOT BETWEEN 1 AND 100 OR stamp IS NULL OR NOT isfinite(stamp) OR stamp<'2000-01-01' OR stamp>now()+interval '5 minutes' THEN RAISE EXCEPTION 'Invalid capture date or page count'; END IF;
  IF jsonb_typeof(item->'pages') IS DISTINCT FROM 'array' THEN RAISE EXCEPTION 'Invalid page receipts'; END IF;
  cnt:=jsonb_array_length(item->'pages');
  IF cnt NOT BETWEEN 1 AND expected OR EXISTS(SELECT 1 FROM jsonb_array_elements(item->'pages') WITH ORDINALITY p(value,n) WHERE
   jsonb_typeof(value) IS DISTINCT FROM 'object' OR value->>'page' IS DISTINCT FROM n::text OR coalesce(value->>'sha256','') !~ '^[a-f0-9]{64}$')
   OR (SELECT count(DISTINCT value->>'sha256') FROM jsonb_array_elements(item->'pages'))<>cnt THEN RAISE EXCEPTION 'Invalid ordered page receipts'; END IF;
  PERFORM pg_advisory_xact_lock(hashtextextended(src.id::text||':'||doc||':'||digest,0));
  SELECT * INTO old FROM wholesale_ingest.foreclosure_captures WHERE source_id=src.id AND source_record_id=doc AND html_sha256=digest;
  IF FOUND THEN
   IF old.expected_pages<>expected OR old.captured_at<>stamp OR old.source_url<>url THEN RAISE EXCEPTION 'Capture identity conflict'; END IF;
   IF NOT(old.pages <@ (item->'pages')) AND NOT((item->'pages') <@ old.pages) THEN RAISE EXCEPTION 'Page evidence conflict'; END IF;
   IF jsonb_array_length(old.pages)<cnt THEN UPDATE wholesale_ingest.foreclosure_captures SET pages=item->'pages',operator_id=p_operator,received_at=now() WHERE source_id=src.id AND source_record_id=doc AND html_sha256=digest; END IF;
  ELSE
   INSERT INTO wholesale_ingest.foreclosure_captures VALUES(src.id,doc,digest,url,stamp,expected,item->'pages',p_operator,now());
  END IF;
 END LOOP;
 RETURN jsonb_build_object('accepted',jsonb_array_length(p_items),'source_key',p_source,'operator_id',p_operator,'verification_granted',false,'outreach_authorized',false);
END; $function$

CREATE OR REPLACE FUNCTION public.save_foreclosure_extractions(p_operator uuid, p_source text, p_items jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO 'public', 'wholesale_ingest', 'pg_temp'
AS $function$
DECLARE src wholesale_ingest.sources; item jsonb; capture wholesale_ingest.foreclosure_captures;
 old wholesale_ingest.foreclosure_extractions; n integer; stamp timestamptz; score numeric;
 doc text; summary_hash text; image_hash text; text_hash text; contents text; engine_id text;
BEGIN
 IF NOT EXISTS(SELECT 1 FROM public.profiles WHERE id=p_operator AND role='admin' AND status='approved') THEN RAISE EXCEPTION 'Approved administrator required'; END IF;
 SELECT * INTO STRICT src FROM wholesale_ingest.sources WHERE source_key=p_source AND list_type='pre_foreclosure';
 IF jsonb_typeof(p_items) IS DISTINCT FROM 'array' OR jsonb_array_length(p_items) NOT BETWEEN 1 AND 500 THEN RAISE EXCEPTION 'Invalid extraction batch'; END IF;
 IF (SELECT count(DISTINCT (value->>'document_id',value->>'page',value->>'engine')) FROM jsonb_array_elements(p_items))<>jsonb_array_length(p_items) THEN RAISE EXCEPTION 'Duplicate extraction pages'; END IF;
 FOR item IN SELECT value FROM jsonb_array_elements(p_items) ORDER BY value->>'document_id',value->>'page',value->>'engine' LOOP
  IF jsonb_typeof(item) IS DISTINCT FROM 'object' OR (SELECT count(*) FROM jsonb_object_keys(item))<>10 OR NOT(item ?& ARRAY['document_id','source_url','html_sha256','page','image_sha256','engine','text','text_sha256','confidence','extracted_at']) THEN RAISE EXCEPTION 'Unexpected extraction fields'; END IF;
  doc:=item->>'document_id';summary_hash:=item->>'html_sha256';image_hash:=item->>'image_sha256';
  text_hash:=item->>'text_sha256';contents:=item->>'text';engine_id:=item->>'engine';
  IF jsonb_typeof(item->'page') IS DISTINCT FROM 'number' OR coalesce(item->>'page','') !~ '^[0-9]+$' OR jsonb_typeof(item->'confidence') IS DISTINCT FROM 'number' THEN RAISE EXCEPTION 'Invalid extraction numeric fields'; END IF;
  n:=(item->>'page')::integer;score:=(item->>'confidence')::numeric;stamp:=(item->>'extracted_at')::timestamptz;
  IF coalesce(doc,'') !~ '^[0-9]{1,30}$' OR coalesce(summary_hash,'') !~ '^[a-f0-9]{64}$' OR coalesce(image_hash,'') !~ '^[a-f0-9]{64}$'
   OR coalesce(text_hash,'') !~ '^[a-f0-9]{64}$' OR coalesce(engine_id,'') !~ '^[a-zA-Z0-9/._-]{1,128}$'
   OR jsonb_typeof(item->'text') IS DISTINCT FROM 'string' OR octet_length(contents)>100000
   OR text_hash IS DISTINCT FROM encode(sha256(convert_to(contents,'UTF8')),'hex')
   OR n NOT BETWEEN 1 AND 100 OR score NOT BETWEEN 0 AND 100 OR stamp IS NULL OR NOT isfinite(stamp)
   OR stamp<'2000-01-01' OR stamp>now()+interval '5 minutes' THEN RAISE EXCEPTION 'Invalid extraction receipt'; END IF;
  SELECT * INTO capture FROM wholesale_ingest.foreclosure_captures WHERE source_id=src.id AND source_record_id=doc AND html_sha256=summary_hash;
  IF NOT FOUND OR capture.source_url IS DISTINCT FROM item->>'source_url' OR jsonb_array_length(capture.pages)<>capture.expected_pages
   OR capture.pages->(n-1)->>'sha256' IS DISTINCT FROM image_hash OR stamp<capture.captured_at THEN RAISE EXCEPTION 'Extraction must match complete captured evidence'; END IF;
  PERFORM pg_advisory_xact_lock(hashtextextended(src.id::text||':'||doc||':'||summary_hash||':'||n::text||':'||engine_id,0));
  SELECT * INTO old FROM wholesale_ingest.foreclosure_extractions WHERE source_id=src.id AND source_record_id=doc AND html_sha256=summary_hash AND page=n AND engine=engine_id;
  IF FOUND THEN
   IF old.image_sha256<>image_hash OR old.text_sha256<>text_hash OR old.text_length<>length(contents) OR old.confidence<>score OR old.extracted_at<>stamp THEN RAISE EXCEPTION 'Extraction evidence conflict'; END IF;
  ELSE
   INSERT INTO wholesale_ingest.foreclosure_extractions VALUES(src.id,doc,summary_hash,n,engine_id,image_hash,length(contents),text_hash,score,contents !~ '\S' OR score<85,stamp,p_operator,now());
  END IF;
 END LOOP;
 RETURN jsonb_build_object('accepted',jsonb_array_length(p_items),'source_key',p_source,'verification_granted',false,'outreach_authorized',false);
END; $function$

CREATE OR REPLACE FUNCTION public.save_list_score(p_id uuid, p_lead uuid, p_input_hash text, p_model text, p_prompt text, p_receipt text, p_result jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
DECLARE snapshot jsonb; old wholesale_ingest.lead_evaluations; item jsonb; category text; points int;
 total int:=0; stack int; expected int; ids jsonb; ref jsonb; fingerprint text; flags jsonb; route text;
BEGIN
 IF p_id IS NULL OR p_lead IS NULL OR coalesce(p_input_hash,'') !~ '^[a-f0-9]{64}$'
 OR coalesce(length(p_model),0) NOT BETWEEN 1 AND 100 OR p_prompt IS DISTINCT FROM 'daily-list-score-v1'
 OR coalesce(length(p_receipt),0) NOT BETWEEN 1 AND 255 THEN RETURN jsonb_build_object('blocked','invalid_identity'); END IF;
 PERFORM pg_advisory_xact_lock(hashtextextended('list-score:'||p_lead::text,0));
 fingerprint:=encode(sha256(convert_to(p_result::text,'UTF8')),'hex');
 SELECT * INTO old FROM wholesale_ingest.lead_evaluations WHERE id=p_id OR (lead_id=p_lead AND input_hash=p_input_hash AND prompt_version=p_prompt) ORDER BY id LIMIT 1;
 IF FOUND THEN
  IF old.id IS DISTINCT FROM p_id OR old.lead_id IS DISTINCT FROM p_lead OR old.input_hash IS DISTINCT FROM p_input_hash
  OR old.model_version IS DISTINCT FROM p_model OR old.prompt_version IS DISTINCT FROM p_prompt OR old.model_receipt IS DISTINCT FROM p_receipt
  OR old.response_hash IS DISTINCT FROM fingerprint THEN RETURN jsonb_build_object('blocked','reference_conflict'); END IF;
  RETURN jsonb_build_object('evaluation',to_jsonb(old),'replayed',true,'current',public.list_scoring_input(p_lead)->>'input_hash'=p_input_hash,'outreach_authorized',false);
 END IF;
 snapshot:=public.list_scoring_input(p_lead);
 IF snapshot ? 'blocked' THEN RETURN snapshot; END IF;
 IF snapshot->>'input_hash' IS DISTINCT FROM p_input_hash THEN RETURN jsonb_build_object('blocked','stale_input'); END IF;
 snapshot:=snapshot->'input';
 SELECT count(DISTINCT value->>'list_type') INTO stack FROM jsonb_array_elements(snapshot->'signals');
 IF jsonb_typeof(p_result) IS DISTINCT FROM 'object' OR p_result-ARRAY['components','needs_to_sell']<>'{}'::jsonb
 OR jsonb_typeof(p_result->'components') IS DISTINCT FROM 'object' THEN RETURN jsonb_build_object('blocked','invalid_result'); END IF;
 IF (SELECT array_agg(key ORDER BY key) FROM jsonb_object_keys(p_result->'components') key)
 IS DISTINCT FROM ARRAY['contactability','distress_stack','equity','need_to_sell','recency'] THEN RETURN jsonb_build_object('blocked','invalid_components'); END IF;
 FOR category,item IN SELECT key,value FROM jsonb_each(p_result->'components') LOOP
  IF jsonb_typeof(item) IS DISTINCT FROM 'object' OR item-ARRAY['points','reason','evidence_ids']<>'{}'::jsonb
  OR coalesce(item->>'points','') !~ '^[0-9]{1,2}$' OR jsonb_typeof(item->'points') IS DISTINCT FROM 'number'
  OR jsonb_typeof(item->'reason') IS DISTINCT FROM 'string' OR length(trim(item->>'reason')) NOT BETWEEN 1 AND 1000
  OR jsonb_typeof(item->'evidence_ids') IS DISTINCT FROM 'array' THEN RETURN jsonb_build_object('blocked','invalid_component'); END IF;
  points:=(item->>'points')::int;
  expected:=CASE category WHEN 'distress_stack' THEN 30 WHEN 'need_to_sell' THEN 25 WHEN 'equity' THEN 20 WHEN 'contactability' THEN 15 ELSE 10 END;
  IF points>expected OR jsonb_array_length(item->'evidence_ids')>100 THEN RETURN jsonb_build_object('blocked','invalid_points'); END IF;
  IF category='equity' AND (points<>0 OR jsonb_array_length(item->'evidence_ids')<>0) THEN RETURN jsonb_build_object('blocked','equity_unknown'); END IF;
  IF category='distress_stack' AND points<>stack*30/4 THEN RETURN jsonb_build_object('blocked','stack_mismatch'); END IF;
  ids:=CASE WHEN category='contactability' THEN snapshot->'contacts' ELSE snapshot->'signals' END;
  IF category='recency' THEN
   SELECT coalesce(jsonb_agg(e),'[]') INTO ids FROM jsonb_array_elements(ids) e
   WHERE (e->>'filed_date')::date BETWEEN (snapshot->>'as_of')::date-29 AND (snapshot->>'as_of')::date;
  END IF;
  FOR ref IN SELECT value FROM jsonb_array_elements(item->'evidence_ids') LOOP
   IF jsonb_typeof(ref) IS DISTINCT FROM 'string' OR NOT EXISTS(SELECT 1 FROM jsonb_array_elements(ids) e WHERE e->'id'=ref)
   THEN RETURN jsonb_build_object('blocked','unknown_evidence'); END IF;
  END LOOP;
  IF points>0 AND jsonb_array_length(item->'evidence_ids')=0 THEN RETURN jsonb_build_object('blocked','missing_evidence'); END IF;
  total:=total+points;
 END LOOP;
 IF p_result->>'needs_to_sell' NOT IN ('unknown','inferred') OR p_result->>'needs_to_sell' IS NULL
 OR (p_result->>'needs_to_sell'='inferred' AND jsonb_array_length(p_result#>'{components,need_to_sell,evidence_ids}')=0)
 OR (p_result->>'needs_to_sell'='unknown' AND (p_result#>>'{components,need_to_sell,points}')::int<>0)
 THEN RETURN jsonb_build_object('blocked','invalid_need_assessment'); END IF;
 flags:=jsonb_build_array('equity_unknown','off_market_unknown','direct_to_seller_unknown','outreach_requires_compliance',
 CASE WHEN p_result->>'needs_to_sell'='inferred' THEN 'need_to_sell_inferred_not_confirmed' ELSE 'need_to_sell_unknown' END);
 route:=CASE WHEN total>=(snapshot->>'score_threshold')::int AND snapshot#>>'{property,is_vacant_lot}'='true' THEN 'underwrite_lot'
 WHEN total>=(snapshot->>'score_threshold')::int THEN 'review' ELSE 'nurture' END;
 INSERT INTO wholesale_ingest.lead_evaluations(id,lead_id,input_hash,model_version,prompt_version,score,reasons,flags,route,stack_count,input_snapshot,model_receipt,response_hash)
 VALUES(p_id,p_lead,p_input_hash,p_model,p_prompt,total,p_result,flags,route,stack,snapshot,p_receipt,fingerprint) RETURNING * INTO old;
 RETURN jsonb_build_object('evaluation',to_jsonb(old),'replayed',false,'current',true,'outreach_authorized',false);
END $function$

CREATE OR REPLACE FUNCTION public.save_manual_analysis(p_id uuid, p_lead uuid, p_operator uuid, p_inputs jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
DECLARE saved public.deal_analyses%ROWTYPE; arv numeric; repairs numeric; fee numeric; ceiling numeric;
BEGIN
 IF NOT EXISTS(SELECT 1 FROM public.profiles WHERE id=p_operator AND status='approved') THEN RAISE EXCEPTION 'Operator not approved'; END IF;
 PERFORM pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended('analysis:'||p_id,0));
 SELECT * INTO saved FROM public.deal_analyses WHERE id=p_id;
 IF FOUND THEN
  IF saved.lead_id IS DISTINCT FROM p_lead OR saved.created_by IS DISTINCT FROM p_operator
   OR saved.operator_inputs IS DISTINCT FROM p_inputs THEN RETURN jsonb_build_object('conflict',true); END IF;
  RETURN jsonb_build_object('analysis',to_jsonb(saved),'reused',true);
 END IF;
 IF NOT EXISTS(SELECT 1 FROM public.leads WHERE id=p_lead) THEN RETURN jsonb_build_object('missing',true); END IF;
 arv:=(p_inputs->>'arv')::numeric; repairs:=(p_inputs->>'repairs')::numeric; fee:=(p_inputs->>'assignment_fee')::numeric;
 IF arv IS NULL OR repairs IS NULL OR fee IS NULL OR arv<=0 OR arv>100000000 OR repairs<0 OR repairs>100000000 OR fee<0 OR fee>100000000
  OR coalesce(p_inputs->>'condition','') NOT IN ('cosmetic','moderate','full_renovation')
  OR jsonb_typeof(p_inputs->'comps') IS DISTINCT FROM 'array'
  OR jsonb_typeof(p_inputs->'line_items') IS DISTINCT FROM 'array' THEN RAISE EXCEPTION 'Invalid analysis'; END IF;
 ceiling:=arv*0.70-repairs-fee;
 INSERT INTO public.deal_analyses(id,lead_id,created_by,operator_inputs,arv_low,arv_mid,arv_high,arv_confidence,arv_comp_count,arv_notes,
 repair_tier,repair_cost_low,repair_cost_mid,repair_cost_high,assignment_fee,mao,offer_range_low,offer_range_high,is_viable,summary)
 VALUES(p_id,p_lead,p_operator,p_inputs,arv,arv,arv,'low',
 (SELECT count(*) FROM jsonb_array_elements(p_inputs->'comps') c WHERE (c->>'sale_price')::numeric>0 AND (c->>'sqft')::numeric>0),
 'Operator estimates; comparable and repair inputs retained for review.',
 CASE p_inputs->>'condition' WHEN 'cosmetic' THEN 'light' WHEN 'full_renovation' THEN 'heavy' ELSE 'moderate' END,
 repairs,repairs,repairs,fee,ceiling,greatest(0,ceiling*0.9),greatest(0,ceiling),ceiling>0,
 coalesce(nullif(p_inputs->>'summary',''),'Manual comparable and repair analysis.')) RETURNING * INTO saved;
 UPDATE public.leads SET estimated_repairs=repairs WHERE id=p_lead;
 RETURN jsonb_build_object('analysis',to_jsonb(saved),'reused',false);
END $function$

CREATE OR REPLACE FUNCTION public.save_retell_api_generation(p_turn uuid, p_messages jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
DECLARE t public.retell_api_turns; s public.retell_api_sessions; m jsonb; total integer:=0;
BEGIN
 IF jsonb_typeof(p_messages) IS DISTINCT FROM 'array' OR jsonb_array_length(p_messages) NOT BETWEEN 1 AND 20 THEN RAISE EXCEPTION 'Invalid generated turn'; END IF;
 FOR m IN SELECT value FROM jsonb_array_elements(p_messages) LOOP
  IF jsonb_typeof(m) IS DISTINCT FROM 'object' OR (SELECT count(*) FROM jsonb_object_keys(m))<>2
   OR NOT(m ?& ARRAY['message_id','content']) OR jsonb_typeof(m->'message_id') IS DISTINCT FROM 'string' OR coalesce(m->>'message_id','') !~ '^[A-Za-z0-9_-]{1,128}$'
   OR jsonb_typeof(m->'content') IS DISTINCT FROM 'string' OR length(trim(m->>'content')) NOT BETWEEN 1 AND 1600 THEN RAISE EXCEPTION 'Invalid generated message'; END IF;
  total:=total+length(m->>'content')+1;
 END LOOP;
 IF total-1>1600 OR (SELECT count(DISTINCT value->>'message_id') FROM jsonb_array_elements(p_messages))<>jsonb_array_length(p_messages) THEN RAISE EXCEPTION 'Ambiguous or oversized generated turn'; END IF;
 SELECT * INTO t FROM public.retell_api_turns WHERE id=p_turn;
 IF NOT FOUND THEN RAISE EXCEPTION 'Missing turn'; END IF;
 SELECT * INTO s FROM public.retell_api_sessions WHERE id=t.session_id FOR UPDATE;
 SELECT * INTO t FROM public.retell_api_turns WHERE id=p_turn FOR UPDATE;
 IF t.generated_messages=p_messages AND t.status IN ('generated','submitting','accepted') THEN RETURN jsonb_build_object('saved',true,'replayed',true); END IF;
 IF t.status<>'generating' OR s.status<>'ready' OR t.generated_messages IS NOT NULL THEN RAISE EXCEPTION 'Generation receipt conflict'; END IF;
 UPDATE public.retell_api_turns SET generated_messages=p_messages,status='generated' WHERE id=t.id;
 RETURN jsonb_build_object('saved',true,'replayed',false,'dispatch_authorized',false);
END $function$

CREATE OR REPLACE FUNCTION public.scan_launch_monitor()
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
DECLARE owner uuid; finding record; issue uuid; prior_resolved timestamptz; alert_id uuid; task_id uuid;
 created_count int:=0; resolved_count int:=0;
BEGIN
 IF NOT pg_catalog.pg_try_advisory_xact_lock(pg_catalog.hashtextextended('wholesaleos:launch-monitor',0)) THEN RETURN jsonb_build_object('busy',true); END IF;
 SELECT p.id INTO owner FROM public.app_settings a JOIN public.profiles p ON p.id::text=a.value WHERE a.key='lead_owner_user_id' AND p.status='approved';
 IF owner IS NULL THEN RAISE EXCEPTION 'Approved incident owner unavailable'; END IF;
 UPDATE public.launch_monitor_incidents i SET resolved_at=now() WHERE i.resolved_at IS NULL
 AND NOT EXISTS(SELECT 1 FROM public.launch_monitor_findings() f WHERE f.category=i.category AND f.reference=i.reference);
 GET DIAGNOSTICS resolved_count=ROW_COUNT;
 FOR finding IN SELECT f.* FROM public.launch_monitor_findings() f
 LEFT JOIN public.launch_monitor_incidents i ON i.category=f.category AND i.reference=f.reference
 WHERE i.id IS NULL OR i.resolved_at IS NOT NULL ORDER BY f.created_at LIMIT 50
 LOOP
  SELECT id,resolved_at INTO issue,prior_resolved FROM public.launch_monitor_incidents
   WHERE category=finding.category AND reference=finding.reference;
  IF issue IS NULL THEN
   INSERT INTO public.launch_monitor_incidents(category,reference,lead_id)
    VALUES(finding.category,finding.reference,finding.lead_id) RETURNING id INTO issue;
   alert_id:=issue;
   task_id:=CASE WHEN finding.category='intake' THEN finding.reference ELSE issue END;
  ELSE
   UPDATE public.launch_monitor_incidents SET resolved_at=NULL WHERE id=issue;
   alert_id:=gen_random_uuid(); task_id:=alert_id;
  END IF;
  INSERT INTO public.tasks(id,title,description,priority,status,type,lead_id,assigned_to,due_date)
  VALUES(task_id,'Review stalled '||finding.category||' processing',
   'Launch monitor reference: '||finding.reference||'. Reconcile the stored receipt/provider outcome. Do not resend uncertain outreach or replay seller contact.',
   'high','pending','follow_up',finding.lead_id,owner,now()) ON CONFLICT(id) DO NOTHING;
  INSERT INTO public.app_notifications(id,recipient_id,type,title,body,action_url,action_label,lead_id,metadata)
  VALUES(alert_id,owner,'system','Stalled '||finding.category||' needs review',
   'An aged receipt or unfinished outcome needs owner review. Open the assigned task; no outreach was replayed.',
   '/tasks','Review tasks',finding.lead_id,jsonb_build_object('integration_failure',true,'launch_monitor',true,'incident_id',issue,'category',finding.category,'reference',finding.reference))
  ON CONFLICT(id) DO NOTHING;
  created_count:=created_count+1;
 END LOOP;
 RETURN jsonb_build_object('created',created_count,'resolved',resolved_count,'snapshot',public.launch_monitor_snapshot());
END $function$

CREATE OR REPLACE FUNCTION public.scan_list_pipeline()
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
DECLARE v_summary jsonb; ranked jsonb;
BEGIN
 v_summary:=wholesale_ingest.scan_at(now());
 IF v_summary->>'busy'='true' THEN RETURN v_summary; END IF;
 SELECT coalesce(jsonb_agg(to_jsonb(t) ORDER BY t.score DESC,t.created_at DESC,t.lead_id),'[]') INTO ranked FROM (
  SELECT latest.lead_id,latest.score,latest.reasons,latest.flags,latest.route,latest.created_at
  FROM (SELECT DISTINCT ON (lead_id) * FROM wholesale_ingest.lead_evaluations ORDER BY lead_id,created_at DESC,id DESC) latest
  WHERE latest.input_snapshot IS NOT NULL AND latest.prompt_version='daily-list-score-v1'
  AND latest.input_hash=public.list_scoring_input(latest.lead_id)->>'input_hash'
  ORDER BY latest.score DESC,latest.created_at DESC,latest.lead_id LIMIT 10
 ) t;
 v_summary:=jsonb_set(v_summary,'{top_ten}',ranked);
 v_summary:=v_summary||jsonb_build_object('scoring_monitor',wholesale_ingest.scan_scoring_at(now()));
 UPDATE wholesale_ingest.daily_digests SET summary=v_summary WHERE day=(v_summary->>'day')::date;
 RETURN v_summary;
END $function$

CREATE OR REPLACE FUNCTION public.settle_list_trace(p_id uuid, p_state text, p_actual_cents integer, p_provider_receipt text, p_result_hash text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
DECLARE saved wholesale_ingest.skip_trace_requests;
BEGIN
 SELECT * INTO saved FROM wholesale_ingest.skip_trace_requests WHERE id=p_id FOR UPDATE;
 IF NOT FOUND THEN RETURN jsonb_build_object('blocked','request_missing'); END IF;
 IF p_state='unknown' AND p_actual_cents IS NULL AND p_provider_receipt IS NULL AND p_result_hash IS NULL THEN
  IF saved.state IN ('submitted','unknown') THEN
   UPDATE wholesale_ingest.skip_trace_requests SET state='unknown' WHERE id=p_id RETURNING * INTO saved;
   RETURN jsonb_build_object('request',to_jsonb(saved),'dispatch',false);
  END IF;
  RETURN jsonb_build_object('blocked','invalid_transition');
 END IF;
 IF p_state IS NULL OR p_state NOT IN ('completed','failed') OR p_actual_cents IS NULL
 OR p_actual_cents<0 OR p_actual_cents>saved.reserved_cents
 OR coalesce(length(trim(p_provider_receipt)),0) NOT BETWEEN 1 AND 255
 OR coalesce(p_result_hash,'') !~ '^[a-f0-9]{64}$'
 THEN RETURN jsonb_build_object('blocked','unconfirmed_settlement'); END IF;
 IF saved.state IN ('completed','failed') THEN
  IF saved.state<>p_state OR saved.actual_cents<>p_actual_cents OR saved.provider_job_id IS DISTINCT FROM p_provider_receipt
   OR saved.result_hash IS DISTINCT FROM p_result_hash THEN RETURN jsonb_build_object('blocked','settlement_conflict'); END IF;
  RETURN jsonb_build_object('request',to_jsonb(saved),'replayed',true,'dispatch',false);
 END IF;
 IF saved.state NOT IN ('submitted','unknown') THEN RETURN jsonb_build_object('blocked','invalid_transition'); END IF;
 -- Hold the original day's budget through provider ambiguity, even after midnight.
 PERFORM 1 FROM wholesale_ingest.daily_budgets WHERE spend_day=saved.spend_day FOR UPDATE;
 UPDATE wholesale_ingest.daily_budgets SET reserved_cents=reserved_cents-saved.reserved_cents,
  actual_cents=actual_cents+p_actual_cents WHERE spend_day=saved.spend_day;
 IF NOT FOUND THEN RAISE EXCEPTION 'Original trace budget missing'; END IF;
 UPDATE wholesale_ingest.skip_trace_requests SET state=p_state,actual_cents=p_actual_cents,
  provider_job_id=p_provider_receipt,result_hash=p_result_hash,settled_at=clock_timestamp() WHERE id=p_id RETURNING * INTO saved;
 RETURN jsonb_build_object('request',to_jsonb(saved),'replayed',false,'dispatch',false);
END $function$

CREATE OR REPLACE FUNCTION public.sync_retell_app_outcome(p_message uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
DECLARE e public.sms_events; j public.retell_form_sms_jobs; t public.retell_api_turns; s public.retell_api_sessions; accepted boolean; issue boolean;
BEGIN
 SELECT * INTO e FROM public.sms_events WHERE id=p_message;
 IF NOT FOUND OR e.provider<>'twilio' OR e.direction<>'outbound' OR e.raw_payload->>'transport' IS DISTINCT FROM 'app_twilio' THEN
  RETURN jsonb_build_object('synced',false,'reason','unrelated_receipt'); END IF;
 PERFORM pg_advisory_xact_lock(hashtextextended('seller-outreach:'||e.phone_number,0));
 -- Lock parent before receipt so callbacks and dispatch completion use one order.
 SELECT * INTO j FROM public.retell_form_sms_jobs WHERE id=(e.raw_payload->>'form_job_id')::uuid FOR UPDATE;
 IF NOT FOUND OR j.delivery_transport<>'app_twilio' OR j.lead_id IS DISTINCT FROM e.lead_id
  OR j.phone_number IS DISTINCT FROM e.phone_number OR j.delivery_sender IS DISTINCT FROM e.raw_payload->>'sender_number' THEN RAISE EXCEPTION 'App delivery identity mismatch'; END IF;
 SELECT * INTO s FROM public.retell_api_sessions WHERE id=j.id FOR UPDATE;
 SELECT * INTO t FROM public.retell_api_turns WHERE outbound_id=p_message FOR UPDATE;
 SELECT * INTO e FROM public.sms_events WHERE id=p_message FOR UPDATE;
 accepted:=e.status IN ('accepted','scheduled','queued','sending','sent','delivered','read')
  AND coalesce(e.raw_payload->>'provider_sid','') ~ '^SM[0-9a-fA-F]{32}$' AND coalesce(e.raw_payload->>'delivery_conflict','false')<>'true';
 issue:=e.status IN ('failed','undelivered','canceled','unknown','blocked');
 IF p_message=j.id THEN
  IF e.body IS DISTINCT FROM j.delivery_body OR e.raw_payload ? 'api_turn_id' THEN RAISE EXCEPTION 'Acknowledgment receipt mismatch'; END IF;
  IF accepted AND j.status='processing' THEN
   UPDATE public.retell_form_sms_jobs SET status='accepted',reason='Twilio accepted app acknowledgment; see exact carrier receipt' WHERE id=j.id;
  ELSIF issue AND j.status IN ('processing','accepted','review') THEN
   UPDATE public.retell_form_sms_jobs SET status=CASE WHEN e.status='blocked' AND j.status='processing' THEN 'stopped' ELSE 'review' END,
    reason='App acknowledgment outcome: '||e.status||'; do not resend automatically' WHERE id=j.id;
   UPDATE public.retell_api_sessions SET status='review',reason='Acknowledgment delivery needs review' WHERE id=j.id AND status IN ('pending','creating','ready');
  END IF;
 ELSE
  IF t.id IS NULL OR t.session_id<>j.id OR e.raw_payload->>'api_turn_id' IS DISTINCT FROM t.id::text
   OR e.raw_payload->>'inbound_sid' IS DISTINCT FROM t.inbound_sid THEN RAISE EXCEPTION 'Reply receipt mismatch'; END IF;
  IF accepted AND t.status='submitting' THEN
   UPDATE public.retell_api_turns SET status='accepted',reason='Twilio accepted; see exact carrier receipt' WHERE id=t.id;
  ELSIF issue AND t.status IN ('submitting','accepted') THEN
   UPDATE public.retell_api_turns SET status='review',reason='Carrier outcome: '||e.status||'; do not resend automatically' WHERE id=t.id;
   UPDATE public.retell_api_sessions SET status='review',reason='Reply delivery needs review' WHERE id=j.id AND status IN ('creating','ready');
  END IF;
 END IF;
 -- Review holds survive later receipt updates until explicit operator resolution.
 RETURN jsonb_build_object('synced',true,'carrier_status',e.status,'carrier_accepted',coalesce(accepted,false),'dispatch_authorized',false);
END $function$

CREATE OR REPLACE FUNCTION public.transition_appointment(p_id uuid, p_expected text, p_next text, p_operator uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
DECLARE saved public.appointments%ROWTYPE;
BEGIN
 IF NOT EXISTS(SELECT 1 FROM public.profiles WHERE id=p_operator AND status='approved') THEN RAISE EXCEPTION 'Operator not approved'; END IF;
 SELECT * INTO saved FROM public.appointments WHERE id=p_id FOR UPDATE;
 IF NOT FOUND THEN RETURN jsonb_build_object('missing',true); END IF;
 IF p_next NOT IN ('confirmed','completed','no_show','cancelled') THEN RETURN jsonb_build_object('conflict',true); END IF;
 IF saved.status=p_next THEN RETURN jsonb_build_object('appointment',to_jsonb(saved),'reused',true); END IF;
 IF saved.status<>p_expected OR saved.status NOT IN ('scheduled','confirmed')
  OR (p_next IN ('completed','no_show') AND saved.scheduled_at>now()) THEN
  RETURN jsonb_build_object('conflict',true); END IF;
 UPDATE public.appointments SET status=p_next WHERE id=p_id RETURNING * INTO saved;
 RETURN jsonb_build_object('appointment',to_jsonb(saved));
END $function$

CREATE OR REPLACE FUNCTION public.update_pipeline_deal(p_id uuid, p_operator uuid, p_expected timestamp with time zone, p_patch jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
DECLARE saved public.deals%ROWTYPE; proposed public.deals%ROWTYPE;
BEGIN
 IF NOT EXISTS(SELECT 1 FROM public.profiles WHERE id=p_operator AND status='approved') THEN RAISE EXCEPTION 'Operator not approved'; END IF;
 IF p_patch ?| ARRAY['id','lead_id','created_by','created_at','updated_at','creation_manifest'] THEN RETURN jsonb_build_object('conflict',true); END IF;
 SELECT * INTO saved FROM public.deals WHERE id=p_id FOR UPDATE;
 IF NOT FOUND THEN RETURN jsonb_build_object('missing',true); END IF;
 IF to_jsonb(saved) @> p_patch THEN RETURN jsonb_build_object('deal',to_jsonb(saved),'reused',true); END IF;
 IF saved.updated_at IS DISTINCT FROM p_expected THEN RETURN jsonb_build_object('conflict',true); END IF;
 proposed:=jsonb_populate_record(saved,p_patch);
 IF proposed.stage NOT IN ('closed','cancelled') AND EXISTS(SELECT 1 FROM public.deals WHERE lead_id=proposed.lead_id AND id<>p_id AND stage NOT IN ('closed','cancelled')) THEN
  RETURN jsonb_build_object('existing_id',(SELECT id FROM public.deals WHERE lead_id=proposed.lead_id AND id<>p_id AND stage NOT IN ('closed','cancelled') LIMIT 1)); END IF;
 IF NOT public.deal_handoff_valid(proposed) THEN RETURN jsonb_build_object('invalid',true); END IF;
 UPDATE public.deals SET
 deal_name=proposed.deal_name,stage=proposed.stage,contract_price=proposed.contract_price,arv=proposed.arv,repair_estimate=proposed.repair_estimate,
 assignment_fee=proposed.assignment_fee,buyer_price=proposed.buyer_price,earnest_money=proposed.earnest_money,
 contract_date=proposed.contract_date,inspection_deadline=proposed.inspection_deadline,closing_date=proposed.closing_date,actual_close_date=proposed.actual_close_date,
 seller_name=proposed.seller_name,buyer_id=proposed.buyer_id,title_company=proposed.title_company,title_contact=proposed.title_contact,title_phone=proposed.title_phone,
 psa_doc_url=proposed.psa_doc_url,assignment_doc_url=proposed.assignment_doc_url,notes=proposed.notes,assigned_to=proposed.assigned_to
 WHERE id=p_id RETURNING * INTO saved;
 PERFORM public.sync_deal_handoff_tasks(saved);
 RETURN jsonb_build_object('deal',to_jsonb(saved),'reused',false);
END $function$

