CREATE OR REPLACE FUNCTION wholesale_ingest.foreclosure_status_evidence_allowed(p_lead uuid, p_county text, p_url text)
 RETURNS boolean
 LANGUAGE plpgsql
 STABLE
 SET search_path TO ''
AS $function$
DECLARE l public.leads; expected text; host text;
BEGIN
 IF p_url IS NULL OR length(p_url)>2000 OR p_county NOT IN ('Dallas','Collin') THEN RETURN false; END IF;
 SELECT lead.* INTO l FROM public.leads lead JOIN wholesale_ingest.properties p ON p.lead_id=lead.id
 WHERE lead.id=p_lead AND p.county=p_county;
 IF NOT FOUND THEN RETURN false; END IF;
 host:=substring(lower(p_url) from '^https://([^/:?#]+)(?:[/:?#]|$)');
 IF host=ANY(CASE p_county WHEN 'Dallas' THEN ARRAY['www.dallascounty.org','dallas.tx.publicsearch.us']
 ELSE ARRAY['www.collincountytx.gov','collincountytx.gov','apps.collincountytx.gov','apps2.collincountytx.gov'] END) THEN RETURN true; END IF;
 IF nullif(trim(l.property_address),'') IS NULL OR nullif(trim(l.city),'') IS NULL OR coalesce(l.zip_code,'') !~ '^[0-9]{5}(-[0-9]{4})?$' THEN RETURN false; END IF;
 expected:='https://www.xome.com/auctions/'||lower(btrim(regexp_replace(trim(l.property_address),'[^A-Za-z0-9]+','-','g'),'-'))||'-'||
  lower(btrim(regexp_replace(trim(l.city),'[^A-Za-z0-9]+','-','g'),'-'))||'-tx-'||left(l.zip_code,5)||'-';
 RETURN starts_with(p_url,expected) AND substring(p_url from length(expected)+1) ~ '^[0-9]{6,12}$';
END; $function$

CREATE OR REPLACE FUNCTION wholesale_ingest.publish_property_alerts()
 RETURNS integer
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
DECLARE owner_id uuid; d date; total integer; notification uuid; task uuid; added integer:=0; affected integer;
BEGIN
 PERFORM pg_advisory_xact_lock(hashtextextended('county-property-alerts',0));
 SELECT p.id INTO owner_id FROM public.profiles p JOIN public.app_settings a ON a.value=p.id::text
 WHERE a.key='lead_owner_user_id' AND p.status='approved' LIMIT 1;
 IF owner_id IS NULL THEN RETURN 0; END IF;
 FOR d IN SELECT DISTINCT (added_at AT TIME ZONE 'America/Chicago')::date
 FROM wholesale_ingest.property_alert_events WHERE notified_at IS NULL LOOP
  SELECT count(*) INTO total FROM wholesale_ingest.property_alert_events
  WHERE (added_at AT TIME ZONE 'America/Chicago')::date=d;
  SELECT notification_id,task_id INTO notification,task FROM wholesale_ingest.property_alert_days WHERE day=d;
  IF NOT FOUND THEN
   notification:=gen_random_uuid();task:=gen_random_uuid();
   INSERT INTO public.app_notifications(id,recipient_id,type,title,body,action_url,action_label,metadata)
   VALUES(notification,owner_id,'pipeline_step','New county properties added',
    total||' new CRM properties added on '||d||'. Review verification and bulk skip-trace readiness.',
    '/daily-lists','Review new properties',jsonb_build_object('day',d,'property_count',total,'outreach_authorized',false));
   INSERT INTO public.tasks(id,title,description,status,priority,type,assigned_to,due_date)
   VALUES(task,'High priority: new county properties',total||' new CRM properties added on '||d||'. Open Daily Lists for verification and bulk PropStream preparation. Contact returns do not clear calls or SMS.',
    'pending','high','follow_up',owner_id,now());
   INSERT INTO wholesale_ingest.property_alert_days VALUES(d,notification,task);
  ELSE
   UPDATE public.app_notifications SET recipient_id=owner_id,body=total||' new CRM properties added on '||d||'. Review verification and bulk skip-trace readiness.',
    metadata=jsonb_build_object('day',d,'property_count',total,'outreach_authorized',false),read=false,read_at=NULL WHERE id=notification;
   UPDATE public.tasks SET status='pending',assigned_to=owner_id,description=total||' new CRM properties added on '||d||'. Open Daily Lists for verification and bulk PropStream preparation. Contact returns do not clear calls or SMS.' WHERE id=task;
  END IF;
  UPDATE wholesale_ingest.property_alert_events SET notified_at=now()
  WHERE notified_at IS NULL AND (added_at AT TIME ZONE 'America/Chicago')::date=d;
  GET DIAGNOSTICS affected=ROW_COUNT;
  added:=added+affected;
 END LOOP;
 RETURN added;
END $function$

CREATE OR REPLACE FUNCTION wholesale_ingest.queue_property_alert()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
DECLARE owner_id uuid; task_id uuid;
BEGIN
 IF TG_OP='UPDATE' AND OLD.lead_id IS NOT NULL THEN RETURN NEW; END IF;
 IF NEW.lead_id IS NOT NULL THEN
  SELECT assigned_to INTO owner_id FROM public.leads WHERE id=NEW.lead_id FOR UPDATE;
  IF owner_id IS NULL THEN
   SELECT p.id INTO owner_id FROM public.profiles p JOIN public.app_settings a ON a.value=p.id::text
   WHERE a.key='lead_owner_user_id' AND p.status='approved' LIMIT 1;
  END IF;
  IF owner_id IS NULL OR NOT EXISTS(SELECT 1 FROM public.profiles WHERE id=owner_id AND status='approved')
  THEN RAISE EXCEPTION 'Approved county intake owner required'; END IF;
  UPDATE public.leads SET assigned_to=owner_id WHERE id=NEW.lead_id AND assigned_to IS NULL;
  SELECT id INTO task_id FROM public.tasks WHERE lead_id=NEW.lead_id AND type='follow_up'
   AND assigned_to=owner_id ORDER BY id LIMIT 1;
  IF task_id IS NULL THEN
   task_id:=md5('county-intake:'||NEW.lead_id::text)::uuid;
   INSERT INTO public.tasks(id,title,description,status,priority,type,lead_id,assigned_to,due_date)
   VALUES(task_id,'Review newly onboarded county property',
    'Review verified property evidence, existing trace results and current contact permissions in Daily Lists. This task does not authorize outreach.',
    'pending','high','follow_up',NEW.lead_id,owner_id,now()) ON CONFLICT(id) DO NOTHING;
  END IF;
  INSERT INTO wholesale_ingest.property_alert_events(property_id,lead_id) VALUES(NEW.id,NEW.lead_id) ON CONFLICT DO NOTHING;
  PERFORM wholesale_ingest.publish_property_alerts();
 END IF;
 RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION wholesale_ingest.scan_at(p_now timestamp with time zone)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
DECLARE today date:=(p_now AT TIME ZONE 'America/Chicago')::date;
 owner_id uuid; e record; latest wholesale_ingest.ingest_runs; reason text;
 count_batches int; incident wholesale_ingest.monitor_incidents; summary jsonb;
BEGIN
 IF p_now IS NULL THEN RAISE EXCEPTION 'Scan time required'; END IF;
 IF NOT pg_try_advisory_xact_lock(hashtextextended('wholesaleos:list-monitor',0)) THEN RETURN jsonb_build_object('busy',true); END IF;
 SELECT p.id INTO owner_id FROM public.app_settings a JOIN public.profiles p ON p.id::text=a.value
 WHERE a.key='lead_owner_user_id' AND p.status='approved' LIMIT 1;
 -- Recover up to seven missed daily schedules, only after procedure approval.
 INSERT INTO wholesale_ingest.expected_runs(source_id,day,due_at)
 SELECT s.id,d::date,(d::date+s.deadline_local) AT TIME ZONE s.timezone
 FROM wholesale_ingest.sources s CROSS JOIN generate_series(today-7,today,interval '1 day') d
 WHERE s.enabled AND s.procedure_approved_at IS NOT NULL
 AND d::date >= (s.procedure_approved_at AT TIME ZONE s.timezone)::date
 AND wholesale_ingest.collection_due_day(s.collection_cadence,s.cadence_effective_on,d::date)=d::date
 ON CONFLICT DO NOTHING;

 -- Raw expiry never changes an unresolved run into a successful empty run.
 UPDATE wholesale_ingest.ingest_runs i SET
 processing_status=CASE WHEN i.status<>'success' OR EXISTS(SELECT 1 FROM wholesale_ingest.records r WHERE r.run_id=i.id AND r.resolved_at IS NULL) THEN 'review' ELSE 'completed' END,
 completed_at=CASE WHEN i.status='success' AND NOT EXISTS(SELECT 1 FROM wholesale_ingest.records r WHERE r.run_id=i.id AND r.resolved_at IS NULL) THEN coalesce(i.completed_at,p_now) ELSE NULL END
 WHERE i.processing_status<>'completed'
 AND (SELECT count(*) FROM wholesale_ingest.raw_payloads b WHERE b.run_id=i.id)=i.expected_batches
 AND NOT EXISTS(SELECT 1 FROM wholesale_ingest.raw_payloads b WHERE b.run_id=i.id AND (b.batch_index>=i.expected_batches OR b.purged_at IS NOT NULL));
 UPDATE wholesale_ingest.jobs j SET state=CASE WHEN i.processing_status='completed' THEN 'done' ELSE 'review' END
 FROM wholesale_ingest.ingest_runs i WHERE i.id=j.run_id AND i.processing_status IN ('review','completed') AND j.state='pending';

 FOR e IN SELECT x.*,s.source_key,s.collection_cadence,s.cadence_effective_on FROM wholesale_ingest.expected_runs x
 JOIN wholesale_ingest.sources s ON s.id=x.source_id WHERE s.enabled AND x.day<=today
 AND wholesale_ingest.collection_due_day(s.collection_cadence,s.cadence_effective_on,x.day)=x.day
 LOOP
  SELECT * INTO latest FROM wholesale_ingest.ingest_runs i
   WHERE i.source_id=e.source_id AND wholesale_ingest.collection_due_day(e.collection_cadence,e.cadence_effective_on,i.scheduled_for)=e.day
   ORDER BY i.received_at DESC,i.id DESC LIMIT 1;
  SELECT count(*) INTO count_batches FROM wholesale_ingest.raw_payloads WHERE run_id=latest.id;
  reason:=NULL;
  IF latest.id IS NULL THEN
   IF e.due_at<=p_now THEN reason:='missing'; END IF;
  ELSIF latest.status<>'success' THEN reason:=latest.status;
  ELSIF count_batches<>latest.expected_batches THEN
   IF e.due_at<=p_now THEN reason:='incomplete'; END IF;
  ELSIF latest.processing_status='review' THEN reason:='property_review';
  END IF;
  IF reason IS NOT NULL THEN
   INSERT INTO wholesale_ingest.monitor_incidents(source_id,day,kind,run_id,first_seen_at,last_seen_at)
   VALUES(e.source_id,e.day,reason,latest.id,p_now,p_now)
   ON CONFLICT(source_id,day) DO UPDATE SET kind=excluded.kind,run_id=excluded.run_id,last_seen_at=p_now,resolved_at=NULL
   RETURNING * INTO incident;
   IF owner_id IS NOT NULL AND incident.task_id IS NULL THEN
    incident.task_id:=gen_random_uuid();
    INSERT INTO public.tasks(id,title,description,status,priority,type,assigned_to,due_date)
    VALUES(incident.task_id,'Daily list needs review',e.source_key||' ('||e.day||'): '||reason||'. Check collection and delivery; never infer zero records from incomplete coverage.','pending','high','follow_up',owner_id,p_now);
    UPDATE wholesale_ingest.monitor_incidents SET task_id=incident.task_id WHERE source_id=e.source_id AND day=e.day;
    UPDATE wholesale_ingest.expected_runs SET alert_task_id=incident.task_id WHERE source_id=e.source_id AND day=e.day;
   ELSIF incident.task_id IS NOT NULL THEN
    UPDATE public.tasks SET description=e.source_key||' ('||e.day||'): '||reason||'. Review the current receipt; no seller outreach was sent.',status='pending'
    WHERE id=incident.task_id;
   END IF;
  ELSIF latest.id IS NOT NULL AND count_batches=latest.expected_batches AND latest.processing_status='completed' THEN
   UPDATE wholesale_ingest.monitor_incidents SET resolved_at=coalesce(resolved_at,p_now),last_seen_at=p_now WHERE source_id=e.source_id AND day=e.day;
   -- Keep the assigned task for operator acknowledgement; do not silently close it.
  END IF;
 END LOOP;

 SELECT jsonb_build_object('day',today,'owner_configured',owner_id IS NOT NULL,
 'sources',(SELECT coalesce(jsonb_agg(jsonb_build_object('source_key',s.source_key,'enabled',s.enabled,'due_at',x.due_at,'status',coalesce(i.status,'not_received'),'processing_status',i.processing_status,'run_id',i.id,'status_reason',i.status_reason,'expected_batches',i.expected_batches,'received_batches',(SELECT count(*) FROM wholesale_ingest.raw_payloads b WHERE b.run_id=i.id),'records_in',(SELECT coalesce(sum(b.records_in),0) FROM wholesale_ingest.raw_payloads b WHERE b.run_id=i.id)) ORDER BY s.source_key),'[]')
 FROM wholesale_ingest.sources s LEFT JOIN wholesale_ingest.expected_runs x ON x.source_id=s.id AND x.day=wholesale_ingest.collection_due_day(s.collection_cadence,s.cadence_effective_on,today)
 LEFT JOIN LATERAL (SELECT r.* FROM wholesale_ingest.ingest_runs r WHERE r.source_id=s.id AND wholesale_ingest.collection_due_day(s.collection_cadence,s.cadence_effective_on,r.scheduled_for)=wholesale_ingest.collection_due_day(s.collection_cadence,s.cadence_effective_on,today) ORDER BY r.received_at DESC,r.id DESC LIMIT 1) i ON true),
 'new_leads',(SELECT coalesce(sum(records_new),0) FROM wholesale_ingest.ingest_runs WHERE scheduled_for=today),
 'stacked_records',(SELECT coalesce(sum(records_stacked),0) FROM wholesale_ingest.ingest_runs WHERE scheduled_for=today),
 'open_incidents',(SELECT coalesce(jsonb_agg(to_jsonb(m) ORDER BY day,source_id),'[]') FROM wholesale_ingest.monitor_incidents m WHERE resolved_at IS NULL),
 'top_ten',(SELECT coalesce(jsonb_agg(to_jsonb(t) ORDER BY t.score DESC,t.created_at DESC,t.lead_id),'[]') FROM (SELECT latest_score.* FROM (SELECT DISTINCT ON (l.lead_id) l.lead_id,l.score,l.reasons,l.flags,l.route,l.created_at FROM wholesale_ingest.lead_evaluations l ORDER BY l.lead_id,l.created_at DESC,l.id DESC) latest_score WHERE score IS NOT NULL ORDER BY score DESC,created_at DESC,lead_id LIMIT 10) t)) INTO summary;
 -- Rank only stored evaluations; no model invocation or outreach from monitoring.
 INSERT INTO wholesale_ingest.daily_digests(day,generated_at,status,summary) VALUES(today,p_now,'generated',summary)
 ON CONFLICT(day) DO UPDATE SET generated_at=p_now,summary=excluded.summary;

 -- Retention is an explicit maintenance action. Monitoring never deletes intake evidence or contacts.
 RETURN summary;
END; $function$

CREATE OR REPLACE FUNCTION wholesale_ingest.scan_scoring_at(p_now timestamp with time zone)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
DECLARE owner_id uuid; job wholesale_ingest.scoring_jobs; kind text; incident wholesale_ingest.scoring_incidents;
BEGIN
 IF p_now IS NULL THEN RAISE EXCEPTION 'Scan time required'; END IF;
 IF NOT pg_try_advisory_xact_lock(hashtextextended('wholesaleos:scoring-monitor',0)) THEN RETURN jsonb_build_object('busy',true); END IF;
 SELECT p.id INTO owner_id FROM public.app_settings a JOIN public.profiles p ON p.id::text=a.value
 WHERE a.key='lead_owner_user_id' AND p.status='approved' LIMIT 1;
 FOR job IN SELECT * FROM wholesale_ingest.scoring_jobs
 WHERE state='review' OR (state='queued' AND created_at+interval '60 minutes'<=p_now)
 OR (state='submitted' AND claimed_at+interval '15 minutes'<=p_now)
 OR (state='received' AND received_at+interval '15 minutes'<=p_now) LOOP
  kind:=CASE job.state WHEN 'submitted' THEN 'model_outcome_unknown' WHEN 'received' THEN 'receipt_completion_overdue'
   WHEN 'queued' THEN 'scoring_queue_overdue' ELSE 'scoring_evidence_review' END;
  INSERT INTO wholesale_ingest.scoring_incidents(job_id,kind,first_seen_at,last_seen_at)
  VALUES(job.id,kind,p_now,p_now) ON CONFLICT(job_id) DO UPDATE SET kind=excluded.kind,last_seen_at=p_now,resolved_at=NULL
  RETURNING * INTO incident;
  IF incident.task_id IS NULL AND owner_id IS NOT NULL THEN
   incident.task_id:=gen_random_uuid();
   INSERT INTO public.tasks(id,title,description,status,priority,type,assigned_to,due_date)
   VALUES(incident.task_id,'List scoring needs review',kind||'. Scoring job '||job.id::text||'; lead '||job.lead_id::text||'. Inspect saved model evidence. Do not repeat an uncertain model call.','pending','high','follow_up',owner_id,p_now);
   UPDATE wholesale_ingest.scoring_incidents SET task_id=incident.task_id WHERE job_id=job.id;
  ELSIF incident.task_id IS NOT NULL THEN
   UPDATE public.tasks SET status='pending',description=kind||'. Scoring job '||job.id::text||'; lead '||job.lead_id::text||'. Inspect saved model evidence. Do not repeat an uncertain model call.' WHERE id=incident.task_id;
  END IF;
 END LOOP;
 UPDATE wholesale_ingest.scoring_incidents i SET resolved_at=coalesce(i.resolved_at,p_now),last_seen_at=p_now
 FROM wholesale_ingest.scoring_jobs j WHERE j.id=i.job_id AND j.state IN ('completed','obsolete') AND i.resolved_at IS NULL;
 RETURN jsonb_build_object('owner_configured',owner_id IS NOT NULL,
 'open_incidents',(SELECT coalesce(jsonb_agg(to_jsonb(i) ORDER BY first_seen_at,job_id),'[]') FROM wholesale_ingest.scoring_incidents i WHERE resolved_at IS NULL));
END $function$

CREATE OR REPLACE FUNCTION wholesale_ingest.supervise_bulk_pipeline()
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
DECLARE result jsonb; reason text; owner_id uuid; task uuid; stamp timestamptz:=now();
BEGIN
 IF NOT pg_try_advisory_xact_lock(hashtextextended('bulk-supervision-v1',0)) THEN
  RETURN jsonb_build_object('busy',true);
 END IF;
 -- Hold expiry-bearing tables through the guard and scan. The legacy scan contains
 -- retention deletes; this scheduler must never reach those with expired records.
 LOCK TABLE wholesale_ingest.raw_payloads,wholesale_ingest.contacts IN SHARE ROW EXCLUSIVE MODE;
 IF EXISTS(SELECT 1 FROM wholesale_ingest.raw_payloads WHERE expires_at<=stamp)
 OR EXISTS(SELECT 1 FROM wholesale_ingest.contacts WHERE expires_at<=stamp) THEN
  reason:='retention_review_required';
 ELSE
  BEGIN
   result:=public.scan_list_pipeline();
   IF result->>'busy'='true' THEN RETURN result; END IF;
   IF result IS NULL OR result->>'owner_configured' IS DISTINCT FROM 'true' THEN
    reason:='owner_not_configured';
   END IF;
  EXCEPTION WHEN OTHERS THEN
   -- Subtransaction rolls back partial scan changes; no raw error/PII in task text.
   reason:='scan_error_'||SQLSTATE;
  END;
 END IF;
 SELECT id INTO owner_id FROM public.profiles WHERE status='approved'
 AND id::text=(SELECT value FROM public.app_settings WHERE key='lead_owner_user_id' LIMIT 1);
 SELECT task_id INTO task FROM wholesale_ingest.bulk_supervision WHERE singleton;
 IF reason IS NOT NULL AND owner_id IS NOT NULL THEN
  IF task IS NULL THEN
   task:=gen_random_uuid();
   INSERT INTO public.tasks(id,title,description,status,priority,type,assigned_to,due_date)
   VALUES(task,'Bulk workflow needs attention',reason,'pending','high','follow_up',owner_id,stamp);
  ELSE
   UPDATE public.tasks SET description=reason,status='pending',assigned_to=owner_id WHERE id=task;
  END IF;
 END IF;
 INSERT INTO wholesale_ingest.bulk_supervision(singleton,checked_at,successful_at,attempts,state,reason,summary,task_id)
 VALUES(true,stamp,CASE WHEN reason IS NULL THEN stamp END,1,CASE WHEN reason IS NULL THEN 'healthy' ELSE 'blocked' END,
 reason,coalesce(result,'{}'),task)
 ON CONFLICT(singleton) DO UPDATE SET checked_at=excluded.checked_at,
 successful_at=coalesce(excluded.successful_at,bulk_supervision.successful_at),attempts=bulk_supervision.attempts+1,
 state=excluded.state,reason=excluded.reason,summary=excluded.summary,task_id=excluded.task_id;
 RETURN jsonb_build_object('supervision',CASE WHEN reason IS NULL THEN 'healthy' ELSE 'blocked' END,
 'reason',reason,'checked_at',stamp,'collection_executed',false,'provider_ordered',false,'outreach_sent',false);
END $function$
